Ceviri.ekle("uk","olay",{
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Похід Барбаросси в Північному Егеї: узяття Скіроса та Північних Спорад", "20ab688e"], "d": ["Дорогою до Превези флот один за одним прийняв капітуляцію островів Північного Егею, які після завоювання Стамбула віддалися під захист Венеції. Так під османське управління перейшли Скірос на північ від Евбеї та Скіатос, Скопелос і Алонісос, що тримали вхід до Салонікської затоки. Ці острови закрили останню північноегейську прогалину, яка, хоч Евбею взяли 1470 року, ще шістдесят вісім років залишалася в руках Венеції.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Захоплення Адена та приєднання єменського узбережжя", "e7d46d8f"], "d": ["Флот, який вирушив із Суеца в індійський похід, спершу повернув до єменського узбережжя, бо не можна було виходити в океан, не убезпечивши Червоного моря. Хадим Сулейман-паша 3 серпня 1538 року ввійшов у порт Адена; тахіридського правителя Аміра ібн Дауда, який схилявся до португальців, викликали на адміральський корабель і стратили, а в місті залишили залогу з 500 осіб. Під час того самого походу прийняли також капітуляцію Мохи та островів Камаран і Фарасан, що панували над протокою, і було закладено основу Єменського бейлербейліку. Так Османська держава вперше заволоділа всім північним узбережжям Баб-ель-Мандебу; Сані ж і внутрішнім областям довелося чекати ще дев'ять років.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Молдовський похід і анексія краю Буджак (Бендери)", "90a88a56"], "d": ["Під час походу проти молдовського господаря Петра Рареша, який не виконував своїх зобов'язань перед османами, захопили Сучаву, а місто Ясси розграбував кримський хан Сахіб Ґерай. Султан поставив господарем Штефана Лакусту (Штефана Сарану) і приєднав безпосередньо до османських земель край Буджак (Південну Бессарабію) разом із Бендерами. Ця анексія стала однією з ланок, які перетворили північно-західне узбережжя Чорного моря на османське внутрішнє море. Молдова вже була підвладним османам господарством; цей похід не відібрав землю в іноземної держави, а лише забрав у господаря внутрішнє управління Бендерами та Буджаком і підпорядкував їх безпосередньо султанові; решта господарства зберегла васальний статус. Така сама будова повторювалася 1484 року в Кілії та Аккермані й 1713 року в Хотині: прикордонні фортеці — під прямою владою, внутрішні землі — васальні.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Передача Навпліона за договором", "104d0937"], "d": ["Війна з Венецією, що тривала три роки після Превези, закінчилася тим, що республіка погодилася залишити свої дві останні фортеці в Мореї. Навпліон і Монемвасію, яких не вдалося взяти облогою, разом із трьомастами тисячами дукатів воєнної контрибуції передали османам за столом переговорів. Так півострів Морея став єдиним цілим, де не залишилося жодного венеційського сліду.", "4a26ee03"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Завоювання Валпо, Шиклоша та Печа", "2ca030a3"], "d": ["Першою метою угорського походу, вирушеного через два роки після приєднання Буди, було убезпечити південне крило нового еялету між Дравою та Дунаєм. Після взяття фортець Валпо та Шиклош здався Печ, центр Барані. Місто стало найлюднішим і найбільш розбудованим центром османської Угорщини, а історик Ібрагім Печеві дістав від нього своє прізвисько.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Завоювання Естерґома та Секешфегервара", "efca9e05"], "d": ["Під час угорського походу, в який Законодавець вирушив особисто, після двотижневої з половиною облоги Естерґом, релігійний центр Угорського королівства та архієпископське місто, перейшов під османське управління. Потім взяли й Секешфегервар, місто коронації угорських королів, завершивши оборонний пояс Будинської провінції. Естерґом залишатиметься в османських руках як ключова фортеця дунайської лінії до 1595 року.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Північний і західний пояс оборони Буди: Вац, Гатван і Шимонторня", "733ee5ce"], "d": ["Після взяття Естерґома та Секешфегервара будинський бейлербей, щоб доповнити кільце фортець навколо столиці, почав діяти без походу самого падишаха. Вац у коліні Дунаю, Гатван — брама Альфельда — та Шимонторня на лінії Шіо здалися одна за одною. Здобутки цього тихого року перетворили Буду з прикордонного міста на центр еялету, що протримався сто сорок років.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Приєднання Басри та вихід до Перської затоки", "02f87c11"], "d": ["Під час завоювання Багдада (1534) правитель Басри Рашид ібн Мегаміс заявив Сулейманові Законодавцю про покору, а 1538 року надіслав ключі від міста. Коли його наступник шейх Ях'я виступив проти османів, багдадський бейлербей Аяс-паша рушив суходолом, а санджакбей Мосула — Євфратом зі 120 суднами; 26 грудня 1545 року Аяс-паша ввійшов до Басри, і місто стало центром бейлербейліку. Цей порт у гирлі Шатт-ель-Арабу був дверима, через які османи вийшли в затоку, що її Португалія контролювала з Ормуза; Амасійським договором 1555 року це становище визнав і Іран.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Завоювання Сани та внутрішнього Ємену", "d31ded85"], "d": ["Після Таїза взяли й Сану, і всю країну підпорядкували бейлербейлікові. Проте через стрімкий рельєф і відмінність мазгабів це панування ніколи не було спокійним; Ємен став для османів фронтом, що безперервно поглинав вояків.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Завоювання Таїза", "d4509df9"], "d": ["У Ємені, де дев'ять років перед тим задовольнилися прибережною смугою, через дедалі більше посилення зейдитських імамів у гірських внутрішніх областях сили Оздеміра-паші піднялися на нагір'я та захопили Таїз.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Стамбульський договір — п'ятирічний мир із Габсбургами", "41f81773"], "d": ["Між османами та Габсбургами підписали мир терміном на п'ять років; Фердинанд погодився платити щорічно 30 000 дукатів за угорські землі, які утримував. Договір юридично закріпив фактичний стан розділеної на три частини Угорщини. Убезпечення таким чином західного фронту дало Законодавцеві змогу організувати нові походи проти Ірану.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Другий іранський похід і повторне взяття Тебріза", "e82365df"], "d": ["У поході, розпочатому на спонуку Елькаса-мірзи, брата шаха Тахмаспа, який повстав проти нього та знайшов притулок у Стамбулі, військо вдруге ввійшло до Тебріза. Оскільки Сефевіди знову не вступили в польову битву й відійшли, випалюючи землю, у місті вдалося пробути лише кілька тижнів. Цей похід остаточно довів, що Тебріз неможливо втримати, і спрямував османську стратегію на створення тривалої прикордонної лінії, тобто на укріплення Вана.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Завоювання Вана та закріплення східного кордону", "fc8f930b"], "d": ["Фортеця Ван, обложена на зворотному шляху з Тебріза, завдяки своєму розташуванню на скелі над східним берегом озера була безперечним ключем області й здалася після короткої облоги. Місто одразу зробили центром бейлербейліку; до нього приєднали санджаки Ерджіш, Аділджеваз і Хаккярі. На відміну від Тебріза, Ван утримали, і чотириста років він залишався найвисунутішою тривалою османською позицією на сході.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Приєднання Аль-Ахси та Катіфа — аравійське узбережжя затоки", "f6701e60"], "d": ["Після взяття Басри захопили Катіф, який став на західному узбережжі затоки передовим постом Португалії, і разом з оазами Аль-Ахса у внутрішній частині створили новий бейлербейлік. Саме звідси вирушали операції проти Бахрейну та Ормуза. Так Османська держава здобула вагомий голос одночасно і на червономорському узбережжі Аравійського півострова, і на узбережжі Перської затоки.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Втрата Шахрезура — ерделанський бей Сухраб схилився до Сефевідів", "5600efc9"], "d": ["Округа Шахрезур, яка під час походу в обидва Іраки (1535) визнала османське управління, перебувала під владою ерделанського еміра Біґе-бея, що сидів у фортеці Залм. Після смерті Біґе-бея 1550 року його брат Сухраб, захопивши фортецю Залм і опанувавши бейлік, повернувся до Сефевідів і вийшов із покори османам; так округа Шахрезур вийшла з-під османського впливу. Область вдалося повернути лише під час нахічеванського походу, коли 1554 року обложили та взяли фортецю Залм.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Взяття Ардагана та басейну Чилдира", "14c9eb76"], "d": ["Ерзурумський бейлербей під час війни з Сефевідами рушив на землі грузинських атабегів у дузі Кури та підпорядкував османському управлінню Ардаган і околиці Чилдира. Так лінія Карс — Ардаган стала єдиною, а нагір'я на північному сході, що відкривали шлях до Грузії, взяли під контроль. Остаточний адміністративний устрій області завершив Чилдирський еялет, створений через двадцять сім років.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Соколлу Мехмед-паша переходить Дунай — початок трансильванської війни", "38fde931"], "d": ["Через смуту, спричинену ченцем Мартінуцці, опікуном малолітнього трансильванського короля Яноша Жиґмонда, і передачу Трансильванією банатських фортець Фердинандові визнали за потрібне новий похід; командування доручили румелійському бейлербеєві Соколлу Мехмед-паші. Попри спроби Мартінуцці тягнути час, військо перейшло Дунай, узяло Бече, Бечкерек, Чанад і Ліппу; проте облогу Темешвара 16 листопада зняли через холоди. Так в Угорщині почалася нова османсько-габсбурзька війна.", "85071c5e"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Сили, вислані з Темешвара, займають паланки Південного Банату — Вершець, Харам, Кевє", "edca0921"], "d": ["Після здачі Темешвара османському війську загони, відокремлені від армії облоги, рушили на малі паланки Банату; за розповіддю Банлакі, ці сили зайняли паланки Вершець, Фачет, Мехадія, Чаковар, Харамвар і Кевє. Так до рук османів перейшов і Харам на березі Дунаю.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Завоювання Солнока та невдала облога Егера", "a7156e8f"], "d": ["Дві османські армії, які об'єдналися після взяття Темешвара, захопили Солнок на Тисі майже без бою, бо наймана залога залишила фортецю. Натомість обложену після того фортецю Егер не вдалося взяти перед тридцятивосьмиденним опором двотисячної залоги під командуванням Іштвана Добо, і з настанням зими військо відійшло. Те, що в тому самому поході одна фортеця легко впала, а друга вистояла, було першою явною ознакою того, що кордон в Угорщині вже не просувається сам собою на користь османів.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Османсько-французький союз — французький флот переходить під османське командування", "a8e01b22"], "d": ["За угодою від 1 лютого 1553 року французький флот передали під командування османського флоту; передбачалися спільні дії проти Іспанії в Західному Середземномор'ї. Після угоди 15 червня 1553 року Тургут-реїс вирушив із сорока п'ятьма галерами в похід на підтримку Франції. Це був перший офіційний союзний договір, який перевів торговельну основу капітуляцій 1536 року у воєнну співпрацю.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Страта царевича Мустафи в Ереглі біля Коньї", "dec36858"], "d": ["Царевич Мустафа, увійшовши до батьківського намету, щоб приєднатися до війська, зібраного для нахічеванського походу, у мить, коли мав постати перед султаном, натрапив на катів і був задушений. Убивство спадкоємця престолу, якого дуже любили у війську, викликало серед яничарів глибокий гнів, і Рюстем-пашу усунули з посади великого візира. Ця подія увійшла в літературу та народну пам'ять як один із найсуперечливіших зламів османської політики щодо царевичів.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Перенесення нубійського кордону на південь до Ібрима", "c57d5d77"], "d": ["Південний кордон Єгипетського бейлербейліку перенесли за другий поріг, коли Оздемір-бей укріпив фортецю Ібрим, що здіймається на скелястому мисі над Нілом, і Нижню Нубію повністю приєднали до османського Єгипту. (Османську адміністративну організацію в Ібримі встановили після завоювання Єгипту; на карті Ібрим позначено османським з 1517 року. Цей рік приблизний, джерело року не подає.) Фортеця була і загатою від набігів із Нубії, і пунктом контролю над шляхом золота та рабів до Сеннара. Розміщений тут боснійський гарнізонний загін виявився таким тривким, що його нащадки перебували у фортеці ще через триста років. Джерела подають дві різні розповіді про час переходу Ібрима під османське управління: стаття TDV про Судан пов'язує приєднання Нижньої Нубії до османського Єгипту з операцією Оздеміра-паші в середині XVI століття, а стаття про Нубію пише, що область аж до долини Хальфи та адміністративна організація в Ібримі були встановлені одразу після завоювання 1517 року. Санджак Ібрим 26 липня 1573 року приєднали до еялету Хабеш.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Відвоювання Беджаї (Бужі) в іспанців", "49691cda"], "d": ["Беджая, яка сорок три роки перебувала в руках Іспанії та розділяла надвоє узбережжя між Алжиром і Константиною, здалася після облоги з суходолу та з моря. З падінням фортеці узбережжя Алжирського оджаку стало безперервним аж до Орана. В Іспанії ця втрата викликала таке обурення, що командувача Алонсо де Перальту, який здав фортецю, стратили на батьківщині.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Приєднання Зейли до еялету Хабеш", "7bbf369a"], "d": ["На південному краю еялету Хабеш порт Зейла на африканському узбережжі Аденської затоки підпорядкували османському управлінню. Це місто, брама султанату Адал до моря, було останнім пунктом постачання для кораблів, що виходили за межі Баб-ель-Мандебу. З приєднанням Зейли кордон Османської держави в Африці сягнув своєї найпівденнішої точки.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Битва царевичів під Коньєю", "1c8de387"], "d": ["Царевич Баязид, вступивши в боротьбу за престол, із військом близько 30 000 людей підійшов під Конью та у дводенній битві зазнав поразки від свого брата царевича Селіма. Розгромлений Баязид через Амасью втік до Ірану, під захист шаха Тахмаспа. Ця битва перетворила кризу престолоспадкування в останні роки Законодавця на зовнішньополітичну проблему.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Морська перемога під Джербою", "c7b905c1"], "d": ["Османський флот під командуванням Піяле-паші маневром розділення надвоє розсіяв біля Джерби союзну іспансько-генуезько-мальтійську ескадру, зібрану для повернення Триполі. Союзники втратили більшу частину свого флоту, а фортеця на острові невдовзі впала. Джербу вважають другою великою морською перемогою після Превези, яка закріпила османську перевагу в Середземномор'ї.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Страта царевича Баязида в Казвіні", "a759de14"], "d": ["Царевича Баязида, який шукав притулку в Ірані, внаслідок тривалих перемовин шах Тахмасп видав османському посольству, і його задушили разом із чотирма синами. В обмін на видачу Сефевіди отримали значні матеріальні поступки та гарантію кордону. Цією стратою усунули останню перешкоду на шляху Селіма II до престолу та зберегли мирний порядок Амасійського договору.", "cf625eb3"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Єменське повстання та єменський похід Коджа Сінан-паші", "c8218d8e"], "d": ["Зейдитський імам аль-Мутаххар повстав під приводом насильницького стягнення податків і вирвав більшу частину Ємену з-під османського управління. Коджа Сінан-паша, відправлений зі Стамбула, операціями 1568–1570 років, узявши після тривалої облоги Каукабан, відновив османську владу в краї. Похід мав життєво важливе значення для збереження контролю над південною брамою Червоного моря та торговельним шляхом в Індійський океан.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Оборонний союз із султанатом Ачех і допомога в Індійському океані", "8e835f24"], "d": ["Ачехські посли, які просили в Законодавця допомоги проти португальських нападів, після смерті султана під Сігетваром засвідчили свою вірність Селімові II, і з ним підписали оборонну угоду. Султан наказав відправити з Александрії гармати, рушниці, боєприпаси та майстрів; для відрядження в індійські води підготували сімнадцять воєнних кораблів. Розростання єменського повстання не дало ескадрі вирушити, але османські гармаші та майстри, які дісталися Ачеху, залишили в краї тривкий слід.", "65c41562"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Завоювання Нікосії", "413d866b"], "d": ["Після облоги, що почалася 25 липня 1570 року й тривала сорок п'ять днів, Нікосія, столиця венеціанського Кіпру, здалася османському війську. Падіння центру острова затиснуло венеціанський опір у фортеці Фамагуста. Це завоювання викликало на Заході великий відгук і прискорило процес, що привів до створення флоту Священної ліги під проводом папи.", "1ef832d4"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Відбудова флоту після Лепанто", "db51fe44"], "d": ["Першою справою Килич Алі-паші, призначеного капудан-пашею після поразки під Лепанто, стало відновлення флоту, який зазнав тяжких втрат; корабельні працювали без перерви всю зиму 1571–1572 років. У червні 1572 року в Середземне море вийшла нова ескадра приблизно з 250 галер і 300 галер добровольців-реїсів. Це швидке відновлення показало, що Лепанто не змогло назавжди зламати османську морську силу.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Стамбульський договір із Венецією — визнання Кіпру", "4d08ef50"], "d": ["Венеція, залишившись наодинці після розпаду Священної ліги, уклала окремий мир з османами, офіційно визнала, що Кіпр належить османам, і погодилася сплатити воєнну контрибуцію. Договір ясно показав, що перемога під Лепанто не принесла християнському світові політичної вигоди. Після цього Венеція сімдесят років уникатиме прямої війни з османами.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Смерть Селіма II", "c289f5ee"], "d": ["Селім II, який після падіння близько двох місяців не міг виходити на диван, помер. Його смерть дванадцять днів тримали в палаці в таємниці, доки старший син Мурад не прибув із Маніси до Стамбула. Щодо дня смерті джерела розходяться: Селяникі називає 15 грудня; Ґерлах, Мехмед бін Мехмед і Дженабі — 13 грудня.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Оголошення про смерть Селіма II та сходження на престол Мурада III", "84334d70"], "d": ["22 грудня 1574 року офіційно оголосили про смерть Селіма II та сходження на престол Мурада III, якого привезли з Маніси. Новий султан пробуде на престолі двадцять один рік, і його правління пам'ятатимуть тривалими іранськими війнами на Сході, переддень Довгої війни на Заході та псуванням акче всередині держави. До смерті Соколлу Мехмед-паші 1579 року в управлінні державою тривав старий порядок.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Битва на Ваді аль-Махазін (Алькасер-Кібір) — Абд аль-Малік за підтримки османів знищив португальське військо", "21280dac"], "d": ["Абд аль-Малік, який за османської підтримки посів марокканський престол, знищив на Ваді аль-Махазін велике військо португальського короля Себастьяна; оскільки в битві загинуло одразу три володарі, у західних джерелах її називають «Битвою трьох королів». Військова могутність Португалії зруйнувалася, і невдовзі країна перейшла до рук Іспанії. Абд аль-Малік також загинув у битві; брат Ахмад аль-Мансур, що став його наступником, повідомив Стамбул про перемогу через посольство. Відносини двох держав залишилися на рівні обміну послами та дарами, а не данини чи васалітету, і невдовзі загострилися через питання дарів.", "0ddf3962"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Завоювання Біхача", "651a7275"], "d": ["Боснійський бейлербей Теллі Хасан-паша, узявши в листопаді 1591 року Ріпач, передову фортецю Біхача, 1592 року захопив і саме місто з фортецею; після десятиденної облоги комендант Ламберг здався. Це завоювання просунуло боснійський кордон уздовж річки Уна й стало останнім великим османським здобутком напередодні Довгої війни, яка вибухне через рік із загибеллю Теллі Хасан-паші під Сисаком (Кулпою).", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Початок османсько-австрійської «Довгої війни»", "bd22c392"], "d": ["Після того як боснійський бейлербей Теллі Хасан-паша зазнав поразки під Сисаком (Кулпою) та загинув, Османська держава оголосила Австрії війну, і почалася Довга війна, яка триватиме тринадцять років. Ця війна, в якій вирішальну роль відігравала піхота з вогнепальною зброєю, прискорила залучення до османського війська сеґбанів і рушничників і поглибила занепад тімарних сипахіїв. Війна скінчиться 1606 року Житваторокським договором.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Коджа Сінан-паша вирушив в австрійський похід — перший похід Довгої війни", "d4a2f46d"], "d": ["Після того як боснійський бейлербей Хасан-паша зазнав поразки під Сисаком та загинув, великий візир Коджа Сінан-паша пишними словами та обіцянками схилив султана до війни та вирушив у похід із 12 000 яничарів та іншими частинами. Так почався перший похід османсько-австрійської війни, яка триватиме тринадцять років.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Завоювання Яниккале (Дьєра)", "14b75207"], "d": ["Великий візир Коджа Сінан-паша після облоги, що тривала понад місяць, прийняв капітуляцію Яниккале, який вважали замком на шляху до Відня. Падіння фортеці викликало в Європі велику паніку й стало найяскравішим османським здобутком у Довгій війні. Проте фортецю вдасться утримати лише чотири роки.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Смерть Мурада III", "1b62e886"], "d": ["Після двадцятиодного року правління Мурад III помер у ті дні, коли волоське військо спалило Бреїлу та дійшло до Сілістри, і був похований у некрополі Святої Софії. Його син Мехмед III, викликаний із Маніси, через десять днів прибув до Стамбула й зійшов на престол (27 січня 1595 р.).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Втрата Естерґома на користь Австрії", "f420d333"], "d": ["Залога Естерґома, не отримавши достатньої допомоги під час облоги, якою керував Карл фон Мансфельд, здала фортецю ерцгерцогу Маттіасу. Із кінцем п'ятдесятидворічного османського панування оборонний ланцюг на дунайській лінії було розірвано, і Буда опинилася під прямою загрозою. Фортецю вдасться повернути лише через десять років, 1605-го.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Завоювання Егерської фортеці", "3e511629"], "d": ["Після тритижневої боротьби могутня Егерська фортеця, яку османи раніше ніяк не могли взяти, впала після капітуляції залоги. Це завоювання, під час якого султан був присутній особисто, певною мірою відновило бойовий дух, підірваний втратою Естерґома, і було створено Егерську провінцію. Разом із перемогою під Мезьокерестешем (Хачова), здобутою через два тижні, 1596 рік став найуспішнішим для османів роком Довгої війни.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Втрата Яниккале (Дьєра)", "b4ccc679"], "d": ["Частини під командуванням Міклоша Палффі та Адольфа фон Шварценберга раптовим нападом, підірвавши ворота фортеці, повернули Яниккале. Втрата фортеці, яку чотири роки тому ціною великих зусиль здобув Коджа Сінан-паша, зруйнувала османську передову лінію в Угорщині. Хоча того самого року ворожі сили, що обложили Буду, відбили, співвідношення у війні дедалі більше перетворювалося на війну на виснаження.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Повстання Караязиджи Абдулхаліма", "30493b0d"], "d": ["Караязиджи Абдулхалім, зібравши сеґбанів і левендів, які втекли з війська під час Довгої війни, узяв під контроль широкий край у Центральній Анатолії, захопив Урфську фортецю (листопад 1599 р.), проголосив себе султаном під титулом «Халім-шах» і розсилав фірмани з власною тугрою. Караязиджи, якого вважають першим проводирем великої джелялійської хвилі, помер 1602 року, а його рух продовжив брат Делі Хасан. Це повстання є початком доби «великої втечі», коли анатолійські селяни масово покидали свою землю.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Оборона Каніжі Тір'які Хасан-пашею", "d56a5e6a"], "d": ["Ерцгерцог Фердинанд і його союзники, прагнучи повернути Каніжу, завойовану рік тому, облягали фортецю понад два місяці; Тір'які Хасан-паша зі своїм загоном у 9000 людей чинив опір. Хоча допомоги ззовні він не отримав, він відбивав загальні штурми й вилазками змусив ворога відступити з тяжкими втратами. Ця оборона в османській історіографії стала легендою, а «Каніжська облога» — окремим літературним жанром.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Смерть Мехмеда III та сходження на престол Ахмеда I", "da735fde"], "d": ["Після смерті Мехмеда III 20 грудня на престол зійшов його чотирнадцятирічний син Ахмед I. Те, що він став першим султаном, який посів престол у дитячому віці, не побувавши намісником у санджаку, свідчить, що практика виховання царевичів у провінції фактично припинилася. За правління Ахмеда I від братовбивства відмовляться й перейдуть до принципу «екберієт» (на престол сходить найстарший чоловік роду).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Повернення Естерґома", "7330f273"], "d": ["Великий візир Лала Мехмед-паша обложив Естерґом, утрачений десять років тому, і знову повернув його під османське управління. Під час того самого походу визволили також Пешт і Вац, і османи зміцнили свою лінію в Угорщині. Цей успіх дав змогу наступного року сісти за стіл перемовин у Житватороку з відносно сильної позиції; Естерґом залишатиметься в османських руках до 1683 року.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Перемога на Орудж-Овасі та придушення повстання Джанболатоглу", "30f93532"], "d": ["Джанболатоглу Алі-пашу, який створив в Алеппо незалежний бейлик і шукав союзу з Тосканою, великий візир Куюджу Мурад-паша тяжко розгромив на рівнині Орудж-Овасі. З відновленням центральної влади в Сирії було зламано найнебезпечнішу гілку джелялійської хвилі. Нещадна дворічна чистка Куюджу Мурад-паші хоч тимчасово, але забезпечила порядок в Анатолії.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Перемога під Алачайиром і придушення повстання Календероглу", "55db0485"], "d": ["Джелялійського проводиря Календероглу, який обклав даниною краї Маніси та Бурси, Куюджу Мурад-паша розгромив під Алачайиром, і той мусив утікати до Ірану. Цією перемогою розсіяли останню з великих джелялійських армій в Анатолії. Жорстока чистка Куюджу Мурад-паші, про яку переказують, що він наповнював викопані за його наказом колодязі тілами страчених бунтівників, хоч і забезпечила порядок на короткий час, не змогла відшкодувати втрат населення та виробництва в Анатолії.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Надання першої ахіднаме Нідерландам", "5d9d117e"], "d": ["Корнеліс Гага, посол Республіки Об'єднаних провінцій Нідерландів, зумів отримати від Ахмеда I ахіднаме того самого обсягу, що й надані Франції та Англії. Так Нідерланди здобули право відкрити посольство в Стамбулі, консульства в османських портах і торгувати під власним прапором. Ця ахіднаме символізує вихід на османський ринок північних морських держав, які заступили Венецію в середземноморській торгівлі.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Смерть Ахмеда I та сходження на престол Мустафи I — принцип екберієту", "9901c09e"], "d": ["Після шлункової хвороби, що тривала п'ятдесят один день, двадцятивосьмирічний Ахмед I помер, і на престол замість його сина посадили брата Мустафу I. Так відмовилися від спадкування від батька до сина й фактично перейшли до системи «екберієт», за якою на престол сходить найстарший чоловік династії. Це перше правління, що тривало дев'яносто шість днів, є також початком доби, коли царевичів виховували в «клітці» (кафес).", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Усунення Мустафи I та сходження на престол Генч Османа (Османа II)", "e0f552f2"], "d": ["Мустафу I під приводом того, що він психічно нездоровий, через дев'яносто шість днів усунули з престолу, і султаном став чотирнадцятирічний син Ахмеда I Осман II. За свідченням, що спирається на Хасанбейзаде, вплив на це рішення про усунення мав головний чорний євнух (кизлар-агаси) Мустафа-ага. Генч Османа з його задумом скасувати яничарський корпус і створити нове військо вважають першою радикальною постаттю в османських дискусіях про реформи. Через чотири роки цей задум коштуватиме йому життя.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Серавський договір — поновлення миру з Іраном", "e778aca8"], "d": ["Серавський договір, укладений з Іраном після поразки під Пуль-і Шикасте, значною мірою підтвердив умови договору Насух-паші 1612 року; щорічну кількість шовку, яку мали надсилати Сефевіди, зменшили з двохсот в'юків до ста. Так закрився другий етап східних війн, що тривали з 1603 року. Мир буде недовгим: із втратою Багдада 1623 року війна спалахне знову.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Хотинський похід і Хотинський договір", "bc4c823c"], "d": ["Укріплений табір, який Ходкевич розбив під Хотином, не змогло здолати велике військо, яким особисто командував Осман II, і багатомісячні штурми не дали результату. За договором, підписаним 9 жовтня, кордоном визнали річку Дністер, а поляки зобов'язалися перешкоджати козацьким набігам. Похід, який, хоч і подавали як перемогу, не дав результату, посилив недовіру молодого султана до яничарів і його намір ліквідувати корпус.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Друге усунення Мустафи I та сходження на престол Мурада IV", "1b3a9e74"], "d": ["Мустафу I, якого після вбивства Османа II посадили на престол удруге, через один рік і три місяці знову усунули, і султаном проголосили одинадцятирічного Мурада IV. Перші дев'ять років державою фактично управляли його мати Кесем-султан і придворні сановники. З 1632 року Мурад IV особисто візьме управління в свої руки та почне добу суворої централізації.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Втрата Багдада на користь Сефевідів", "db81be0c"], "d": ["Унаслідок перемовин, які Бекір-субаши, що повстав у Багдаді, вів із Сефевідами, його син Дервіш Мехмед, який обороняв внутрішню цитадель, здав місто силам шаха Аббаса. Втрата одного з міст-символів халіфатської спадщини та більшої частини Іраку викликала в Стамбулі велике обурення. Повернення Багдада на п'ятнадцять років стане єдиною метою османської східної політики.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Придушення повстання Абаза Мехмед-паші з центром в Ерзурумі", "e6da2729"], "d": ["Ерзурумський бейлербей Абаза Мехмед-паша, який повстав проти яничарів під приводом помсти за вбивство Османа II, роками тримав під контролем Східну Анатолію та чинив опір центру. Після облоги Ерзурума великим візиром Хюсрев-пашею він мусив здатися, був помилуваний і призначений до Боснії. Кінець повстання був передумовою того, щоб Мурад IV зміг вирушити в похід проти Ірану.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Перша страта шейх-уль-іслама: Ахізаде Хюсейн-ефенді", "a60a58c5"], "d": ["Шейх-уль-іслама Ахізаде Хюсейна-ефенді стратили поблизу Бюйюкчекмедже, мотивуючи це тим, що він посередничав під час військових заворушень і надіслав султанові письмове застереження щодо порядку судочинства. Те, що він став першим стратеним османським шейх-уль-ісламом, зламало давню традицію, за якою найтяжчим покаранням для представників ільміє було вигнання. Цю подію вважають символом дедалі суворішої влади Мурада IV та порушення рівноваги між державою та улемами.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Завоювання Ревана (Єревана) Мурадом IV", "b65a9b73"], "d": ["Мурад IV, вирушивши зі Стамбула 28 березня 1635 року, 28–29 липня обложив Реван (Єреван) і 8 серпня прийняв капітуляцію фортеці; потім увійшов до спорожнілого Тебріза й наказав зруйнувати місто. На честь перемоги султан наказав звести в палаці Топкапи Реванський павільйон. Цей похід був першою великою східною операцією після тридцятирічної перерви, під час якої султан особисто командував військом.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Втрата Ревана на користь Сефевідів", "fbb8dd25"], "d": ["Після відходу османського війська сили шаха Сефі обложили Реван і за вісім місяців повернули його. Те, що фортецю так швидко втратили, показало, наскільки логістично важким було тривке панування на Кавказі. Реван залишать за Іраном і за договором у Касре-Ширіні 1639 року, а османи відмовляться від претензій на Азербайджан.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Повторне завоювання Багдада", "4d2f27f3"], "d": ["Мурад IV, вийшовши зі Стамбула 8 травня 1638 року, після запеклої сорокаденної облоги повернув Багдад, який п'ятнадцять років був у руках Сефевідів; під час облоги загинув візир Тайяр Мехмед-паша. Із завоюванням міста в Іраку відновили османське управління, а султан отримав титул «Завойовник Багдада». Завоювання, закріплене договором у Касре-Ширіні наступного року, заклало основу нинішнього турецько-іранського кордону.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Смерть Мурада IV та сходження на престол султана Ібрагіма", "e2ca1ca0"], "d": ["Після Мурада IV, який помер у віці двадцяти семи років (за хіджрою — двадцяти восьми), на престол зійшов його брат Ібрагім, єдиний живий чоловік династії. За правління нового султана, який роками жив у «клітці», палацові витрати та боротьба за вплив у палаці похитнули державний порядок. Через вісім років, коли його усунуть і вб'ють, в османській історії станеться друге вбивство султана.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Повернення Азовської фортеці від козаків", "e5fcf160"], "d": ["Азовську фортецю, яку 1637 року захопили донські козаки, залишили перед спільною операцією Султанзаде Мехмед-паші та кримського хана Мехмеда IV Ґерая; козаки відійшли, підпаливши фортецю. Повернення північної брами Чорного моря поклало край небезпечній добі, коли козацькі набіги сягали самого Босфору. 1696 року фортецю втратять — цього разу на користь російського царя Петра I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Початок критського походу та завоювання Ханьї", "a1b0c77f"], "d": ["Під приводом того, що мальтійські корсари напали на османський паломницький корабель і сховалися на Криті, Венеції оголосили війну, і флот під командуванням Юсуф-паші висадив війська на острів. Після п'ятдесятичотириденної облоги фортецю Ханья взяли й створили на Криті першу тривку османську базу. Так почалася найдовша в османській історії війна; повністю острів зможуть завоювати лише через двадцять чотири роки, 1669-го.", "2809708a"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Втрата Кліса на користь Венеції", "5473c22c"], "d": ["На далматинському фронті критської (кандійської) війни контрнаступ венеціанського командувача Леонардо Фосколо охопив і Кліс, який із 1537 року був центром санджаку; фортеця перейшла до Венеції. Те, що османи зосередили всі сили на Криті, унеможливило повернення цієї втрати на далматинському кордоні — Кліс більше ніколи не повернеться під османське управління; центр санджаку перенесли до Лівно.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Початок облоги Кандії", "13016b10"], "d": ["Після взяття Ханьї та Ретимно османське військо обложило Кандію, останню велику опору Венеції на острові. Ця блокада, яка триватиме двадцять один рік, увійшла в історію як одна з найдовших облог у світовій воєнній історії. Під час облоги спроби венеціанського флоту перекрити Дарданелли перенесуть війну в самісіньке серце Егеїди.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Убивство великої валіде Кесем-султан", "9d763f79"], "d": ["Кесем-султан, якій було близько шістдесяти двох років, знайшли в одній із кімнат гарему та вбили башлала Узун Сулейман-ага та його люди, які діяли за наказом Турхан-султан, матері Мехмеда IV. Смерть цієї могутньої жінки династії, яка спрямовувала державну політику за правління трьох султанів, вважають фактичним кінцем доби, званої «жіночим султанатом». Влада, що звільнилася, через п'ять років відкрила шлях Кьопрюлю Мехмед-паші до посади великого візира з надзвичайними повноваженнями.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Дарданельська поразка та втрата Бозджаади й Лемносу", "e01a1f7e"], "d": ["Велика морська перемога, яку венеціанський адмірал Моченіго здобув біля Дарданелл у червні 1656 року, майже повністю знищила османський флот; потім окупували Бозджааду, Лемнос і Самотраку. Коли протока опинилася під венеціанською блокадою, ціни на харчі в Стамбулі різко зросли й поширився страх нападу на столицю. Ця катастрофа стала безпосередньою причиною того, що у вересні 1656 року Кьопрюлю Мехмед-пашу призначили великим візиром на певних умовах і з надзвичайними повноваженнями.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Дарданельська перемога та повернення Бозджаади", "603da863"], "d": ["Флот, мобілізований Кьопрюлю Мехмед-пашею, 19 липня 1657 року розгромив венеціанську ескадру перед протокою; потім сили під командуванням Курд-паші 25 серпня повернули Бозджааду, а 30 серпня венеціанці повністю залишили острів. У листопаді визволили також Лемнос, дарданельську блокаду прорвали, і шлях постачання Стамбула знову відкрився. Кьопрюлю особисто прибув на острів і наказав відремонтувати укріплення; цей успіх є першим великим воєнним здобутком доби Кьопрюлю.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Завоювання Йєнє (Інеу) та трансильванський похід", "d1089616"], "d": ["Кьопрюлю Мехмед-паша, вирушивши в похід, щоб покарати трансильванського князя Дєрдя II Ракоці, який без дозволу пішов походом на Польщу, порушивши османську опіку, пройшов через Белград і взяв стратегічну фортецю Йєнє (Янова). У Трансильванії призначили нового князя, суворо нагадавши про васальний зв'язок. Цей похід був першою ланкою спроби османів відновити свою владу в Центральній Європі. Трансильванія вже була підвладним османам князівством; взяття Йєнє було не завоюванням в іноземної держави, а виведенням цієї фортеці васальної Трансильванії з-під князівського управління та прямим приєднанням до османського санджаку; решта князівства зберегла васальний статус.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Придушення повстання Абаза Хасан-паші", "4ba74321"], "d": ["Абаза Хасан-паша, який проти суворих чисток Кьопрюлю Мехмед-паші заручився підтримкою анатолійських бейлербеїв та аг сеґбанів, почав велике повстання з вимогою усунути великого візира. Повстання придушили в Алеппо, а його призвідців знищили; це був останній колективний опір провінційних пашів центру. Так влада Кьопрюлю стала беззаперечною, а посада великого візира знову піднеслася до рівня справжнього виконавчого центру держави.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Завоювання Варада (Орадя)", "0e6ad300"], "d": ["У межах походу проти трансильванського князя Дєрдя II Ракоці, який оголосив османам війну, взяли фортецю та місто Варад. Із падінням однієї з ключових фортець Трансильванії в краї створили нову османську провінцію (Варадську провінцію). Це завоювання стривожило Габсбургів і стало однією з прямих причин османсько-австрійської війни, яка почнеться через три роки. Інші місця, приєднані того самого дня: Варад. І тут землю не було відібрано в іноземної держави: Трансильванія вже була васальним османським князівством; перетворення Варада на провінцію лише вивело управління цим містом із васального князівства та підпорядкувало його безпосередньо султанові, так само як два роки тому в Йєнє.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Битва під Сен-Готардом", "61ebc1f2"], "d": ["Османські сили, переправившись через річку Раабу, були зупинені союзним європейським військом під командуванням Монтекукколі й зазнали тяжких втрат. У воєнній історії цю битву вважають переломною, бо вона вперше ясно показала перевагу вогню дисциплінованої піхоти з вогнепальною зброєю над османською кінною атакою. Попри поразку, у Вашварському договорі, підписаному через дев'ять днів, османи зуміли здобути вигідні умови.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Вашварський договір", "089c978c"], "d": ["Договір, підписаний попри поразку під Сен-Готардом, постановив, що Уйвар і Варад залишаються за османами, Трансильванія лишається нейтральною під османською опікою, а Австрія сплачує «подарунок» у 200 000 курушів. Цей двадцятирічний мир є одним із рідкісних прикладів, коли сторона, що програла війну, перемогла за столом перемовин. Невдоволення, викликане договором у габсбурзькій громадській думці, живитиме середньоугорський рух і опосередковано — віденський похід 1683 року.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Початок правління деїв в Алжирі", "e99faa51"], "d": ["Алжирський оджак і таїфе-і реїс (корпорація капітанів-корсарів) змістили останнього агу та обрали деєм Хаджі Мехмеда довічно. Відтоді Алжиром правив не призначений зі Стамбула бейлербей, а дей, якого місцевий оджак обирав із власного середовища; османський зв'язок обмежувався згадуванням імені султана в хутбі та обов'язками, пов'язаними зі стягом і участю в походах. Так Алжир перетворився з еялету на оджаклик — такого самого перетворення зазнали Туніс 1705 року за Хусейнідів і Триполітанія 1711 року за Караманли.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Почався польський похід — Мехмед IV і Фазиль Ахмед-паша на чолі війська", "75e15a39"], "d": ["Коли тривали польські напади на українського гетьмана Петра Дорошенка, який перейшов під османську опіку, Стамбул зажадав від польського короля припинити напади; не діставши прихильної відповіді, вирішили йти походом на Польщу. 4 червня 1672 року великий візир Фазиль Ахмед-паша з військом, при якому був і султан, вирушив на Польщу. Похід завершиться завоюванням Кам'янця та Бучацьким договором.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Завоювання Кам'янця та створення Подільської провінції", "c3f4f6d0"], "d": ["Після дев'ятиденної облоги здався Кам'янець, який вважали найпотужнішою фортецею Польщі на сході; 2 вересня Мехмед IV здійснив першу п'ятничну молитву в мечеті, перетвореній із кафедрального собору. Зробивши фортецю центром, створили Подільську провінцію, і османський прапор сягнув своєї найпівнічнішої точки на землях нинішньої України. Кам'янець залишатиметься північно-західним краєм імперії до Карловицького миру 1699 року.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Кара Мустафа-паша прийняв капітуляцію Умані від Польщі", "0d3543a0"], "d": ["Кара Мустафа-паша, відправлений проти Польщі, прийняв капітуляцію Умані, однієї з фортець, які утримувала Польща; місто залишалося під османським управлінням до Карловицького миру.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Завоювання Чигиринської фортеці", "a17cedd0"], "d": ["Після операції, в якій Мелек Ібрагім-паша минулого року не досяг успіху, великий візир Мерзіфонлу Кара Мустафа-паша, особисто командуючи, обложив укріплену Чигиринську фортецю (19/21 липня) і 21 серпня захопив її. Падіння фортеці, яка була символом османсько-російського суперництва за козацький гетьманат в Україні, змусило Росію шукати миру. Цей успіх став також одним із джерел самовпевненості, з якою Мерзіфонлу поверне на Відень.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Бахчисарайський договір — перший офіційний мир із Росією", "df82bc0b"], "d": ["Унаслідок перемовин, які після чигиринських походів велися за посередництва кримського хана, між Османською державою та Росією підписали двадцятирічний мир, а кордоном визнали річку Дніпро (Озю). Як перший всеосяжний договір між двома державами його вважають початковим документом османсько-російських відносин. Завдяки миру східний фронт убезпечили, і військо змогли спрямувати до Центральної Європи.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Вручення Імре Текелі берата на середньоугорське королівство", "3cd8d51d"], "d": ["Протестантського угорського шляхтича Імре Текелі, який повстав проти габсбурзького тиску, з квітня 1682 року почали вважати «обраним королем Середньої Угорщини», а 16 вересня будинський бейлербей Ібрагім-паша вручив йому знаки князівської влади. Так під османською опікою створили нову васальну угорську державу. Це втручання зробило війну з Австрією неминучою й запустило ланцюг подій, що привів наступного року до другої облоги Відня.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Втрата Лефкади (Аямаври) на користь Венеції", "e6905fee"], "d": ["Флот Венеції, яка приєдналася до Священної ліги, обстрілявши місто з гармат, окупував острів Лефкада в Іонічному морі. Коли того самого року впала й Превеза, османський контроль на вході в Адріатику було зламано. Ці втрати стали початковими кроками операції, під час якої Морозіні за три роки захопить усю Морею.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Втрата Корона на користь Венеції", "2ed762bc"], "d": ["Венеціанські сили під командуванням Морозіні захопили фортецю Корон на південно-західному краю півострова Морея; відтоді місто тридцять років залишатиметься під венеціанським управлінням. Падіння Корона стало першим великим здобутком венеціанської операції із завоювання Мореї. Фортецю повернуло лише 1715 року османське військо під командуванням Сіляхдар Алі-паші.", "506cf83e"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Відбиття венеціанської облоги Евбеї (Еґрібоза)", "aae7e6a0"], "d": ["Морозіні, який, захопивши Морею, повернув на Егеїду, понад три місяці облогою намагався взяти Евбею; проте перед укріпленнями, посиленими взимку 1687–1688 років, і опором залоги мусив відступити з тяжкими втратами. Ця невдача зупинила венеціанське просування в Егеїді та похитнула воєнний авторитет Морозіні. Евбея залишиться в османських руках і за Карловицьким миром.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Втрата Каніжської фортеці на користь Австрії", "553b45f3"], "d": ["Каніжа, яка з січня 1690 року перебувала в щільній блокаді габсбурзького війська чисельністю 60 000 людей, місяцями чинила опір без допомоги, а потім була втрачена за угодою про капітуляцію, яку підписав останній комендант Мустафа-паша. Так у фортеці, яку пам'ятають за легендарною обороною Тір'які Хасан-паші, скінчилося дев'яностолітнє османське панування. Втрата Каніжі стала крахом останньої великої опори османів у Західній Угорщині.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Сходження на престол Ахмеда II", "52947b14"], "d": ["Після смерті Сулеймана II на престол в Едірне зійшов його сорокадев'ятирічний брат Ахмед II. Його правління припало на найтяжчі роки воєн зі Священною лігою; через два місяці після сходження на престол під Сланкаменом загинув великий візир Фазиль Мустафа-паша. Натомість запроваджена за його доби система малікяне стала одним із найважливіших заходів, що змінили довгострокову структуру османських фінансів.", "d3441b14"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Захоплення Басри іранцями", "a9cdf3a3"], "d": ["Поки Османська держава на заході була зайнята війнами зі Священною лігою, Басра після чуми 1690 року зазнала пограбування спершу від мунтафіцького шейха Мані, а потім від хана Хувейзи Фераджуллаха. Скориставшись цим безладом, іранці 1696 року захопили місто й залишили в Басрі свого намісника-охоронця.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Стамбульський договір — Азов залишено Росії", "79db4724"], "d": ["У Карловиці з Росією вдалося укласти лише дворічне перемир'я; тривкий мир підписали в Стамбулі після складних перемовин, що тривали півтора року. Османська держава офіційно віддала Росії Азовську фортецю, втрачену 1696 року, та землі довкола неї й відмовилася від щорічної данини, яку кримський хан одержував від Москви. Натомість Росія здобула право мати в Стамбулі постійного посла; так російську присутність на північному узбережжі Чорного моря було юридично закріплено.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Повернення Курни та Басри Далтабаном Мустафою-пашею", "7adb777d"], "d": ["Далтабан Мустафа-паша, призначений після Карловицького миру намісником Багдада та сераскером Басри, рушив на південь із силами Алеппо, Ракки, Сіваса та Карамана та з річковою флотилією, що спустилася з Біреджика. Шейхи навколишніх племен один за одним скорилися, іранський охоронець Басри Давуд-хан залишив місто, і Курна та Басра знову перейшли під османське управління.", "60abbe06"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Початок кюлеменського (мамлюцького) правління в Багдаді", "abe52618"], "d": ["Із призначенням намісником Багдада Хасан-паші грузинського походження в Іраку почалася доба, коли замість намісників, призначуваних центром, панувала верства правителів, вирощених із їхніх власних рабів. З намісництвом Сулейман-паші 1749 року система остаточно вкоренилася, і Висока Порта вже мусила призначати не того, кого хотіла, а одного з мамлюків, які здобули вплив. Ця напівавтономна структура, хоч і була корисною для оборони іранського кордону, на півтора століття послабила контроль центральної влади над Іраком.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Заснування династії Хусейнідів у Тунісі", "cb1a98f9"], "d": ["У вакуумі влади, що виник після вторгнення алжирських сил у Туніс, ага сипахіїв турецького походження Хусейн ібн Алі захопив бейлик і здобув легітимність, заявивши про вірність османському султанові. Заснована ним династія правила Тунісом у 1705–1735 та 1756–1957 роках; правління оджаку заступив порядок бейлику, що передавався від батька до сина. Так з'явився перший приклад підпорядкованих центрові, але фактично автономних династичних структур у західних оджаках.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Відвоювання Орана (Вахрана) та Мерс-ель-Кебіра в іспанців", "b67ce06a"], "d": ["Сили бейлербея Алжирського оджаку після тривалої облоги захопили Оран, який два століття був у руках іспанського гарнізону, та його порт Мерс-ель-Кебір. Це був найбільший успіх, здобутий у боротьбі з Іспанією західними оджаками під османською опікою в Західному Середземномор'ї, і він убезпечив західний фланг Алжиру. 1732 року місто знову окупують іспанці, а остаточно його повернуть лише 1792 року.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Прутський договір — повернення Азова та Таганрога", "bac5d2a1"], "d": ["Договір із семи статей, підписаний після капітуляції російського війська, оточеного на берегах Пруту, постановив повернути османам Азовську фортецю разом із її землями та боєприпасами. Укріплення Таганрога, Кам'янки та Єні-Кале мали зруйнувати, і сторони не повинні були будувати в цих краях нові фортеці. Система флоту та баз, яку Петро I шістнадцять років будував у Воронежі та Азові, розвалилася; вихід Росії до Чорного моря затримався приблизно на п'ятдесят років.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Заснування династії Караманли в Триполітанії", "e1105d4a"], "d": ["У Триполітанії, виснаженій чварами аг оджаку, кавалерійський офіцер Ахмед Караманли захопив управління та узаконив своє становище бератом на бейлербейство, отриманим зі Стамбула. Через Ахмед-пашу, його сина Мехмед-пашу та онука Юсуф-пашу виникла династія, що тривала з 1711 до 1835 року; постала напівнезалежна структура, яка створила власний флот і укладала договори безпосередньо з європейськими державами. Ця доба скінчиться лише 1835 року, коли провінцію безпосередньо підпорядкують центрові.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Адріанопольський (Едірнський) договір із Росією", "14901a70"], "d": ["Через невиконання обіцянок, даних на Пруті, війну оголошували ще двічі, і зрештою, коли росіяни прийняли зобов'язання, в Едірне підписали тривкий мир. Договір підтвердив прутські умови; Росія не повинна була втручатися в польські справи, мала відійти з козацьких земель і не перешкоджати поверненню на батьківщину шведського короля Карла XII, прозваного «Залізною головою» (Демірбаш Шарл). Закриття таким чином північного фронту дало Османській державі змогу повернутися обличчям до морейсько-венеціанського фронту. Інші місця, приєднані того самого дня: Хотин.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Оголошення війни Венеції — підготовка морейського походу", "d970b122"], "d": ["У Дивані ухвалили рішення про війну, мотивуючи це тим, що Венеція підтримує чорногорських повстанців, захоплює османські торговельні кораблі та гнітить тяжкими податками Морею, яку здобула в Карловиці. Похід, підготовлений великим візиром Сіляхдар Дамад Алі-пашею, наступного року завершиться поверненням усього півострова Морея менш ніж за сто днів. Проте цей успіх приведе в рух Австрію та 1716 року відчинить двері значно тяжчій війні.", "ef2edb5f"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Австрія та Венеція уклали союз — брама османсько-австрійської війни 1716–1718 років", "99511ca2"], "d": ["Після того як османи повернули Морею від Венеції, Австрія, заявивши, що Карловицький мир порушено, підписала з Венецією союзний договір; принц Євгеній у листі до великого візира зажадав повернути місця, забрані у Венеції. На нараді в Давутпашинському таборі під тиском великого візира Алі-паші Австрії оголосили війну й отримали на це фетву від шейх-уль-іслама.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Великий візир Алі-паша вирушив в австрійський похід", "2fbdce42"], "d": ["Після оголошення війни Австрії сердар-і екрем Алі-паша вирушив в австрійський похід із військом понад 100 000 людей; флот того самого літа повернув на Корфу. Військо рушить із Белграда на Петроварадин, а на початку серпня під час розгрому великий візир загине.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Поразка під Петроварадином (Варадином) — загибель Дамад Алі-паші", "265c1d81"], "d": ["Османське військо, переправившись через Дунай через Белград, зустрілося під Петроварадином з австрійськими силами під командуванням принца Євгенія; хоча в першому натиску атака яничарів потіснила ворожі шанці, з крахом кавалерійського крила лави розсипалися. Великого візира Сіляхдар Дамад Алі-пашу вбила куля в чоло, а табір і артилерійський обоз повністю дісталися ворогові. Ця поразка, яку османські літописи згадують як «рік Варадина», стала першою ланкою ланцюга, що привів до втрати Темешвара, а наступного року — Белграда.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Облога Корфу завершується невдачею", "b2aa7011"], "d": ["Морейський сераскер Кара Мустафа-паша з суходолу, а капудан-паша Джанім Ходжа Мехмед-паша з флотом із моря натиснули на Корфу; острів був ключовою базою Венеції в Адріатиці. Однак надзвичайно потужні укріплення фортеці, підкріплення, доставлені венеціанським флотом, і звістки про поразку на дунайському фронті призвели до зняття облоги. Те, що Корфу не вдалося взяти, згасило піднесення, викликане повторним завоюванням Мореї, і перемістило центр ваги війни до Угорщини.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Втрата Темешвара на користь Австрії", "27fe1365"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Здача фортеці Харам (Єні-Паланка) Австрії — втрачено дунайське узбережжя Банату", "38ee4c6d"], "d": ["Після падіння Темешвара австрійський генерал кавалерії Мерсі, якому доручили зайняти решту Банату, 14 листопада рушив на Харам (Єні-Паланку) на березі Дунаю; коли 16 листопада він підійшов до фортеці, османський гарнізон із 200 осіб підняв білий прапор і здався за умови вільного виходу. Так до Австрії перейшла й дунайська лінія Південного Банату, яка перебувала в руках османів з 1552 року. Інше поселення, яке того самого дня в атласі переходить від османів до Габсбургів: Вершець — він іде за ланцюгом головного центру Харама (Bánlaky 0019/1703; задекларована приблизність).", "5b54ecb0"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Східний похід: узяття Тбілісі та початок війни з Іраном", "78343dc2"], "d": ["Коли держава Сефевідів розвалилася внаслідок афганської навали, а Росія вийшла на узбережжя Каспію, Османська держава відрядила військо на схід, щоб ця порожнеча не опинилася повністю під російським впливом. Було захоплено Тбілісі, і Грузію приєднано до османського управління; потім просування тривало в напрямку Гянджі, Ревана та Нахічевані. Цей похід, що відбувався за миролюбним фасадом Доби тюльпанів, став початком тривалої східної авантюри, яка мала тривати тринадцять років і закінчитися поверненням усього здобутого.", "5c412d91"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Стамбульський договір про поділ — поділ Ірану з Росією", "fce8eec2"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Захоплення Тебріза — оволодіння Азербайджаном", "e502a4f7"], "d": ["Після невдалої спроби роком раніше Тебріз знову взяли в облогу, і після запеклих боїв за кожну вулицю місто здалося османському війську. Під османське управління перейшли також залежні від Тебрізького еялету Меренд, Мераге та Совукбулак (Мехабад). Того самого року, взявши ще Лорі, Гянджу, Ардебіль і Хоррамабад, османи фактично окупували області, які за Стамбульським договором про поділ відійшли їм. Ці досягнуті на сході межі були найдальшими з часів договору Ферхад-паші, проте їх утримання стало важким тягарем для війська та скарбниці.", "e0953563"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Хамаданський договір — приєднання Західного Ірану до Османської держави", "94a29dc3"], "d": ["Договір, підписаний з афганським правителем Ашраф-шахом, поклав край чотирирічній війні й юридично визнав за Османською державою окуповані нею землі Західного Ірану. Натомість Ашраф-шах визнав халіфство османського падишаха та зобов'язався, щоб в Ірані хутбу читали від імені падишаха. Ця дипломатична перемога виявилася недовговічною: контрнаступ, який Надір-шах розпочав 1730 року, за кілька років змів усі здобутки договору.", "fd0174b9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Договір Ахмед-паші — повернення більшої частини Західного Ірану", "590d839f"], "d": ["Після перемоги Надір-шаха під Малаєром і низки іранських наступів багдадський намісник Ахмед-паша підписав мирний текст, не порадившись із центральною владою. За договором кордоном визнавалася річка Аракс; міста Західного Ірану, як-от Хамадан, Керманшах, Ардалан, Ардебіль і Тебріз, поверталися Ірану, а Гянджа й Тбілісі залишалися в османів. Цей текст, зустрінутий у Стамбулі з обуренням, Надір-шах теж уважав недостатнім, і ще до кінця 1732 року війна спалахнула знову. Атлас уважає, що того самого дня від османів до Сефевідів перейшов і Котур, який іде за ланцюгом Хоя (TDV hoy; окремої дати для Котура в джерелі немає — задекларована приблизність).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Повторна втрата Орана на користь Іспанії", "20485027"], "d": ["Великий десантний флот, посланий королем Іспанії Філіпом V під командуванням графа Монтемара, підійшов до Орана, розгромив сили Алжирського оджаку та повернув місто. Порт, завойований двадцять чотири роки перед тим, знову на шістдесят років опинився в руках іспанського гарнізону. Цю втрату, яка показала межі могутності західних оджаків у Західному Середземномор'ї, вдалося надолужити лише 1792 року остаточним завоюванням Орана.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Реформа корпусу бомбардирів за європейським зразком і заснування Хумбарахане", "d980cf2a"], "d": ["Француз за походженням Хумбараджи Ахмед-паша, який вступив на османську службу, за підтримки великого візира Хекімоглу Алі-паші перетворив корпус бомбардирів на підрозділ із платнею, організований на європейський лад. Триста вояків, набраних у Боснії, здобували регулярну освіту, засновану на арифметиці та геометрії; було складено нові статути щодо організації, спорядження та пенсій, за тогочасною технікою виготовлено сто мортир і п'ятдесят тисяч бомб. Хумбарахане, де викладали геометрію, вважають першим осередком сучасної військово-інженерної освіти в Османській державі.", "181b7161"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Стамбульський договір — поступка Південного Кавказу Ірану", "8c205aab"], "d": ["Друга іранська війна, що тривала чотири роки, закінчилася договором, укладеним після поразки на Арпачаї та втрати Гянджі й Тбілісі. Османська держава відійшла з усіх земель Південного Кавказу та Західного Ірану, захоплених із 1723 року, а кордон повернувся на лінію Касре-Ширінського договору 1639 року. Після тринадцяти років східних походів залишилися важкий фінансовий тягар і спорожніла скарбниця; натомість закриття східного фронту було життєво важливим здобутком з огляду на нову війну з Росією.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Падіння фортеці Очаків (Озі) під натиском росіян", "f93e61f3"], "d": ["Російське військо під командуванням фельдмаршала Мініха обложило фортецю Очаків у гирлі Дніпра; після вибуху порохового складу оборона розвалилася, і фортеця впала з великими людськими втратами. Втрата Очакова, який уважали ключем до північно-західного узбережжя Чорного моря, відкрила росіянам дорогу на Крим і спричинила в Стамбулі велику паніку. Наступного року через епідемію та труднощі постачання росіяни залишили фортецю, і вона знову перейшла до османів.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Перемога під Баня-Лукою — порятунок Боснії", "f603865a"], "d": ["Коли австрійські війська вступили до Боснії та обложили Баня-Луку, боснійський намісник Хекімоглу Алі-паша прийшов на допомогу з силами, зібраними з місцевого населення, і завдав чисельно переважному ворогові тяжкої поразки. Ця перемога з першого ж кроку зруйнувала австрійський план окупації Боснії, і північ еялету було повністю повернуто. Баня-Лука стала одним із переломних моментів, що підняли бойовий дух османського війська, яке після 1683 року безперервно відступало перед Австрією.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Перемога під Хісарджиком (Ґроцкою) — відкриття дороги на Белград", "2101cdff"], "d": ["Австрійське військо, що йшло боронити Белград, потрапило в засідку у вузькій тіснині на березі Дунаю та в битві, яка тривала цілий день, зазнало важких втрат. Поки сили фельдмаршала Валліса безладно відступали до Белграда, османське військо підійшло до фортеці й розпочало облогу. Хісарджик був найпереконливішою перемогою в польовій битві над Австрією з часів Карловицького миру й безпосередньо забезпечив повернення Белграда.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Нішський договір — мир із Росією, нейтралізація Азова та припинення кримських набігів", "674f974e"], "d": ["Росія, яка залишилася сама після того, як Австрія в Белграді погодилася на мир, була змушена закінчити війну за посередництва французького посла Вільнева. Укріплення фортеці Азов зруйнували, а цю місцевість оголосили нейтральною землею між двома державами; Росія прийняла умову не тримати на Чорному морі ні військових, ні торгових кораблів. Так мету Росії вийти до моря було відкладено ще на покоління, а Османська держава востаннє у XVIII столітті встала з-за столу переговорів із виграшем.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Очаків повернувся після російської окупації: за миром 1739 року фортецю передано після зруйнування", "7ecc2bef"], "d": ["Росіяни взяли Очаків 11 липня 1737 року. За миром, укладеним із Росією 1739 року, фортецю після зруйнування її укріплень знову передали османам; османи утримували Очаків до 1788 року, ще до Ясського договору.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Оборона Мосула — відсіч Надір-шахові", "c03ffbc1"], "d": ["Узявши Кіркук та Ербіль і підійшовши до Мосула, Надір-шах сорок днів обстрілював місто з гармат і влаштовував один за одним загальні штурми. Оборона, яку очолив намісник Хусейн-паша аль-Джалілі, озброївши також міщан, змусила іранське військо з важкими втратами зняти облогу. Те, що Мосул вистояв, запобігло втраті всього Іраку та на ціле століття зміцнило вплив родини Джалілі в місті.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Дір'їйський союз — заснування першого Саудівського емірату в Неджді", "188751bf"], "d": ["Емір Мухаммад ібн Сауд, який узяв під свій захист у Дір'ї вигнаного з Уяйни богослова Мухаммада ібн Абд аль-Ваххаба, уклав із ним союз, що ставив політичну владу на службу релігійному заклику. Ця угода розпочала для роду Саудів нову історію та об'єднала розпорошені оазові емірати Неджду навколо єдиного руху. Ця сила, яка за пів століття сягнула Кербели, Мекки та Медини, змусила Османську державу боронити своє панування в Хіджазі.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Керденський договір — кінець османсько-іранських воєн", "1d3a919e"], "d": ["Договір, укладений після останньої чотирирічної війни, без змін поновив Касре-Ширінський кордон 1639 року; жодна зі сторін не здобула територій. Наполегливу вимогу Надір-шаха визнати джафаризм п'ятим мазгабом залишили без задоволення, натомість домовилися, що іранські паломники зможуть вільно здійснювати хадж і що сторони обміняються послами. Так фактично завершилися османсько-іранські війни, що тривали понад два століття; цей кордон донині великою мірою зберігся.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Смерть Махмуда I і сходження на престол Османа III", "30203700"], "d": ["Махмуд I, який за двадцять чотири роки правління повернув за Белградським договором утрачені землі та підтримував реформу корпусу бомбардирів, помер, повертаючись із п'ятничного селямлику. Його наступником став брат, Осман III, який до п'ятдесяти восьми років жив у кафесі. Почалося коротке й неспокійне правління: за доби Османа III, який за три роки змінив шість великих візирів, у державних справах запанував помітний застій.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Смерть Османа III і сходження на престол Мустафи III", "3ac10f85"], "d": ["Після смерті Османа III, який правив три роки, на престол зійшов Мустафа III, відкритий до ідей реформ і уважний до державних справ. Новий падишах, спираючись на досвід великого візира Коджа Раґиба-паші, намагався виправити фінанси та оновити військо; за цієї доби було створено корпус скорострільної артилерії барона де Тотта. Проте війна з Росією, у яку вступили 1768 року, затьмарила всі здобутки сімнадцятирічного правління.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Оголошення війни Росії — балтський інцидент і початок війни 1768–1774 років", "9c6aabe0"], "d": ["Коли російські й козацькі загони, переслідуючи учасників Барської конфедерації в Речі Посполитій, напали на містечко Балту на османському кордоні та спалили його, диван ухвалив рішення про війну, а російського посла ув'язнили в Єдикуле. Війна, у яку вступили без серйозної військової підготовки й оголосили за шість місяців наперед, пішла погано із самого початку. Ця шестирічна боротьба з Чесменським погромом флоту, поразкою під Кагулом і окупацією Криму перетворилася на одну з найтяжчих низок поразок в османській історії.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Втрата Хотинської фортеці на користь росіян", "66d43ea4"], "d": ["Хоча дві спроби російського війська під командуванням князя Голіцина було відбито, після поразки великого візира між Кам'янцем і Хотином військо відступило, а залога покинула фортецю. Втрата без опору найсильнішого османського укріплення на північ від Дунаю відчинила росіянам ворота Волощини та Молдавії. Обидва князівства окупували того самого року; Хотин вдалося повернути лише 1774 року за Кючук-Кайнарджійським договором.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Поразка на Кагульській рівнині", "6f408eaf"], "d": ["Через три тижні після спалення флоту під Чесмою головне османське військо на Дунаї розсипалося на Кагульській рівнині перед значно меншими, але дисциплінованими силами фельдмаршала Румянцева. Табір, обози та сотні гармат потрапили до рук ворога; утікачі зазнали великих втрат, переправляючись через Дунай. Знищення протягом одного літа і флоту, і сухопутного війська призвело до падіння одне за одним Кілії, Аккермана, Ізмаїла та Бендер і до окупації Криму.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Російська окупація Кримського півострова", "217837b0"], "d": ["Російські війська, які роком раніше захопили Буджак, під командуванням князя Долгорукова прорвалися через Перекоп (Ор-Капи) та захопили весь Кримський півострів. Хана скинули з престолу, а поставивши на чолі проросійського Сахіба Ґерая, зробили перший крок до відриву ханства від Османської держави. Втрата Криму, який три століття був північним щитом османів, стала початком процесу, що привів до незалежності 1774 року та до прямої анексії 1783 року.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Смерть Мустафи III і сходження на престол Абдул-Гаміда I", "42cba8e2"], "d": ["Замість Мустафи III, який помер у найкризовіший момент війни з Росією, на престол у сорок дев'ять років зійшов його брат Абдул-Гамід I, що провів сорок три роки в палацовому кафесі. Новому падишахові, який прийняв державу в одну з найважчих її діб, довелося зіткнутися з тяжкими умовами Кючук-Кайнарджійського договору, підписаного того самого року. Його п'ятнадцятирічне правління минуло під знаком утрати Криму та нової війни з Росією й обірвалося 1789 року через удар, який стався з ним під час читання звістки про падіння Очакова.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Поразка під Козлуджею — розгром, що привів до Кючук-Кайнарджі", "8e0542f9"], "d": ["Османські сили, зібрані під Шуменом, зазнали під Козлуджею поразки від об'єднаних колон Суворова та Каменського, і більша частина війська розбіглася. Після цього розгрому на Балканах не залишилося сил для опору; російські передові загони обложили Шумен, і під загрозою опинилася ставка великого візира. Те, що не минуло й місяця, як сторони сіли за стіл у Кючук-Кайнарджі й було прийнято надзвичайно тяжкі умови, є прямим наслідком цієї поразки.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Поступка Буковини (північ Молдавії) Австрії", "190f9caa"], "d": ["Скориставшись слабкістю, спричиненою Кючук-Кайнарджійським миром, Австрія зажадала Буковину, яка забезпечувала зв'язок між Молдавією та Трансильванією, і здобула цю землю без війни, погрозами та підкупом. Втрата цієї родючої та стратегічної області на південний захід від Хотина фактично розколола Молдавське воєводство надвоє. Цю поступку, що відбулася без жодного пострілу, вважали одним із найочевидніших свідчень того, що Османська держава вже втратила здатність стримувати противників. 1775 року з поступкою Буковини Сучава та Чернівці перейшли до Австрії (день не підтверджено).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Іранська окупація Басри", "0161e709"], "d": ["Садик-хан, брат правителя з династії Зендів Карім-хана, після річної облоги захопив Басру, і Османська держава втратила свій найважливіший порт у Перській затоці. Окупація прямо вдарила по торговому шляху до Індії, доходах від фініків і перлів та південній обороні Іраку. Місто вдалося повернути лише 1779 року під час боротьби за престол, що спалахнула в Ірані після смерті Карім-хана.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Айнали-Кавацька роз'яснювальна конвенція — тимчасовий компроміс щодо Криму", "9b3b0468"], "d": ["Дві держави, які через питання про те, хто очолить Кримське ханство, опинилися на межі війни, за посередництва Франції підписали в палаці Айнали-Кавак роз'яснювальний акт. Росія погодилася вивести війська з Криму, а Османська держава — визнати ханом проросійського Шахіна Ґерая; було підтверджено релігійне халіфське право падишаха щодо Криму. Ця крихка рівновага, що мала протриматися чотири роки, остаточно зруйнувалася 1783 року з прямою анексією півострова Росією.", "8a428802"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Оголошення війни Росії — почалася російсько-турецька війна 1787–1792 років", "3bfb870c"], "d": ["Після показної подорожі Катерини II до Криму та взяття нею Грузії під свій захист диван ухвалив рішення про війну, щоб скасувати анексію, а російського посла знову замкнули в Єдикуле. Проте військо не було готове, скарбниця була порожня, а пошуки союзників нічого не дали. Ця п'ятирічна війна закінчилася падінням Очакова з різаниною, втратою Ізмаїла та тяжкими умовами Ясського договору.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Вступ Австрії у війну — боротьба на два фронти", "ae912290"], "d": ["Відповідно до таємного союзу з Росією, укладеного 1781 року, австрійський імператор Йосиф II оголосив війну Османській державі й рушив у напрямку Белграда та Боснії. Османське військо раптом мусило воювати одночасно на двох фронтах: на півночі проти Росії, на заході проти Австрії. Попри перемоги над австрійцями під Лазаретом, Мехадією та Себешем, 1789 року з втратою Белграда розвалився й західний фронт.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Османсько-прусський союз", "03b88e51"], "d": ["Щойно зійшовши на престол і шукаючи союзників у Європі, Селім III підписав із Пруссією союзний договір, що передбачав взаємну допомогу: Пруссія зобов'язалася оголосити війну Росії та Австрії, а Османська держава — не укладати миру, доки не буде повернуто Крим. Це був перший в османській історії справжній текст взаємного союзу, підписаний із європейською державою, і він показував, що від класичного уявлення «з невірними союзу не буває» відмовилися. Пруссія у війну не вступила, але, змусивши Австрію до миру, відкрила шлях до Систовського договору.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Падіння фортеці Ізмаїл і різанина", "6a296b0c"], "d": ["Фортецю Ізмаїл, яку вважали найсильнішим укріпленням дельти Дунаю, було захоплено за один день кривавим загальним штурмом, організованим генералом Суворовим; залогу та мешканців міста значною мірою вирізали. Ця різанина, яка набула широкого розголосу в Європі, викликала глибоке потрясіння в османському суспільстві та переламала хребет дунайської лінії оборони. Через рік фортецю повернули за Ясським договором, але доля війни на той час була вже давно вирішена.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Систовський договір — закриття австрійського фронту", "58741f1d"], "d": ["Завдяки тискові Пруссії та тому, що Французька революція прикувала увагу Австрії на заході, дві держави уклали мир на основі довоєнних кордонів. Австрія повернула всі окуповані місця, зокрема Белград; Османська держава погодилася лише на невеликі виправлення кордону з Хорватією. Закриття західного фронту на таких умовах дозволило Османській державі зосередити всі сили проти Росії та обмежило втрати за Ясським договором. Унаслідок цих виправлень на хорватському кордоні Цетін (Цетінград) і Дрежник-Град переходять від османів до Габсбургів (TDV zistovi-antlasmasi; Korić 2016, n. 118, стаття 4). Оршова (Стара Оршова) — єдине місце, яке не повернули (Bánlaky 0019/1796); юридичну передачу атлас датує цим днем (фактична окупація — 16 квітня 1790 року).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Ясський договір — остаточна втрата Криму та кордон по Дністру", "a56fd194"], "d": ["За договором, підписаним наприкінці п'ятирічної війни, кордоном визнавалася річка Дністер; лівий берег залишився за Росією, правий — за османами, а Очаків із околицями було втрачено остаточно. Османська держава цілковито відмовилася від надії повернути Крим і юридично визнала анексію 1783 року; Волощину та Молдавію повернули зі звільненням від данини на два роки. Прийнявши також зобов'язання сплатити дванадцять мільйонів курушів воєнної контрибуції, османи назавжди поступилися Росії північчю Причорномор'я. Інші місця, приєднані того самого дня: Ізмаїл.", "277ee99d"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Фактичне правління Пазвандоглу Османа у Відіні", "0ce70361"], "d": ["Пазвандоглу Осман, який повстав проти запроваджень Нізам-і Джедід, змусив відінського намісника тікати, захопив місто та укріпив його вздовж Дунаю глибокими ровами. 1797 року, на вершині своєї могутності, він зібрав близько вісімдесяти тисяч вояків і взяв під контроль Нікополь, Систову, Русе, Софію та Ніш, подаючи себе не бунтівником, а реформатором. Багатомісячна облога, яку вела Висока Порта в 1798–1799 роках, нічого не дала, і до своєї смерті 1807 року він напівнезалежно правив Північною Болгарією.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Відкриття Мюхендісхане-і Беррі-і Хюмаюн (імперської сухопутної інженерної школи)", "e9a3a34b"], "d": ["Щоб готувати для війська Нізам-і Джедід офіцерів-артилеристів, фортифікаторів і картографів, у Хаскьої відкрили сухопутну інженерну школу; вона була сухопутним відповідником Морської інженерної школи, заснованої 1773 року. У програмі викладали алгебру, геометрію, механіку, фортифікацію та балістику, з європейських мов перекладали книжки з математики та артилерії. Цю школу, яку вважають коренем сучасної інженерної освіти в Туреччині, визнають початком нинішнього Стамбульського технічного університету.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Оголошення війни Франції та союз із Росією й Англією", "80e95bd7"], "d": ["Після вторгнення Наполеона в Єгипет Османська держава, порушивши традиційну дружбу з Францією, що тривала два з половиною століття, оголосила їй війну. У ході тих самих подій вона вперше у своїй історії уклала союз із Росією та дозволила російському флотові пройти через Протоки в Середземне море; потім було підписано союз і з Англією. Завдяки цим союзам у французів відібрали Іонічні острови, проте відкриття Проток для іноземного флоту створило прецедент, за який згодом довелося дорого заплатити.", "7d8a9e45"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Оборона Акри — відсіч Наполеонові", "56b5c45b"], "d": ["Наполеон, який просувався з Єгипту в Сирію, обложив Акру та два місяці влаштовував штурми один за одним; місто обороняв Джеззар Ахмед-паша за підтримки англійського флоту та частин Нізам-і Джедід, надісланих зі Стамбула. Змушений зняти облогу та відійти в Єгипет, Наполеон поховав перед цими мурами мрію про поширення на схід. Звістку зустріли в Стамбулі з великою радістю та вважали доказом того, що новостворене навчене військо склало свій перший серйозний іспит.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Набіг ваххабітів на Кербелу", "522341ed"], "d": ["Ваххабітські сили, що вирушили з Неджду, вдерлися в Кербелу, пограбували місто, зруйнували гробницю імама Хусейна та вбили понад три тисячі людей. Мамлюцькі намісники Османської держави в Іраку не змогли запобігти набігові; подія викликала бурхливу реакцію і в Ірані, і в Стамбулі. Цей напад засвідчив, що рух Саудів уже не був оазовим еміратом, а перетворився на регіональну силу, яка загрожувала священним містам Османської держави.", "f571ab30"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Евакуація французів з Єгипту", "00cfdc8c"], "d": ["Унаслідок спільної операції османських та англійських сил із суходолу й моря спершу капітулював Каїр, а потім Александрія, і французькі війська кораблями відправили на батьківщину. Коли закінчилася трирічна окупація, Єгипет на папері повернувся під османське управління, але боротьба за владу між мамлюцькими беями та албанськими загонами вкинула країну в хаос. Ця порожнеча за кілька років підготувала ґрунт для піднесення Мехмеда Алі з Кавали.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Паризький договір — відновлення миру з Францією", "1b76991f"], "d": ["Договір, підписаний після евакуації Єгипту, офіційно припинив стан війни між Османською державою та Францією й поновив давні капітуляції. Французьким торговим кораблям дозволили заходити в Чорне море; натомість Франція визнала територіальну цілісність Османської держави. Встановлення миру повернуло простір для маневру зовнішній політиці Селіма III, затиснутій на боці Росії та Англії.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Захоплення Таїфа ваххабітами", "7b791359"], "d": ["Ваххабітські сили під командуванням Сауда ібн Абдул-Азіза першим кроком проти Хіджазу обложили та пограбували Таїф; місто впало як перші ворота до святої землі. Для османського падишаха, який мав титул покровителя двох святинь, це був удар, що прямо похитнув легітимність його влади. Через два з половиною місяці те саме військо рушило на Мекку.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Перше захоплення Мекки ваххабітами", "21157c05"], "d": ["Через два з половиною місяці після падіння Таїфа ваххабітські сили ввійшли до Мекки, зруйнували гробниці та запровадили порядок відповідно до своїх уявлень; шериф Ґаліб мусив відступити в Джидду. Перекриття шляхів хаджу відлунило по всьому ісламському світу та змусило Стамбул просити військової допомоги в єгипетського намісника Мехмеда Алі. Це перше панування тривало лише три місяці.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Повернення Мекки шерифом Ґалібом", "83d08dff"], "d": ["Шериф Ґаліб, який відступив у Джидду, зібраними силами обложив Мекку й після двадцятип'ятиденної облоги відібрав місто у ваххабітів; хутбу знову читали від імені османів. Це друге панування також не стало тривалим: 1806 року сили Саудів знову взяли місто.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Початок Першого сербського повстання", "0f6e8767"], "d": ["Після того як бунтівні яничари-даї, що захопили владу в Белграді, масово перебили сербських старшин, під проводом Карагеоргія почався збройний опір. Рух, який спочатку зберігав вірність падишахові й був спрямований лише проти даїв, невдовзі перетворився на національне повстання з вимогами автономії та незалежності. 1806 року сербські сили захопили Белград; це повстання стало першою ланкою націоналістичних рухів за незалежність на Балканах.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Окупація Медини ваххабітами", "84e310d7"], "d": ["Услід за Меккою до рук ваххабітських сил перейшла й Медина; скарбницю гробниці Пророка (Равза-і Мутаххара) роздали, а склепінчасті гробниці в місті зруйнували. Так обидва священні міста вийшли з-під османського контролю, і каравани паломників із Дамаска та Єгипту роками не могли вирушити в дорогу. Медину вдалося повернути лише через сім років, 1812 року, єгипетському війську під командуванням Тосуна-паші, сина Мехмеда Алі-паші.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Початок війни з Росією (російсько-турецька війна 1806–1812 років) і закриття Проток", "ea170804"], "d": ["Коли Селім III, який після перемоги Наполеона під Аустерліцом зблизився з Францією, попри російський тиск усунув господарів Волощини та Молдавії, російські війська окупували обидва князівства, і почалася війна. Османська держава закрила Протоки для російського флоту; у відповідь Англія стала на бік Росії та відрядила ескадру до Стамбула. Ця шестирічна війна, переплетена з повстанням Кабакчі та поваленням Селіма III, закінчилася втратою Бессарабії за Бухарестським договором 1812 року.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Англійський флот перед Стамбулом (експедиція Дакворта)", "195bb58f"], "d": ["Бажаючи змусити Османську державу розірвати зв'язки з Францією, Англія провела ескадру під командуванням адмірала Дакворта через Дарданелли та поставила її на якір перед Стамбулом. За спонукою також французького посла Себастьяні мешканці Стамбула піднялися, берегові батареї за кілька днів посилили, і ескадра, так і не обстрілявши місто, мусила відійти; на зворотному шляху в Дарданеллах вона зазнала тяжких втрат. Те, що столицю вперше так близько загрожував іноземний флот, поставило питання Проток у центр європейської дипломатії.", "bf71116c"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Дарданелльський договір — мир з Англією та правило щодо Проток", "fe282117"], "d": ["Договір, укладений з Англією після провалу експедиції Дакворта, припинив війну між двома державами та повернув англійським купцям давні привілеї. Положення тексту, назване «стародавнім правилом», зафіксувало, що в мирний час жоден іноземний військовий корабель не може проходити через Протоки. Цей принцип став правовою основою всіх міжнародних угод, які впродовж XIX століття визначали режим Проток.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Слобозійський розгром — оточення Дунайської армії", "54b60fd1"], "d": ["Більшу частину османського війська, яке перейшло Дунай під Русе, Кутузов обхідним маневром з протилежного берега річки затиснув під Слобозією та прирік на голод. Тисячі вояків мусили здатися; сили, що були в руках великого візира, фактично розтанули, і через місяць Висока Порта мусила просити перемир'я. Ця поразка стала прямою причиною згоди віддати Бессарабію за Бухарестським договором 1812 року.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Повернення Белграда та придушення Першого сербського повстання", "06f56f52"], "d": ["Сербські повстанці, позбавлені за Бухарестським договором російської підтримки, не встояли перед спільною операцією сил, що прийшли з Боснії та Румелії; Хуршид Ахмед-паша ввійшов до Белграда, і дев'ятирічне повстання було цілковито придушене. Карагеоргій утік до Австрії, а санджак Смедерево знову підпорядкували прямому османському управлінню. Проте суворі заходи, які було вжито, через два роки викликали друге й тривале повстання під проводом Мілоша Обреновича.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Друге сербське повстання та верховне князівство Мілоша Обреновича", "e6e82ad2"], "d": ["Проти тяжких заходів, запроваджених після придушення першого повстання, вибухнуло нове повстання під проводом Мілоша Обреновича; цього разу Висока Порта віддала перевагу компромісові перед силою. За досягнутою угодою Мілоша визнали «верховним князем» (баш-кнезом), а повноваження збирати податки та вести внутрішні справи залишили сербським кнезам. Цей перший осередок фактичної автономії став відправною точкою процесу, що привів до фірману 1830 року та незалежності 1878 року.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Волоське повстання — Іпсіланті переходить Прут, і піднімається Володимиреску", "67d46a98"], "d": ["Александр Іпсіланті, генерал російського війська, перейшов Прут і від імені «Філікі Етерія» спробував розпочати загальне грецьке повстання у Волощині та Молдавії; у ті самі дні Тудор Володимиреску підняв місцевих селян. Два рухи не змогли об'єднатися: на заклик Іпсіланті разом воювати проти турків Володимиреску відповів: «Я повстав не проти турків, а проти греків», а невдовзі його вбили люди Іпсіланті. У травні османські сили придушили повстання, проте порядок фанаріотських господарств скінчився, а полум'я повстання перекинулося в Морею.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Заснування Другої Саудівської держави в Ер-Ріяді", "34dad3bd"], "d": ["Через шість років після падіння Дір'ї 1818 року та загибелі Першої Саудівської держави Туркі ібн Абдаллах вигнав єгипетські залоги з Неджду й заснував новий Саудівський емірат із центром в Ер-Ріяді. Нове утворення, уникаючи поширення на Хіджаз, воліло залишатися в Неджді та трималося осторонь прямих зіткнень з османсько-єгипетськими силами. Ця друга держава проіснувала до кінця століття й стала другою ланкою ланцюга, що привів до створення нинішньої Саудівської Аравії. Інші поселення, втрачені того самого дня: Дір'я (Неджд).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Аккерманська конвенція — поступки щодо Сербії та князівств", "c75f15d0"], "d": ["Одразу після скасування яничарського корпусу Османська держава, залишившись без війська, мусила перед російським ультиматумом прийняти договір із тяжкими умовами. Було підтверджено обіцяну Сербії автономію, визнано, що господарів Волощини та Молдавії не можна усувати без згоди Росії, а російським торговим кораблям надано повну свободу в Протоках. Коли через два роки Висока Порта через грецьке питання оголосила, що не визнає конвенцію, Росія сприйняла це як привід до війни.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Ліквідація тімарної системи", "84d5d1d6"], "d": ["Через рік після скасування яничарського корпусу близько 5200 сипахіїв-тімаріотів із п'ятдесяти трьох санджаків Румелії та Анатолії разом із доходами з тімарів перетворили на кінноту Асакір-і Мансуре. Так фактично скінчився тімарний лад — чотиристолітній хребет османського землеволодіння, оподаткування та війська. Звільнені тімари передали скарбниці, і відкрився шлях до переходу на централізоване військо з платнею та грошову податкову систему.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Заснування Тибхане-і Аміре — початок сучасної медичної освіти", "ac3e57c0"], "d": ["Щоб готувати лікарів і хірургів для новоствореного війська Асакір-і Мансуре, на пропозицію головного лікаря Мустафи Бехчета-ефенді в Шехзадебаші відкрили Тибхане-і Аміре. Заняття впорядкували за європейськими програмами, і спочатку викладали французькою мовою; через кілька років створили також Джеррахане-і Аміре (хірургічну школу), і два заклади об'єднали. Цю школу, яку вважають початком сучасної медичної освіти в Туреччині, визнають витоком нинішнього Стамбульського медичного факультету.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Початок російсько-турецької війни 1828–1829 років", "9dff4e05"], "d": ["Після спалення флоту під Наваріном і заяви Високої Порти про невизнання Аккерманської конвенції Росія почала війну одразу на двох фронтах. Оскільки яничарський корпус щойно скасували, а нове військо ще тільки створювалося, османська оборона від самого початку була слабкою; росіяни переходили Дунай, а на сході взяли Карс і Ахалцихе. Російське військо, яке за рік дійшло до Едірне, нав'язало тяжкі умови Адріанопольського договору 1829 року та незалежність Греції.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Перший договір зі Сполученими Штатами Америки", "d737516f"], "d": ["За договором про торгівлю та мореплавство, укладеним після багаторічних контактів, США здобули в османських володіннях статус нації найбільшого сприяння та право торгового проходу через Протоки. Окрема таємна стаття передбачала, що османи на своє бажання можуть будувати кораблі на американських верфях і купувати готові судна та деревину; сенат США ратифікував договір, але цю таємну статтю відхилив 27 голосами проти 18. Та шлях для кораблів усе ж не закрився: Генрі Екфорд продав османам корабель, який привів 1831 року, а американські майстри, що працювали в Айнали-Каваку, дали флотові кораблі нового типу. Цей договір став документом перших всебічних відносин Османської держави з позаєвропейською державою.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Кінець мамлюцького правління в Багдаді", "7e1d38a3"], "d": ["Махмуд II, який проводив політику централізації, оголосив бунтівником багдадського намісника Давуда-пашу, що не надсилав вимаганих грошей і наказав убити посланця з центру. Сили під командуванням Алі Ризи-паші після дев'яностоденної облоги захопили місто, і майже всіх мамлюків було ліквідовано. Так скінчилося напівнезалежне правління мамлюків, що тривало з 1704 року, а Ірак знову підпорядкували безпосередньо центрові.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Заснування Військової школи (Мектеб-і Харбіє) в казармі Мачка", "bf31c7d9"], "d": ["Щоб забезпечити Асакір-і Мансуре-і Мухаммедіє офіцерами, підготовленими за європейським зразком, у казармі Мачка відкрили Школу військових наук (Мектеб-і Фюнун-и Харбіє). Учнів навчали математики, топографії, фортифікації та іноземних мов; невдовзі кадри зміцнили, пославши учнів до Відня та Парижа. Ця школа стала колискою традиції офіцерів зі шкільною освітою в османському війську, а отже й нового покоління військової інтелігенції, яке з'явилося наприкінці XIX століття.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Пряме підпорядкування Триполітанії центрові — кінець династії Караманли", "faabcb96"], "d": ["Через боротьбу за престол у родині Караманли та посилення європейського тиску після окупації Францією Алжиру 1830 року Висока Порта прямо втрутилася в справи Триполітанії. Флот, надісланий зі Стамбула, увійшов до міста, останнього бея з роду Караманли усунули й доправили до Стамбула, а еялет передали намісникові, призначеному з центру. Так закінчилася 124-річна доба династії, а останній клаптик землі в Північній Африці, яким Османська держава управляла безпосередньо, було закріплено.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Скасування посади дефтердара та заснування Міністерства фінансів", "89f8125e"], "d": ["Посаду дефтердара — голови класичного османського фінансового ладу — скасували, створили Міністерство фінансів на європейський зразок, а розпорошені скарбниці зосередили в одних руках. Того самого року й інші підрозділи Високої Порти реорганізували в міністерства, і відбувся перехід до сучасної структури ради міністрів. Це впорядкування було одним із найважливіших кроків, що підготували адміністративну основу Танзіматського фірману, оголошеного через рік.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Англійці закріплюються в Адені", "ddbd556b"], "d": ["Спираючись на угоду про торгівлю та дружбу, укладену 1802 року з султаном Лахеджу Ахмедом ібн Абдул-Керімом, Англія висадила війська в порту Аден і взяла місто під контроль. Цей порт, що тримав вихід із Червоного моря, перетворився на вугільну базу на шляху до Індії та на ключовий пункт британської імперської стратегії. Хоча на папері претензії Османської держави на Ємен зберігалися, її фактичне панування на південному узбережжі після цієї дати вже ніколи не повернулося.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Повернення на узбережжя Тіхами: узяття Ходейди, Забіда та Мохи", "353982d2"], "d": ["На єменському узбережжі, яке після відходу єгипетського війська 1840 року залишилося без господаря, під наглядом мекканського шерифа висадилися сили під командуванням Тевфіка-паші та підпорядкували османському управлінню порти Ходейда, Забід і Моха. Хоча була спроба просунутися до самої Сани, через опір населення довелося повернутися до Ходейди; тож нагір'я залишилося за зейдитськими імамами, а османське панування впродовж двадцяти трьох років тривало лише на смузі Тіхами. Внутрішній Ємен повернули тільки 1872 року походом Ахмеда Мухтара-паші.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Балталіманська конвенція: спільна османсько-російська опіка над Волощиною та Молдавією", "d3bb22e9"], "d": ["Коли революції 1848 року перекинулися на Волощину та Молдавію, османські й російські сили спільно окупували князівства. За конвенцією, підписаною в Балталімані, було ухвалено, що господарів не обиратимуть, а призначатиме падишах на сім років і що обидві держави запровадять спільний контроль у регіоні. Угода зберегла на папері суверенітет османів, але визнала за Росією фактичне право співучасті та прискорила відрив дунайських князівств від Османської держави.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Питання угорських біженців: Кошут і його товариші знаходять притулок в османів", "1c7d7ef4"], "d": ["Після придушення угорської революції 1848–1849 років російсько-австрійською інтервенцією Лайош Кошут і тисячі угорських та польських біженців знайшли притулок на османських землях. Австрія та Росія різко вимагали їх видачі; Висока Порта за підтримки Англії та Франції відмовила у видачі й поселила групу в Кютах'ї. Оточення Кошута пробуло тут близько вісімнадцяти місяців, а сотні біженців прийняли іслам і вступили на османську службу. Цю подію вважали однією з рідкісних дипломатичних перемог, що піднесли авторитет Османської держави доби Танзімату в європейській громадській думці.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Заснування Енджюмен-і Даніш: перша османська академія в Стамбулі", "6fda1365"], "d": ["Енджюмен-і Даніш, створена рішенням Меджлісу загальної освіти (Меджліс-і Маариф-і Умуміє), була першою османською науковою академією, організованою для підготовки наукових книжок і підручників турецькою мовою. Її урочисто відкрили 18 липня 1851 року в будівлі Дарюльмааріфу; серед її вітчизняних та іноземних членів був і Ахмед Джевдет-паша. Хоч вона проіснувала недовго, такі праці, як «Історія» Джевдета-паші та «Каваїд-і Османіє» («Правила османської мови»), стали плодом цієї установи й вважалися наріжним каменем перетворення турецької на мову науки.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Перемога під Ольтеницею: перший османський успіх на дунайському фронті", "a660ad2f"], "d": ["На початковому етапі Кримської війни головнокомандувач (сердар-і екрем) Омер Лютфі-паша перейшов Дунай і під Ольтеницею відкинув російські сили з тяжкими втратами. Перемога на самому початку війни зупинила російський наступ і показала Європі силу, якої османське військо набуло завдяки навчанню після Танзімату. Цей успіх підготував психологічний ґрунт, що полегшив рішення Англії та Франції вступити у війну на боці османів.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Союзний договір з Англією та Францією в Стамбулі", "04809278"], "d": ["Союзний договір, укладений у Кримській війні проти Росії між Османською державою, Англією та Францією, передбачав спільні дії трьох держав і те, що союзники не укладатимуть сепаратного миру до закінчення війни. Так Османська держава вперше у своїй історії вступила у військовий союз із великими європейськими державами як рівна сторона. Цей договір також заклав правове підґрунтя офіційного прийняття османів до системи європейських держав у Парижі через два роки.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Створення Стамбульського шехремінату: перша сучасна муніципальна організація", "be4af27f"], "d": ["Скупчення союзних вояків у Стамбулі під час Кримської війни та інфраструктурна криза, спричинена зростанням населення, виявили неспроможність класичного міського управління, зосередженого на посаді каді. Створений за європейськими зразками шехремінат (міське управління) зосередив в одних руках прибирання, встановлення цін, нагляд за ринками та міське будівництво; наступного року в Бейоглу та Галаті як пілотний район утворили Шостий муніципальний округ. Цей крок вважають початком сучасного муніципального самоврядування в Османській державі.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Паризький договір: кінець Кримської війни та прийняття османів до системи європейських держав", "4aee0e2a"], "d": ["За Паризьким договором, який закінчив Кримську війну, Османську державу оголосили рівноправним учасником європейського міжнародного права, а її територіальну цілісність узяли під спільну гарантію великих держав. Чорне море нейтралізували, претензію Росії на заступництво над православними підданими, яку вона мала з часів Кючук-Кайнарджі, скасували, а південь Бессарабії (повіти Кілія, Кагул, Ізмаїл і Болград) передали Молдавії. Проте той самий договір, перетворивши Іслахатський фірман на міжнародне зобов'язання, прочинив і двері для втручання у внутрішні справи.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Відкриття палацу Долмабахче: центр управління переїжджає з Топкапи", "71ad26d0"], "d": ["Палац, який 1842 року Абдул-Меджид замовив родині Бальянів, відкрили після чотирнадцяти років будівництва, і центр управління державою переїхав із чотиристолітнього Топкапи на берег Босфору. Своїм європейським стилем, кришталевими сходами та залою урочистих прийомів (Муаєде) палац став кам'яним утіленням претензії Танзімату на вестернізацію. Водночас його величезна вартість стала однією зі статей, що їх найбільше критикували в роки, коли османські фінанси потрапляли в спіраль зовнішніх позик.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Об'єднання Волощини та Молдавії під владою Кузи: народження Румунії", "baef4da5"], "d": ["На виборах, проведених після Паризького договору, обидва князівства обрали господарем полковника Александру Йоана Кузу, здійснивши таким чином фактичне об'єднання. Хоча Висока Порта й Австрія виступили проти, довелося визнати доконаний факт, підтриманий Францією. Це об'єднання, яке на папері залишалося залежним від Османської держави, 1862 року взяло назву Румунія, а 1877 року в односторонньому порядку проголосило незалежність; це переломний момент у розпаді османського панування на Дунаї.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Кулелійська справа: перша спроба перевороту проти Абдул-Меджида в Стамбулі", "e3653b21"], "d": ["Таємне товариство з військових і цивільних, обурене танзіматською політикою та рівністю, яку Іслахатський фірман надавав немусульманам, планувало скинути падишаха, але його накрили під час зібрання в мечеті Килич Алі-паші. Оскільки обвинувачених судили в казармі Кулелі, подія отримала цю назву; смертні вироки замінили засланням. Її вважають першою в османській історії спробою палацового перевороту, здійсненою організацією, створеною з ідеологічних міркувань.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Друзько-маронітська громадянська війна в Гірському Лівані та дамаські події", "5595fdd6"], "d": ["Сутички, що вибухнули в травні 1860 року після вбивства двох друзів поблизу Сайди, перетворилися на найкривавішу друзько-маронітську громадянську війну в горах, у липні перекинулися в Дамаск і закінчилися загибеллю тисяч християн. Коли Франція висадила війська, Висока Порта відрядила в регіон Фуада-пашу з надзвичайними повноваженнями; було проведено суворе придушення. Ці події дали привід для європейського втручання та стали прямою причиною того, що Ліван здобув особливий статус.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Початок виходу «Терджюман-і Ахваль»: перша приватна турецькомовна газета в Стамбулі", "24792957"], "d": ["«Терджюман-і Ахваль» («Тлумач подій»), яку видавав Аґях-ефенді, а редакційну роботу взяв на себе Шинасі, була першою турецькомовною газетою, що виходила без державної підтримки. У передмові до першого номера обстоювалося право народу висловлюватися про власні справи, а друкуючи з продовженнями «Одруження поета» Шинасі, газета прочинила двері й сучасній турецькій літературі. Народження поняття громадської думки та опозиційної преси в Османській державі відносять саме до цього часу.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Статут Гірського Лівану: статус привілейованого мутасарифату для Лівану", "bf375603"], "d": ["Статут, складений під тиском великих держав після різанини 1860 року, перетворив Гірський Ліван на привілейований мутасарифат, прямо підпорядкований Високій Порті й керований адміністративною радою, створеною з урахуванням рівноваги між конфесіями. Було поставлено умову, щоб мутасариф був османським підданим-католиком, а його призначення подавалося на схвалення великим державам; першим мутасарифом став Давуд-паша. Цей порядок протримався до 1915 року й утворив ядро сучасної Ліванської держави.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Смерть Абдул-Меджида та сходження на престол султана Абдул-Азіза", "27204d7c"], "d": ["Коли Абдул-Меджид, який за двадцять два роки правління підписав Танзіматський та Іслахатський фірмани, помер від туберкульозу, на престол зійшов його брат Абдул-Азіз. Новий падишах у перші роки подавав надії заходами ощадності та простим способом життя; флот він перетворив на одну з помітних сил світу. Проте під кінець його правління тяжкий зовнішній борг, банкрутство 1875 року та балканські повстання нагромадилися й підготували ґрунт для його повалення 1876 року.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Об'єднані князівства беруть назву Румунія", "d960e3fc"], "d": ["Волощина та Молдавія, фактично об'єднані подвійним обранням Кузи 1859 року, 1862 року зібрали свої парламенти та уряди під одним дахом у Бухаресті й офіційно взяли назву Румунія. Хоча юридично Османська держава зберегла становище сюзерена та щорічну данину, контроль над князівством вона фактично втратила. Саме ця дата символізує кінець чотиристолітнього османського впливу на північ від Дунаю.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Приєднання Суакіна, Массауа та Дахлаку до Єгипту", "a0924860"], "d": ["Массауа, яку султан Абдул-Меджид 1846 року разом із Суакіном віддав єгипетському правителеві Мехмеду Алі-паші як сальяне (призначення доходів), за хедива Ісмаїла-паші разом із Дахлаком і Суакіном включили до єгипетських володінь та організували зі статусом каймакамства. Так ці три порти на африканському узбережжі Червоного моря, юридично залишаючись османською землею, адміністративно перейшли з прямого підпорядкування Високій Порті до Каїра — увійшли в той самий залежний шар, що й сусідні Єгипет і Судан.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Початок критського повстання (1866–1869)", "3679b861"], "d": ["Широке повстання, що вибухнуло на острові за відкритої підтримки Греції, уперше перетворило вимогу критських греків про енозис (приєднання до Греції) на міжнародне питання. Запекла гірська війна, яка тривала три роки, завдала османському війську тяжких втрат і набула великого розголосу в європейській громадській думці. Повстання вдалося згасити лише 1868 року, коли Алі-паша прибув на острів і ввів у дію статут, що надавав широкі привілеї.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Виведення останніх османських залог із Белграда та сербських фортець", "b34217db"], "d": ["Під тиском великих держав і на наполегливу вимогу князя Михайла Висока Порта погодилася звільнити останні військові опорні пункти, що залишалися в неї в Сербії; 18 квітня 1867 року османський прапор у Белградській фортеці спустили, а ключі передали князеві. Так закінчилася фактична османська військова присутність, що тривала з 1521 року, і на шляху Сербії до незалежності зникла остання велика перешкода. Сюзеренітет падишаха звівся лише до символічного питання прапора та данини.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Надання єгипетським намісникам титулу хедива", "09e10c12"], "d": ["Унаслідок наполегливого лобіювання Ісмаїла-паші, представника третього покоління династії Мехмеда Алі з Кавали, та грошей, які він лив у Стамбул, єгипетському намісникові надали титул хедива, що підкреслював його вищість над іншими намісниками. У ті самі роки змінили й порядок спадкування — тепер від батька до сина, а Єгиптові визнали повноваження суверенного характеру: зовнішні позики, нагородження медалями, утримання консульств. Ці кроки є першою ланкою ланцюга, який прискорив юридичний відрив Єгипту від Османської держави.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Критський статут: широкі адміністративні привілеї для острова", "12052262"], "d": ["Щоб покласти край трирічному повстанню, великий візир Алі-паша особисто прибув на острів, і за статутом, оприлюдненим зі схвалення падишаха, критянам надали змішані адміністративні ради, місцеві суди, вживання грецької мови в офіційному діловодстві та податкові пільги. Це впорядкування зберегло османське панування на острові ще на тридцять років. Проте привілеї, надані християнському населенню, послабили становище критян-мусульман і посіяли зерна кризи 1896–1898 років.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Відкриття Шура-йи Девлет: заснування османської Державної ради", "70b16497"], "d": ["Ірадою від 5 березня 1868 року Меджліс судових постанов (Меджліс-і Ахкям-і Адліє) розділили надвоє: адміністративно-законодавчі справи передали Шура-йи Девлет (Державній раді), а судові — Дивану судових постанов; установу урочисто відкрили у Високій Порті, а першим її головою призначили Мідхата-пашу. Їй доручили готувати законопроєкти, розв'язувати адміністративні спори та вести судові справи щодо чиновників. Зі змішаним складом із мусульман і немусульман її вважають першим інституційним утіленням ідеї поділу влади в Османській державі.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Відкриття Суецького каналу: скорочення шляху до Індії через Єгипет", "377ccd04"], "d": ["Будівництво, розпочате 1859 року, тривало десять років, і 163-кілометровий канал, що з'єднав Середземне море з Червоним, урочистою церемонією ввели в дію. Коли шлях, який з'єднував Європу з Індією, скоротився на тисячі миль, Єгипет раптом став ключовим пунктом світової торгівлі. Ця геостратегічна цінність стала головною причиною окупації Єгипту Англією через тринадцять років після відкриття каналу, а борг, яким канал обтяжив Єгипет, довів хедиват до банкрутства.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Заснування Болгарського екзархату: відокремлення болгарської церкви від Фанару", "33a8272c"], "d": ["Фірманом падишаха було створено окрему від Грецького патріархату самостійну болгарську церкву (екзархат), а питання про те, які повіти підпорядкують екзархатові, залишили на всенародне голосування. Висока Порта зробила цей крок, щоб зламати грецький вплив, але результат виявився протилежним: церква перетворилася на організований центр болгарської національної ідентичності та болгарських претензій на Македонію. Так було закладено інституційний ґрунт болгарсько-грецько-сербського суперництва на Балканах і повстань 1876 року.", "ce8f108b"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Недждський похід Мідхата-паші: відновлення османського панування в Аль-Ахсі", "7db51461"], "d": ["Багдадський намісник Мідхат-паша, скориставшись боротьбою за престол у родині Саудів, відрядив війська на західне узбережжя Перської затоки та приєднав область Аль-Ахса під назвою санджаку Неджд до вілаєту Басра. Абдаллаха ібн Фейсала призначили мутасарифом, і на папері було встановлено османське панування. Похід мав на меті зупинити поширення англійського впливу в затоці та того самого року привів і Катар під османський контроль.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Смерть великого візира Алі-паші: кінець танзіматської когорти", "1cf0141c"], "d": ["Зі смертю Алі-паші, який після кончини Фуада-паші 1869 року сам ніс тягар танзіматської політики, вичерпалося покоління майстерних дипломатів, що тридцять років керувало зовнішньою політикою держави. Проросійське та свавільне управління його наступника Махмуда Недіма-паші зміцнило особисту владу Абдул-Азіза. За п'ять років після смерті Алі-паші фінанси збанкрутували, Балкани повстали, а зміна на престолі стала неминучою.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Встановлення османського контролю в Катарі", "3b453165"], "d": ["На запрошення шейха Касіма ібн Тані, який перебував під англійським тиском, османські сили висадилися на Катарському півострові, і восени 1871 року в регіоні було встановлено османський контроль. Катар організували як казу в складі санджаку Неджд, а шейха призначили каймакамом. Цей крок став найвідчутнішим здобутком наступальної політики, яку Мідхат-паша проводив у затоці проти Англії; османський прапор майорів на півострові до 1913 року.", "823711c3"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Узяття Сани: відновлення османської влади в Ємені", "978e20a0"], "d": ["Коли з відкриттям Суецького каналу стратегічна цінність Червоного моря зросла, Висока Порта відрядила в Ємен під командуванням Ахмеда Мухтара-паші резервний корпус (фирка-і іхтіятіє). Зі взяттям Сани державну владу було відновлено у внутрішньому Ємені, фактично втраченому два століття перед тим, а область перетворили на вілаєт. Проте боротьба із зейдитськими імамами не припинялася ніколи; повстання 1891, 1898 та 1904 років утворили найдорожчий і найтриваліший внутрішній фронт Османської держави. Інші місця, приєднані того самого дня: Сана, Таїз.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Початок герцеговинського повстання: Східне питання спалахує знову", "571b18ec"], "d": ["Повстання християнських селян в околицях Невесинє проти тяжких податків і гніту аянів швидко поширилося на всю Герцеговину та живилося добровольцями з Сербії та Чорногорії. Повстання, яке привело до нав'язування реформ Австрією та Росією, наступного року викликало болгарські повстання та оголошення війни Сербією і Чорногорією. Так розірвалася перша ланка великого ланцюга, що привів до російсько-турецької війни 1877–1878 років і до втрати Балкан за Берлінським трактатом.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Банкрутство османських фінансів: виплати за зовнішнім боргом скорочено наполовину", "2cac2fa5"], "d": ["Позики, які з 1854 року брали одну за одною, витрати на Кримську війну, будівництво палаців і голод в Анатолії 1873–1874 років перетворили дефіцит бюджету на прірву понад п'ять мільйонів лір. Уряд Махмуда Недіма-паші, оголосивши, що виплати відсотків і основної суми боргу на п'ять років скорочуються наполовину, фактично запровадив мораторій. Це рішення, що викликало бурхливу реакцію на європейських біржах, започаткувало процес, який через шість років закінчився Мухарремським декретом і створенням Управління Османського державного боргу.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Повалення Мурада V і сходження на престол Абдул-Гаміда II", "cffb2271"], "d": ["Мурад V, який зійшов на престол після повалення Абдул-Азіза, став неспроможним виконувати обов'язки через психічне здоров'я, підірване смертю дядька та справою Черкеса Хасана; із дев'яноста трьох днів його правління лише сім він був при ясному розумі. За фетвою шейх-уль-ісламу його скинули, а на його місце поставили брата, Абдул-Гаміда II. Новий падишах зійшов на престол, пообіцявши Мідхатові-паші проголосити конституційну монархію; починалася доба, що тривала тридцять три роки.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Константинопольська (Терсанська) конференція: великі держави нав'язують балканські реформи", "b5006a2c"], "d": ["Конференція, яку великі держави скликали в Стамбулі для розв'язання балканської кризи, зажадала розділити Болгарію на два автономні вілаєти та провести в Боснії та Герцеговині реформи під міжнародним контролем. У день відкриття конференції Висока Порта гарматними залпами сповістила про проголошення конституції (Канун-і Есасі), намагаючись відповісти на нав'язування конституційною реформою. Делегати вважали це зволіканням і 20 січня 1877 року роз'їхалися; через чотири місяці Росія оголосила війну.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Відкриття першого Меджліс-і Мебусан у Долмабахче", "429bb279"], "d": ["115 депутатів, обраних згідно з конституцією (Канун-і Есасі), уперше зібралися 19 березня 1877 року на церемонії в залі урочистих прийомів палацу Долмабахче; так в османській історії почалася доба представницького парламенту. Депутати — мусульмани й немусульмани — різко ставили запитання урядові та обговорювали керування війною і відповідальність міністрів. Ця смілива опозиція стала головною причиною, що вкоротила життя парламенту.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Початок оборони Плевни: опір Газі Османа-паші", "0e04a878"], "d": ["Осман-паша, який під час російсько-турецької війни 1877–1878 років рушив із Відіна до Плевни, щоб перерізати шлях на Стамбул російському війську, що перейшло Дунай, укріпив містечко редутами й траншеями та розпочав легендарну п'ятимісячну оборону. Три великі російсько-румунські штурми один за одним було відбито з тяжкими втратами, і військо, яким особисто керував цар Олександр II, мусило перейти до облоги. Плевна ввійшла в історію як найблискучіший оборонний успіх османського війська в XIX столітті.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Падіння Плевни: крах дунайського фронту", "185e7602"], "d": ["Коли за п'ять місяців облоги в Османа-паші вичерпалися припаси, він пішов на прорив через річку Вит; після того як його поранили й узяли в полон, місто здалося. Російські командувачі привітали полоненого пашу, повернувши йому шаблю, а Осман-паші надали титул «Газі». З падінням Плевни дорога перед російським військом відкрилася; за два місяці впали Софія, Пловдив і Едірне, а російські передові загони дійшли до Єшилкьоя (Сан-Стефано).", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Окупація Софії російськими військами", "ef369d22"], "d": ["Російське військо, яке після падіння Плевни перейшло Балкани, увійшло до беззахисної Софії. Місто вже не повернулося під османське управління: наприкінці 1878 року воно опинилося в автономному Болгарському князівстві, а 1879 року фактично стало його столицею. На карті з цієї дати Софія виходить із прямого османського управління під тимчасову російську окупацію, а потім під автономну болгарську владу.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Адріанопольське перемир'я: у російсько-турецькій війні 1877–1878 років замовкає зброя", "1f899180"], "d": ["Після падіння одне за одним Софії, Пловдива та Едірне й виходу російського війська до берегів Мармурового моря Висока Порта мусила просити перемир'я. Перемир'я, підписане в Едірне, змусило османів прийняти попередні умови миру: автономію Болгарії, незалежність Чорногорії, Сербії та Румунії і тяжку воєнну контрибуцію. Через місяць ці умови перетворилися на текст договору в Сан-Стефано.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Абдул-Гамід II безстроково припиняє роботу Меджліс-і Мебусан", "e770b540"], "d": ["Після різкої критики депутатів, які покладали на уряд і двір відповідальність за катастрофічний кінець війни, Абдул-Гамід II, спираючись на повноваження, надане йому конституцією (Канун-і Есасі), безстроково припинив роботу парламенту. Так закрився перший османський парламент, який пропрацював близько одинадцяти місяців, і почалася тридцятирічна доба деспотичного правління (істібдаду). Парламент зміг знову зібратися лише після революції 1908 року.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Сан-Стефанський договір: проєкт Великої Болгарії", "2c7cc611"], "d": ["Сан-Стефанський договір, який закінчив російсько-турецьку війну 1877–1878 років, створював величезну автономну Болгарію, що сягала Егейського моря та охоплювала Македонію; визнавав незалежність Сербії, Чорногорії та Румунії; залишав Росії Карс, Ардаган, Батум і Догубаязит та, крім того, накладав воєнну контрибуцію, яку неможливо було сплатити. Цей текст, що виводив Росію до Середземного моря, викликав бурхливу реакцію Англії та Австрії. Так і не бувши виконаним, за чотири місяці він був переглянутий на Берлінському конгресі; проте залишився документом, який проголосив кінець османської Румелії.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Окупація Боснії та Герцеговини й Нові-Пазара Австро-Угорщиною", "e5f901df"], "d": ["Спираючись на повноваження, надане Берлінським трактатом, австро-угорські війська вступили до Боснії; хоча османський уряд погодився не чинити опору, місцеве мусульманське та православне населення Сараєва й Мостара взялося за зброю і три місяці чинило запеклий опір. Окупацію вдалося завершити лише 20 жовтня 1878 року. Юридичний суверенітет падишаха на папері тривав до 1908 року, але чотиристолітню османську Боснію фактично було втрачено, і почалася велика хвиля мусульманської еміграції. Інші поселення, втрачені того самого дня: Баня-Лука.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Мухарремський декрет і створення Управління Османського державного боргу", "02b7cc03"], "d": ["Переговори з представниками держав-кредиторів, які велися після банкрутства 1875 року, завершилися декретом від 28 мухаррама 1299 року (20 грудня 1881): основну суму боргу скоротили більш ніж наполовину, натомість найприбутковіші статті доходів — збори із солі, тютюну, шовку, гербовий і рибальський — передали Управлінню Османського державного боргу, яким прямо керували кредитори. Це управління, що мало тисячі службовців, перетворилося на окрему фінансову організацію всередині держави. Цю дату вважають фактичним кінцем османської фінансової незалежності.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Суакін — єдиний порт, який не дістався Махді", "5a37b198"], "d": ["Тим часом як із лютого 1884 року всі області Східного Судану, крім Суакіна, переходили під владу Мухаммада Ахмеда аль-Махді, порт устояв під військовим захистом трьох англійських батальйонів під командуванням генерала Ґрема. Це був початок періоду, коли фактичне та юридичне становище розійшлися: хоча узбережжя фактично перебувало під англійським військовим контролем, 1885 року його адміністративне підпорядкування забрали в Єгипту та передали безпосередньо вілаєтові Ємен, тобто Високій Порті, — і цей порядок тривав, доки 1888 року йому не поклала край окупація Зейли Францією.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Убивство Мідхата-паші у в'язниці в Таїфі", "f4562261"], "d": ["Мідхат-пашу, архітектора конституції (Канун-і Есасі) та символічну постать Першої конституційної доби, на Їлдизькому суді визнали винним у справі про смерть Абдул-Азіза; смертний вирок замінили засланням і відправили його в Таїф. За даними TDV, у ніч із 7 на 8 травня 1884 року його задушили в камері, а офіційною причиною назвали хворобу — карбункул. Його смерть стала символом ліквідації конституційної опозиції за доби Абдул-Гаміда II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Надання німцям концесії на залізницю Хайдарпаша — Анкара", "5705b163"], "d": ["Ірадою падишаха концесію на будівництво та експлуатацію лінії Хайдарпаша — Анкара надали банкірові Альфреду фон Каулі, який представляв Deutsche Bank, і було засновано Товариство Анатолійської залізниці. Ця концесія стала переломним моментом, що зламав англо-французьку монополію в османських шляхах сполучення та зовнішній політиці й утвердив німецький вплив. Разом із концесією на Багдадську лінію, яку через одинадцять років надали тому самому товариству, народилася мрія «Берлін — Багдад», що стала однією з головних осей суперництва великих держав перед Першою світовою війною.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Заснування Товариства османської єдності (Іттіхад-і Османі) в Стамбулі", "b7187939"], "d": ["Четверо учнів Військово-медичної школи заснували Товариство османської єдності як таємну організацію проти деспотичного правління; невдовзі вона перетворилася на комітет «Єднання і поступ», який зібрав під своїм дахом усі опозиційні елементи младотурецького руху. Побудована на принципі осередків організація об'єдналася з вигнанцями в Європі та офіцерами в Салоніках. Із цього маленького учнівського осередку вийшла когорта, яка 1908 року змусила проголосити Другу конституційну монархію, а після 1913 року одноосібно керувала державою.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Напад на Османський банк: акція дашнакських бойовиків у Галаті", "08b3095f"], "d": ["Озброєна група вірменської організації «Дашнакцутюн», щоб привернути увагу Європи до вірменського питання, захопила головну контору Османського банку в Галаті, взяла заручників і погрожувала висадити будівлю в повітря. Криза за посередництва послів скінчилася тим, що бойовиків в обмін на припинення акції вивезли з країни на кораблі. Криваві події в Стамбулі в дні після нападу відіграли визначальну роль у перетворенні вірменського питання на важіль міжнародного втручання.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Початок греко-турецької війни 1897 року: фессалійський фронт", "33e490ab"], "d": ["Після того як Греція висадила на Криті флот і війська, а на румелійському кордоні почалися напади загонів, Османська держава оголосила війну. Османське військо, навчене німецькою реформаторською місією, швидко просувалося у Фессалії та за місяць узяло Ларису, Фарсалу та Домокос; грецьке військо розсипалося. Після втручання великих держав здобуті землі повернули, але війна залишилася єдиною безперечною воєнною перемогою доби Абдул-Гаміда II і не змогла запобігти фактичній втраті Криту.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Надання німцям концесії на лінію Конья — Багдад", "fd8b6cbd"], "d": ["Після візиту кайзера Вільгельма II до Стамбула та Дамаска 1898 року Товариству Анатолійської залізниці надали попередню концесію на лінію від Коньї до Багдада та Басри. Проєкт Багдадської залізниці означав для османів зміцнення центрального контролю над арабськими вілаєтами, а для Німеччини — вихід до Перської затоки. Цей проєкт, проти якого різко виступали Англія та Росія, став однією з найсуперечливіших справ імперіалістичного суперництва, що вело до Першої світової війни.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Початок будівництва Хіджазької залізниці в Дамаску", "62f58f68"], "d": ["Будівництво лінії, яку Абдул-Гамід II наказав прокласти ірадою від 2 травня 1900 року, почали офіційною церемонією в Дамаску 1 вересня 1900 року. Проєкт, здійснений цілком на пожертви, зібрані в ісламському світі, та працею османських інженерів і вояків, скоротив подорож паломників із Дамаска до Медини із сорока днів до п'яти. Це був і престижний твір, що зміцнював духовний авторитет халіфату, і стратегічна інвестиція, що посилювала військовий контроль над Хіджазом.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Мюрцштезька програма: міжнародний контроль за реформами в Македонії", "4c7464da"], "d": ["Після Ілінденського повстання російський та австрійський імператори зустрілися в Мюрцштезі й підготували новий пакет реформ для Македонії. Програма передбачала призначення двох іноземних цивільних агентів при османському генеральному інспекторі, реорганізацію жандармерії європейськими офіцерами та зміну адміністративних кордонів за національним принципом. Висока Порта опиралася, вважаючи це порушенням суверенних прав, але під спільним тиском мусила погодитися; програма стала одним з основних чинників, які прискорили младотурецьку (іттіхадистську) організацію серед молодих офіцерів.", "b56ab15c"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Втрата Сани на користь імама Ях'ї", "e7f876cb"], "d": ["Повстання, яке 1904 року розпочав зейдитський імам Ях'я Хамід ад-Дін, у квітні 1905 року завершилося падінням Сани після облоги; місто вийшло з-під османського управління, а під час облоги спалахнули голод і епідемія. Гірський рельєф Ємену, довжина ліній постачання та місцева легітимність зейдитського імамату від самого початку робили тутешнє османське панування крихким. Місто повернули через п'ять місяців ціною тяжких втрат, але єменська проблема не закрилася до 1918 року.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Їлдизький замах: бомбовий напад на Абдул-Гаміда II", "1ee2e1a6"], "d": ["Організація «Дашнакцутюн» учинила замах, підірвавши біля карети падишаха, який виходив із п'ятничного селямлику, ландо з бомбою годинникової дії; Абдул-Гамідові врятувало життя те, що він затримався на кілька хвилин, розмовляючи із шейх-уль-ісламом. Від вибуху загинуло двадцять шість людей, понад п'ятдесят було поранено. Ця подія ще посилила одержимість падишаха безпекою та його деспотичне правління, що спиралося на мережу таємних агентів; вона стала й темою вірша Тевфіка Фікрета «Мить запізнення».", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Повернення Сани: придушення повстання імама Ях'ї", "dec3b8f9"], "d": ["Повстання, яке почалося 1904 року під проводом зейдитського імама Ях'ї, у квітні 1905 року завершилося падінням Сани, і в місті спалахнули голод та епідемія. Підкріплення під командуванням Алі Ризи-паші та Ахмеда Фейзі-паші операцією, яку вели з 15 липня до 1 вересня 1905 року за підтримки також сил із Таїза, ціною тяжких втрат повернули місто, і повстання було придушене. Єменська операція принесла османському війську десятки тисяч утрат і величезний фінансовий тягар; серед офіцерів у Румелії страх «заслання в Ємен» був однією з головних скарг, що живили іттіхадистську організацію.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Скликання першого Меджліс-і Мебусан Другої конституційної доби", "e7fd2716"], "d": ["Парламент, сформований на двоступеневих виборах, проведених після тридцятирічної перерви, відкрився 17 грудня 1908 року промовою падишаха, а його головою обрали лідера младотурецького руху Ахмеда Ризу-бея. Парламент із депутатів — турків, арабів, албанців, греків, вірмен і євреїв — був останньою великою спробою втілити ідеал османізму. Проте незалежність Болгарії, анексія Боснії та проголошення приєднання Криту до Греції затьмарили цей оптимізм ще до відкриття парламенту.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Армія дії та повалення Абдул-Гаміда II: сходження на престол Мехмеда V Решада", "6a65a704"], "d": ["Армія дії, яка після подій 31 березня вирушила із Салонік, у ніч з 22 на 23 квітня чотирма колонами ввійшла до Стамбула, а 24 квітня здався палац Їлдиз. Генеральні національні збори (Меджліс-і Умумі-і Міллі) 27 квітня ухвалили повалити Абдул-Гаміда II; падишаха відправили в Салоніки, а на престол звели його брата Мехмеда V Решада. Так скінчилося тридцятитрирічне особисте правління, але його заступила нова доба, у якій падишах був символом, а комітет «Єднання і поступ» правив за підтримки війська.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Албанське повстання: збройний опір у Косові та Шкодері", "93ed30c6"], "d": ["Централізаторська податкова політика іттіхадистського уряду, кампанія зі збирання зброї та суперечка про латинську абетку підняли на повстання албанські племена, які доти вважали одними з найвірніших державі. Хоча військо під командуванням Махмуда Шевкета-паші суворо придушило повстання, заворушення знову спалахнули 1911 і 1912 років. Ці повстання виснажили османське військо напередодні Балканської війни та прискорили народження албанського національного руху.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Ушійський договір: поступка Триполітанії та Бенгазі Італії", "4ffa1fd2"], "d": ["Висока Порта, яка перед воєнними приготуваннями балканських держав не наважилася на боротьбу на два фронти, підписала у швейцарському містечку Уші таємний мир з Італією та залишила Триполітанію і Бенгазі. Так Османська держава втратила свою останню землю в Африці; натомість обіцяли повернути окуповані Італією Родос і Додеканес, але цієї обіцянки так і не виконали. Коли договір підписали, Балканська війна вже давно почалася. Унаслідок цієї події Мурзук (Феццан), Гат, Себха, Убарі, Трагхан, Завіла та аль-Катрун (санджак Феццан вілаєту Триполітанія) перейшли під італійське управління.", "5896634d"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Убивство великого візира Махмуда Шевкета-паші в Стамбулі", "68e60e63"], "d": ["Махмуда Шевкета-пашу, призначеного великим візиром після нападу на Високу Порту, убили пострілами по його автомобілю поблизу Чаршикапи, коли він їхав до Військового міністерства. Комітет «Єднання і поступ», поклавши замах на опозицію, розпочав широку хвилю арештів і страт, а партію «Свобода і злагода» фактично ліквідували. Разом із цією подією остаточно встановилася однопартійна диктатура іттіхадистів, що спиралася на тріумвірат Енвера, Талата та Джемаля.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Початок Другої балканської війни: чвари союзників за поділ", "48d088a2"], "d": ["Балканські союзники, не зумівши поділити землі, забрані в османів за Лондонським договором, посварилися між собою; з нападом Болгарії на сербські та грецькі позиції почалася друга війна. Коли на фронт проти Болгарії вийшли також Румунія та Чорногорія, болгарське військо розвалилося. Османська держава, скориставшись цією нагодою, перейшла лінію Мідіє — Енез, проведену Лондонським договором, і повернула Східну Фракію разом з Едірне.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Константинопольський договір: мир із Болгарією та закріплення Едірне", "c8c18b2d"], "d": ["Договір, підписаний між Османською державою та Болгарією після Другої балканської війни, визнав кордоном річку Мерич (Мариця) і юридично закріпив те, що Едірне, Киркларелі, Дідимотика та Східна Фракія залишаються в османів. Дедеагач залишили Болгарії (а Кавала після болгарської окупації восени 1912 року в липні 1913 року перейшла до Греції й була закріплена за нею Бухарестським договором 10 серпня 1913 року); було врегульовано взаємний обмін населенням між двома країнами та права мусульман у Болгарії. Цей текст є гарантією єдиного клаптика землі, який вдалося повернути після балканської катастрофи. Інші місця, приєднані того самого дня: Гюмюльджіне (Комотіні).", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Афінський договір: мир із Грецією та передача Салонік і Яніни", "8e94def7"], "d": ["Договір, підписаний між Османською державою та Грецією, офіційно визнав перехід до Греції втрачених у Балканській війні Салонік, Яніни та Південної Македонії, а від османських прав на Крит відмовилися. Було докладно врегульовано релігійні та майнові права мусульман, які залишилися в Греції, статус вакфів і призначення муфтіїв. Натомість статус егейських островів залишили невирішеним, і він лишився постійним джерелом напруги між двома державами.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Підписання таємного османсько-німецького союзного договору в Стамбулі", "0472efb3"], "d": ["Щойно в Європі вибухнула війна, в особняку великого візира Саїда Халіма-паші підписали таємний союзний договір між Османською державою та Німеччиною; текст передбачав, що в разі вступу Росії у війну проти Німеччини османи також стануть на бік Німеччини. Договір приховали навіть від кабінету: про нього знали лише чотири особи. Через три місяці набіг у Чорному морі фактично втягнув Османську державу у війну, і доля імперії виявилася пов'язаною з цим документом.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Одностороннє скасування капітуляцій", "ec773d18"], "d": ["У момент, коли Європа була зайнята війною, османський уряд оголосив, що з 1 жовтня 1914 року в односторонньому порядку скасовує капітуляції, які надавали іноземцям судові, фінансові та митні привілеї. Припинення цього чотиристолітнього привілейного ладу зустріли в країні з великим піднесенням незалежності, а в Стамбулі влаштували святкування. Усі держави, зокрема союзна Німеччина, протестували проти рішення; остаточно капітуляції відійшли в історію лише 1923 року в Лозанні.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Чорноморський набіг: османський флот бомбардує російські порти", "8ad4ef61"], "d": ["«Ґебен» і «Бреслау» («Явуз» і «Міділлі»), які втекли з Німеччини й увійшли до османського флоту нібито «куплені», під командуванням адмірала Сушона вийшли в Чорне море, обстріляли з гармат російські порти та потопили кораблі. Цей наказ, який Енвер-паша віддав таємно від кабінету, фактично покінчив із нейтралітетом. Протягом тижня Росія, Англія та Франція оголосили війну, і Османська держава безповоротно вступила в Першу світову війну.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Захоплення Фао англо-індійськими силами — відкриття Іракського фронту", "08663813"], "d": ["Уранці наступного дня після оголошення державами Антанти війни Османській державі англо-індійська бригада, що чекала на Бахрейні, висадилася у Фао в гирлі Шатт-ель-Арабу. Невеликий османський загін у зруйнованій фортеці Фао відійшов під вогнем військових кораблів, і станція індійської телеграфної лінії перейшла до рук англійців. Так відкрився Іракський фронт.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Проголошення великого джихаду: читання фетви про джихад у мечеті Фатіх", "2a6174e8"], "d": ["П'ять фетв, виданих шейх-уль-ісламом Юргюплю Хайрі-ефенді, прочитали в мечеті Фатіх від імені халіфа-падишаха, закликавши всіх мусульман до джихаду проти держав Антанти. Цей крок, на який Німеччина покладала великі надії, мав на меті підняти мусульман в англійських і французьких колоніях. Очікуваного загального повстання не сталося; навпаки, повстання меккського еміра шерифа Хусейна за англійської підтримки через два роки гірко показало межі політичного впливу халіфату.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Здача Курни англійцям", "621d36b0"], "d": ["Сили валі Басри Субхі-бея, які після падіння Басри відійшли до Курни, де зливаються Тигр і Євфрат, після боїв 4–8 грудня здалися вранці 9 грудня 1914 року.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Сарикамиська операція: катастрофа на Кавказькому фронті", "5cbde7f0"], "d": ["Щоб повернути Карс, Ардаган і Батум, утрачені 1878 року, та підняти тюрків Кавказу, Енвер-паша взимку кинув 3-тю армію в маневр через гори Аллахуекбер для оточення російських сил. Через недостатнє зимове спорядження, вичерпане постачання та хуртовини з морозами до мінус тридцяти градусів армія розтанула ще до вступу в бій; десятки тисяч вояків замерзли на смерть. Операція стала однією з найтяжчих катастроф османів у війні та на два роки залишила східний фронт беззахисним.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Перша канальська операція: наступ на Суец через Синайську пустелю", "02dd72f5"], "d": ["Командувач 4-ї армії Джемаль-паша, щоб звільнити Єгипет від англійської окупації та перекрити судноплавство Суецьким каналом, організував наступ через Синайську пустелю. Хоча османські частини вийшли на східний берег каналу й деяким удалося переправитися, через англійську перевагу та те, що очікуване народне повстання в Єгипті не відбулося, вони відступили. Операція не досягла мети, але, змусивши Англію тримати в Єгипті великі сили, мала непрямий стратегічний вплив.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Ухвалення закону про переміщення та поселення (депортацію, «техджір»)", "2f2bc22c"], "d": ["Після Ванського повстання та російського наступу уряд видав тимчасовий закон, який дозволяв командувачам армій переміщувати в інші області населення, що, за оцінкою, порушувало безпеку в тилу фронту, а падишах затвердив його 27 травня 1915 року. Унаслідок його застосування більшу частину вірменського населення східних і південних вілаєтів Анатолії відправили в напрямку Сирії та Мосула; під час переміщення через хвороби, голод і напади сталися величезні людські втрати. Це рішення залишилося найтяжчою і донині найсуперечливішою проблемою останніх років Османської держави.", "e8af8dee"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Смерть Абдул-Гаміда II у палаці Бейлербей", "c9662582"], "d": ["Помер Абдул-Гамід II, якого 1909 року скинули з престолу й відправили спершу в Салоніки, а після втрати міста в Балканській війні перевезли до Стамбула та тримали під наглядом у палаці Бейлербей. Протягом тридцятитрирічного правління він намагався виграти час, утримуючи державу від воєн, але запам'ятався й деспотичним правлінням. Його поховали за участю великого натовпу в тюрбе Махмуда I на вулиці Діванйолу; смерть припала на воєнний рік, коли встановлений ним лад уже давно був ліквідований.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Брест-Литовський договір: повернення Карса, Ардагана та Батума", "da82636f"], "d": ["Договір між державами Четверного союзу та Росією, яка вийшла з війни після більшовицької революції, закрив східний фронт і повернув Османській державі Карс, Ардаган і Батум (Ельвіє-і Селясе — «три санджаки»), втрачені за Берлінським трактатом 1878 року. Це було єдине територіальне здобуття в османській історії після сорокарічної перерви. Проте після Мудроського перемир'я цю область знову втратили, а остаточне розв'язання принесли Карський договір 1921 року.", "f6f15123"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Смерть Мехмеда V Решада та сходження на престол Мехмеда VI Вахідеддіна", "d302ba07"], "d": ["Мехмед V Решад, дев'ятирічне правління якого минуло у війнах за Триполітанію, балканських і світовій, помер у найкритичніший період війни, і на престол під іменем Мехмеда VI зійшов його брат Вахідеддін. Новий падишах намагався звільнитися від опіки іттіхадистської когорти; коли через чотири місяці підписали перемир'я, йому довелося керувати ліквідацією імперії. Він був тридцять шостим і останнім падишахом османської династії.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Прибуття флоту Антанти до Стамбула та фактична окупація міста", "d10cb14d"], "d": ["Після Мудроського перемир'я союзний флот із понад шістдесяти англійських, французьких, італійських і грецьких кораблів став на якір перед Долмабахче, і Стамбул фактично опинився під окупацією. Уперше за чотириста шістдесят п'ять років столиця перейшла під контроль іноземних військ. Слова «Як прийшли, так і підуть», які, за переказом, того самого дня сказав Мустафа Кемаль-паша, зійшовши в Хайдарпаші й побачивши цю картину, стали однією із символічних фраз національно-визвольної боротьби.", "30db4974"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Ерзурумський конгрес: рішення східних вілаєтів про національний опір", "41ef0457"], "d": ["Конгрес, скликаний Товариством захисту прав Східної Анатолії, після відкладення під англійським тиском відкрився з п'ятдесятьма шістьма делегатами, а головою обрали Мустафу Кемаля-пашу, який залишив військову службу. Конгрес проголосив, що батьківщина в національних кордонах є єдиним цілим, що мандат і протекторат неприйнятні, а в разі розпаду уряду нація візьме свою долю у власні руки. Ці рішення через шість місяців стали ядром тексту Національної обітниці (Місак-і Міллі).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Сіваський конгрес: об'єднання національного опору під одним дахом", "0e9ad36b"], "d": ["Конгрес, який розпочав роботу 4 вересня 1919 року в сіваському султанському ліцеї, об'єднав товариства захисту прав з усіх куточків країни під назвою Товариства захисту прав Анатолії та Румелії й обрав Представницький комітет. Пропозицію про американський мандат після тривалих дискусій відхилили. З декларацією, оприлюдненою 11 вересня, національно-визвольна боротьба стала легітимним політичним рухом з єдиним центром, і почалося відкрите змагання за владу зі стамбульським урядом.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Амасійський протокол: переговори стамбульського уряду з Представницьким комітетом", "40e6a6ab"], "d": ["Після падіння Дамада Феріда та формування уряду Алі Ризи-паші морського міністра Саліха-пашу відрядили в Амасью для переговорів із Представницьким комітетом. Досягнутими протоколами стамбульський уряд фактично визнав існування анатолійського руху; було погоджено скликати Меджліс-і Мебусан, провести вільні вибори та захистити національні кордони. Це перший офіційний політичний здобуток національно-визвольної боротьби щодо Стамбула.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Ухвалення Національної обітниці останнім османським парламентом", "6322865e"], "d": ["Текст Національної обітниці (Ахд-і Міллі), підписаний 121 депутатом в останньому османському Меджліс-і Мебусан, ставив умовами неподільну цілісність земель у межах мудроської лінії, де переважало мусульмансько-турецьке населення, всенародне голосування в арабських вілаєтах і Західній Фракії, скасування капітуляцій і повну політичну та фінансову незалежність. 17 лютого 1920 року текст ухвалили одноголосно та оголосили світові. Ця декларація була і політичною програмою національно-визвольної боротьби, і картою кордонів, які обстоювали в Лозанні; вона стала прямою причиною офіційної окупації Стамбула державами Антанти 16 березня.", "576d2af5"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Гюмрійський (Александропольський) договір: перший міжнародний договір уряду Великих національних зборів Туреччини", "9232c690"], "d": ["Коли армія східного фронту під командуванням Казима Карабекіра повернула Сарикамиш і Карс, Вірменія попросила миру та договором, підписаним у Гюмрі, погодилася, що не визнає Севрського договору й відмовляється від територіальних вимог на сході. Цей перший договір, підписаний анкарським урядом, став першим міжнародним документом, який фактично відкидав Севр, і відкрив Великим національним зборам Туреччини шлях до юридичного визнання. Так було забезпечено східний кордон, і стало можливим перекинути сили на західний фронт.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Перша битва під Іненю: перша перемога регулярної армії", "4add3719"], "d": ["Новостворена регулярна армія на позиціях під Іненю зупинила грецькі сили, що наступали в напрямку з Бурси, та змусила їх відступити. Цей обмежений за військовим масштабом успіх мав величезні політичні наслідки: анкарський уряд запросили на Лондонську конференцію, відкрився шлях до Московського договору з Радянською Росією та було ухвалено Закон про основну організацію (Тешкілят-і Есасіє). Ця перемога зміцнила також довіру внутрішньої громадськості до регулярної армії.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Друга битва під Іненю: грецький наступ зламано вдруге", "a974521c"], "d": ["Грецьке військо, чий уряд не здобув нічого на Лондонській конференції, розпочало новий наступ із напрямків Бурси та Ушака, але його знову зупинили на хребтах Іненю, і воно мусило відступити. Телеграму Мустафи Кемаля-паші Ісметові-паші «Ви перемогли там не лише ворога, а й лиху долю нації» написано після цієї перемоги. Битва піднесла міжнародний авторитет національно-визвольної боротьби та прискорила відхід Італії з Анатолії.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Анкарська угода: мир із Францією та закриття південного фронту", "35fc32db"], "d": ["Угода, підписана з Францією в Анкарі після перемоги на Сакар'ї, припинила війну на південному фронті; французькі війська звільнили Чукурову та Південний Схід, зокрема Адану, Антеп, Мараш і Урфу, і відійшли до сирійського кордону. Так одна з держав Антанти фактично визнала анкарський уряд, а в севрському фронті з'явилася перша тріщина. Зброя, отримана зі звільнених областей, і вивільнені частини відіграли вирішальну роль у підготовці Великого наступу.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Муданійське перемир'я: передача Стамбула та Проток без війни", "ac0d9baf"], "d": ["Коли після Великого наступу турецька армія зіткнулася з англійськими силами під Чанаккале та Ізмітом, конференція, скликана в Муданьї, після одинадцяти днів напружених торгів закінчилася перемир'ям. Було погоджено, що протягом п'ятнадцяти днів Греція звільнить Східну Фракію до Мерича й вона перейде під турецьке управління, а Стамбул і Протоки передадуть за мирним договором. Так збройний етап національно-визвольної боротьби завершився дипломатичною перемогою, здобутою без жодного пострілу, і відкрилися двері Лозанни.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Від'їзд Мехмеда VI Вахідеддіна зі Стамбула та обрання Абдул-Меджида-ефенді халіфом", "8ab0e847"], "d": ["Мехмед VI Вахідеддін, останній падишах, становище якого після скасування султанату стало спірним, уранці в п'ятницю 17 листопада 1922 року покинув Стамбул на англійському броненосці «Малая» та вирушив на Мальту. Через два дні, 19 листопада, Великі національні збори Туреччини обрали Абдул-Меджида-ефенді халіфом без політичних повноважень. Так фактично скінчилося шістсот двадцять трирічне правління османської династії; халіфат же символічно проіснував ще п'ятнадцять місяців. Вахідеддін, переїхавши на Мальту, а потім до Італії, оселився на віллі Нобеля в Сан-Ремо; його звернення про прийняття в якійсь мусульманській країні нічого не дали, і 16 травня 1926 року він помер там, повторюючи, що ніколи не зрікався своїх прав на султанат і халіфат.", "86831a04"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Коринф (Ґьордюс) перейшов до Морейського деспотату", "392495eb"], "d": ["Коринф, який з 1358 року був леном флорентійської родини Аччайолі, залежним від Ахейського князівства, 1395 року перейшов до рук візантійського деспота Мореї Феодора. Відтоді й до османського завоювання місто залишалося під управлінням деспотату.", "1803a03a"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Завоювання Коринфа (Ґьордюса)", "87a2bc59"], "d": ["Під час морейського походу Фатіха фортецю Акрокоринф облягали три місяці, і зрештою її взяли мирним шляхом. Так Коринфський перешийок, який вважали воротами Мореї, перейшов до османів.", "b2be3a05"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Залишення Коринфа (Ґьордюса) Венеції", "9a25b6b9"], "d": ["Після падіння Патр Коринф мирним шляхом відійшов венеційцям, а мусульманське населення залишило місто. У серпні 1687 року військо Морозіні збиралося в Коринфі для афінського походу.", "d92bcf7d"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Повернення Коринфа (Ґьордюса)", "26f53e3a"], "d": ["Першою великою зупинкою морейського походу Дамада Алі-паші став Коринф; у червні 1715 року османи відібрали місто у венеційців і звідси рушили на решту півострова.", "82e2e719"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Перехід емірату Сабахів у Кувейті під османський протекторат", "3584dba0"], "d": ["За статтею TDV «Кувейт», пристань на початку XVIII століття заснувало плем'я утуб, яке прийшло з Неджду, а наприкінці століття управління перейняла родина Сабахів. У ті самі роки, коли Ель-Ахса перейшла до рук Саудитів, емірат, який під тиском ваххабітів не мав іншого вибору, крім як спертися на Басру, перейшов під османський протекторат. Цей зв'язок офіційно оформить 1871 року реорганізація Басри, проведена Мідхат-пашею, і Кувейт вважатиметься однією з трьох каз санджаку Басра; на цьому записі ґрунтуються й пізніші територіальні претензії Іраку.", "c084f05f"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Кінець Дубровницької республіки — французька окупація", "f8e27bf1"], "d": ["Французи, які за Кампо-Формійським миром (1797) закріпилися на далматинському узбережжі, 27 травня 1806 року захопили Дубровник і поклали край невеликій купецькій республіці. Так припинився трьохсот п'ятдесятирічний залежний статус Дубровника, який із 1458 року, сплачуючи Османській державі данину, зберігав автономію й торговельні привілеї; місто та острів республіки Мльєт (Mljet) на карті переходять під пряме французьке управління.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Втрата Сухума на користь росіян — відкриття східного узбережжя Чорного моря", "adc96bd4"], "d": ["Під час російсько-османської війни 1806-1812 років російський флот рушив до східного узбережжя Чорного моря й узяв Сухум-кале, на який спиралося османське панування в Абхазії. Фортеця була осередком зв'язків із кавказькими племенами та прибережної торгівлі. З її втратою Росія вперше міцно закріпилася на східному березі Чорного моря; османський вплив на Кавказі стиснувся до околиць Анапи та Поті.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Передання Парги під османське управління", "66e0cc5d"], "d": ["Парга з 1401 року перебувала в руках Венеції й ніколи не потрапляла під османське управління; після падіння Венеції вона по черзі переходила до Франції та Англії. Стаття TDV «Тепеделенлі Алі-паша» підсумовує становище так: місто здалося англійцям і лише 1819 року було залишене під управління Алі-паші. Передання завершилося переселенням більшої частини мешканців на Іонічні острови. Так до імперії приєдналася й остання з трійці Превеза-Парга-Воніца, залишеної за Венецією в Пожареваці; Парга залишатиметься османською дев'яносто чотири роки.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Аргос переходить до рук грецьких повстанців", "be66a696"], "d": ["У перші місяці морейського повстання Аргос з околицями вийшов з-під османського управління й перейшов до рук грецьких повстанців; у травні 1821 року місто стане ареною контрнаступу османських сил.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ахмед Кіхая взяв Аргос, місто пограбовано й спалено", "d6d3ac7b"], "d": ["Сили Ахмеда Кіхаї, розбивши греків під Аргосом, пограбували й спалили місто; на короткий час воно повернулося під османський контроль.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Ахмед Кіхая в Аргосі з'єднався з мусульманами Триполіци й вирушив на Триполіцу", "9d679fd5"], "d": ["Ахмед Кіхая, з'єднавшись в Аргосі з мусульманами Триполіци, рушив у бік Триполіци; Аргос знову перейшов під контроль грецьких повстанців.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Перехід Коринфа (Ґьордюса) до грецьких повстанців", "892dcdc6"], "d": ["Під час грецької війни за незалежність Акрокоринф перейшов до рук повстанців, а коменданта фортеці Кяміль-бея взяли в полон.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Махмуд-паша Драмали розташував свою ставку в Аргосі", "c79abbfb"], "d": ["Військо Махмуд-паші Драмали вступило на Аргоську рівнину, і паша влаштував свою ставку в містечку Аргос; місто знову перейшло під османський контроль.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Махмуд-паша Драмали почав відступати з Аргоса", "5e5afb74"], "d": ["Змушений відступити ще до того, як минуло два тижні від заняття Аргоса, Махмуд-паша Драмали почав відводити першу дивізію свого війська в напрямку Коринфа; Аргос знову перейшов до рук грецьких повстанців.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Втрата Нафпліона (Навплія) на користь повстанців", "1a67fa50"], "d": ["Нафпліон, порт із наймогутнішими в Мореї укріпленнями, після блокади, що тривала понад рік, здався через голод. Від самого початку повстання фортеця була останньою великою опорою османського контролю на півострові; з її втратою вся Морея перейшла до рук повстанців. Незабаром місто стало першою столицею нової грецької держави.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Перехід Лепанто під грецьке управління", "c9d19d4b"], "d": ["Лепанто на північному березі Коринфської затоки, яке до грецького повстання залишалося в османських руках, у квітні 1829 року було втрачене й перейшло під грецьке управління; назву містечка змінили на античну — Навпактос. Мусульманське та єврейське населення міста цілковито зникло, і воно перетворилося на невелике містечко.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Французька окупація Алжиру — кінець трьохсотлітнього оджаку", "0be8f568"], "d": ["Скориставшись як приводом інцидентом із віялом, що виник із боргової суперечки, Франція три роки тримала алжирське узбережжя в блокаді, а потім висадила війська в Сіді-Ферруші. Наприкінці тритижневої операції дей Гусейн капітулював, і османський Алжирський оджак, що існував із 1516 року, припинив своє існування. Окупація не обмежилася столицею; того самого літа було втрачено й Тлемсен, Шершель та Медеа у внутрішніх районах. Щоб усе узбережжя опинилося під французьким контролем, знадобилося ще двадцять чотири роки.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Передання Негропонте (Евбеї) Греції — разом з островом (Карістос, Ореї)", "7b524aa4"], "d": ["Негропонте (місто на Евбеї), яке впродовж усієї грецької війни за незалежність було ареною запеклих боїв, але залишалося в османських руках, після набуття чинності мирним договором 1831 року передали грекам. Мусульманське населення міста, що з 1470 року було важливою морською базою, розпродало все своє майно за безцінь і гуртом переселилося на османські землі; місто довго залишалося порожнім, а німецький мандрівник Фальмераєр 1842 року назвав його містом-привидом.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Французька окупація Орана", "a8415d66"], "d": ["Оран, який Іспанія передала без війни 1792 року, був найбільшим портом на заході Алжиру. Через шість місяців після падіння столиці французькі частини увійшли в місто. Західна операція, що розпочалася звідси, невдовзі наштовхнулася на опір еміра Абд аль-Кадіра, який тривав п'ятнадцять років.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Окупація Аннаби (Бона)", "21f37fb1"], "d": ["Аннабу, порт Східного Алжиру біля туніського кордону, взяли французькі сили й перетворили на базу для походу на Константину. Водночас місто було найближчим африканським портом навпроти острова Сардинія.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Передання Афін новій грецькій державі (день, коли баварські війська прийняли Акрополь)", "deee4d37"], "d": ["Афіни, османські з 1456 року, під час грецької війни за незалежність кілька разів переходили з рук у руки, а гарнізон на Акрополі 1827 року знову опинився під османським контролем. Оскільки місто залишалося на північ від кордону, проведеного Лондонським протоколом, його передали новому королівству, і гарнізон залишив Акрополь. Дата в атласі — це день, коли баварські війська прийняли Акрополь; фактичний вихід османського гарнізону відбувся кількома днями пізніше (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, розд. 13; Finlay, Journals and Letters, т. I, с. 67). Наступного року Афіни замість Нафпліона проголосили столицею Греції.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Окупація Беджаї (Бужі)", "a8927e00"], "d": ["Порт Беджая, де гори Кабілії виходять до моря, був останньою незалежною ланкою берегової лінії між Алжиром та Аннабою. Його взяли за підтримки корабельної артилерії; проте гірська внутрішня область позаду нього ще тридцять років не потрапляла під французький контроль. Ці прибережні захоплення й утворюють на карті поступове, рік за роком, танення османського Алжиру.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Окупація Сетіфа", "2073731a"], "d": ["Після того як роком раніше впала Константина, французькі сили вийшли на плоскогір'я, взяли давнє римське місто Сетіф і розмістили в ньому постійний гарнізон. Сетіф був вузлом, де перетиналися караванні шляхи між узбережжям і Сахарою; його окупація показала, що Франція почала контролювати вже не лише порти, а й внутрішню торговельну мережу.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Окупація Біскри — втрата воріт Сахари", "d895cad0"], "d": ["Біскра на південному підніжжі Атлаських гір була воротами до Сахари й осередком оаз фінікових пальм. Із її взяттям у роки, коли опір еміра Абд аль-Кадіра почав ламатися, французький контроль уперше сягнув північного краю пустелі. Далі мала бути вже пустельна кампанія, що просувалася від оази до оази.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Окупація Туггурта — остаточна втрата всього Алжиру", "33c056e2"], "d": ["Із взяттям оазисного міста Туггурт на півночі Сахари окупацію, розпочату 1830 року, було завершено в північній половині сучасного Алжиру. У ці роки Османська держава воювала в Кримській війні на одному боці з Францією; хоча вона ніколи офіційно не відмовлялася від правових претензій на Алжир, фактично не змогла зробити жодного кроку. Єдиною землею, що залишалася в Північній Африці, була Триполітанія.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Падіння Ель-Обейда — перехід Кордофана до сил Махді", "58299f62"], "d": ["Рух, започаткований Мухаммадом Ахмадом, який проголосив себе махді, швидко поширився проти єгипетського управління в Судані. Ель-Обейд, центр Кордофана, упав після чотиримісячної облоги й став столицею повстання; скарбниця та склади зброї в місті дали рухові змогу перетворитися на армію. Юридично Судан усе ще був землею Єгипетського хедивату, пов'язаного з Османською державою, тому на карті ця втрата випадає з основного тіла імперії.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Падіння Хартума — втрата всього Судану", "d4b98464"], "d": ["Після десятимісячної облоги сили Махді увійшли в Хартум, що лежить у місці злиття Блакитного та Білого Нілу; губернатора міста Гордона було вбито, а британська колона, послана на допомогу, спізнилася на два дні. Від цієї дати весь Судан, включно з Сеннаром, Донголою та Кордофаном, чотирнадцять років перебував під управлінням Держави махдистів. Лише 1899 року, з остаточно розірваним османським зв'язком, область перейшла під спільне англо-єгипетське управління.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Італійська окупація Массауа — втрата західного узбережжя Червоного моря", "c333b95b"], "d": ["Порт Массауа, центр еялету Хабеш, окупувала Італія, скориставшись смутою, яку спричинило поширення махдистського повстання в Судані; це стало ядром італійської Еритреї. Суакін на півночі та архіпелаг Дахлак у морі було втрачено в тому самому процесі. Так припинилося османське панування на західному узбережжі Червоного моря, яке тривало з часів Селіма Явуза, і обидва береги цього моря опинилися в чужих руках.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Італійська окупація Родосу", "e08662c5"], "d": ["Прагнучи посадити Османську державу за стіл переговорів у Триполітанській війні, Італія перенесла бойові дії в Середземне море й висадила війська на Родосі. Острів було взято за кілька днів. Родос, який Сулейман Законодавець здобув 1522 року після тривалої облоги й який утримували триста дев'яносто років, перестав бути найбільшою острівною базою імперії у Східному Середземномор'ї; хоча за Лозаннським договором в Уші це вважалося тимчасовою окупацією, повернути його вже не вдалося.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Італійська окупація Додеканесу", "200aacf2"], "d": ["Протягом тижня після взяття Родосу італійський флот окупував і навколишні острови; згодом цей архіпелаг дістане назву «Додеканес». Більшість островів лежала за кілька миль від анатолійського узбережжя й контролювала південно-східний прохід Егейського моря. За Ушійським договором окупацію в обмін на залишення Триполітанії вважали тимчасовою, але Італія так і не звільнила острови; 1947 року їх передали Греції.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Окупація Коса", "ab246c62"], "d": ["Кос, остання ланка Додеканеської операції, був родючим і густонаселеним островом просто навпроти півострова Бодрум. Із його окупацією всі острови в південно-східному куті Егейського моря опинилися під італійським контролем, а південно-західне узбережжя Анатолії по всій довжині було оточене ланцюгом чужих островів.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Проголошення незалежності Ікарії", "c4452033"], "d": ["На невеликому острові Ікарія між Самосом і Хіосом мешканці в атмосфері непевності, створеній італійськими окупаціями, повстали, вигнали з острова османську жандармерію та проголосили «вільну державу» з власним прапором, поштовою маркою й зборами, яка проіснувала п'ять місяців. У листопаді 1912 року острів приєднався до Греції. Попри незначні розміри, ця подія є виразним свідченням того, як розпадалася центральна влада в Егеїді.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Вихід Самосу з-під османського управління", "3a862f2b"], "d": ["Самос із 1832 року був автономним князівством, що платило Османській державі податок і яким правив бей, призначений зі Стамбула. У вакуумі, створеному Триполітанською війною, прихильники об'єднання на острові захопили управління, і устрій автономного князівства фактично припинив існування; того самого року острів проголосив приєднання до Греції. Цей острів, віддалений на два кілометри від анатолійського узбережжя, став однією з перших утрачених земель в Егеїді.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Падіння Яніни — втрата Епіру та Парги", "d42fce18"], "d": ["Яніна, яку під час Балканської війни облягали п'ять місяців, здалася після падіння позицій біля Бізані; разом із містом до Греції перейшов увесь Епір. Тоді ж було втрачено й Паргу, підпорядковану санджаку Яніна, і дев'яносточотирирічне османське управління скінчилося. Втрата Яніни означала, що зачинилося останнє вікно імперії в Адріатику.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Падіння Едірне перед болгарами", "459d2e56"], "d": ["Після облоги, що тривала п'ять із половиною місяців, Едірне, вичерпавши боєприпаси та провіант, здалося; Шюкрю-пашу взяли в полон. Падіння міста, османського з 1361 року й столиці впродовж дев'яноста двох років, вважали найтяжчим ударом Балканської війни. Через чотири місяці, під час Другої Балканської війни, Едірне повернули, скориставшись крахом Болгарії на інших фронтах.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Втрата Янбу на користь сил шерифа Гусейна", "e291c816"], "d": ["Повстання, яке шериф Гусейн розпочав у червні, поширилося на узбережжя Червоного моря; Янбу, порт Медини, за підтримки британського флоту перейшов до рук повстанців. Порт став головними воротами для зовнішнього потоку зброї та грошей на потреби повстання. Так було перерізано морське сполучення сил Фахреддіна-паші в Медині, і місто залишилося саме на кінці Хіджазької залізниці.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Третя битва за Газу — втрата Гази та Хан-Юніса", "c142a069"], "d": ["Після двох невдалих спроб Алленбі під час третього наступу прорвав фронт, обійшовши його з боку Беер-Шеви, і лінія оборони Гази, яку утримували шість місяців, упала. Газу та Хан-Юніс на південь від неї залишили того самого дня. Цей прорив став початком розвалу Палестинського фронту; через п'ять тижнів упаде Єрусалим.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Окупація Комотіні — втрата Західної Фракії", "904d813c"], "d": ["Західна Фракія, яка після Мудроса спочатку опинилася під контролем військ Антанти, за рішенням конференції в Сан-Ремо відійшла Греції, і грецька армія увійшла в Комотіні. Ця область, повернута 1913 року від Болгарії, стала останньою землею, яку імперія втратила в Румелії. Статус турецького населення області через три роки врегулювали в Лозанні режимом меншин. Із цією окупацією кази Комотіні, Ксанті, Дедеагач і Суфлі в Західній Фракії перейшли до Греції.", "ef0aeba3"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Епідемія чуми в Стамбулі та переїзд двору в Едірне", "70c7a163"], "d": ["За статтею «Стамбул» в «Енциклопедії ісламу» TDV, швидке й щільне заселення міста час від часу створювало ґрунт для поширення епідемічних хвороб; під час епідемії чуми 1466 року двір і державні сановники тимчасово перебралися в Едірне. Населення міста в таких епідеміях зазнавало значних втрат.", "7b20238c"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Відкриття навчання в медресе Сахн-и Семан", "021f2a83"], "d": ["За статтею «Сахн-и Семан» в «Енциклопедії ісламу» TDV, ці вісім медресе, засновані в комплексі Фатіха, були задумані як навчальний заклад найвищого рівня тієї доби й утворювали вершину ієрархії османської ільмійє (улемського стану). Викладання в них і їх закінчення в наступні століття вважалися найпрестижнішим щаблем у кар'єрі каді та мюдерриса.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Завершення палацу Топкапи (Нового палацу, Сарай-и Джедід)", "d2db6323"], "d": ["За статтею «Палац Топкапи» в «Енциклопедії ісламу» TDV, джерела того часу розходяться щодо дат початку й завершення будівництва; згідно з датою 883 (1478) рік на написі Баб-и Гюмаюн, будівництво, розпочате за наказом Фатіха, ймовірно, 1465 року, до цього року було здебільшого завершене, і палац перебрав роль осередку держави від старого палацу. Так падишах переїхав до нової резиденції, яка на три століття стала адміністративним і церемоніальним серцем держави.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Сходження Баязида II на престол у Стамбулі", "9b686d04"], "d": ["За статтею «Баязид II» в «Енциклопедії ісламу» TDV, шехзаде Баязид, санджакбей Амасьї, дізнавшись про смерть батька, швидко прибув до Стамбула й посів престол; за підтримки яничарів він випередив свого брата Джема, який вирушав із Коньї. Під час сходження на престол яничарам роздали звичний для них подарунок із нагоди інтронізації. Ця зміна на престолі також запалила гніт боротьби між двома братами.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Проголошення султаном Джема в Бурсі", "b355168a"], "d": ["За статтею «Султан Джем» в «Енциклопедії ісламу» TDV, Джем, який через Караман дістався Бурси, захопив місто, проголосив себе султаном і наказав прочитати хутбу на своє ім'я. Це нетривале султанування закінчилося, коли сили, надіслані його старшим братом Баязидом II, розбили Джема під Єнішехіром. Після поразки Джем був змушений тікати в бік Єгипту.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Страта Ґедіка Ахмед-паші", "6d75a58c"], "d": ["За статтею «Ґедік Ахмед-паша» в «Енциклопедії ісламу» TDV, пашу, відомого походом на Отранто та перебуванням на посаді великого візира, стратили в Едірне за наказом Баязида II через його позицію у справі султана Джема та занепокоєння щодо його впливу. Смерть одного з найдосвідченіших полководців доби Фатіха викликала широкий відгомін при дворі.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Заснування першої друкарні в Стамбулі", "04475930"], "d": ["За статтею «Друкарня» (Matbaa) в «Енциклопедії ісламу» TDV, єврейські переселенці з Іспанії, брати Давид і Самуїл ібн Нахміас, заснували в Стамбулі першу друкарню, що друкувала єврейським шрифтом. Це зафіксовано як першу друкарську ініціативу, що діяла на османських землях; друк турецькою арабським письмом став можливим набагато пізніше, у XVIII столітті.", "118df98b"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Землетрус «Малий кінець світу» в Стамбулі", "53e3b1d6"], "d": ["За статтею «Стамбул» в «Енциклопедії ісламу» TDV, сильний землетрус, що вразив місто, у народі називали «Малим кінцем світу»; тяжких пошкоджень зазнали мури, мечеті та багато будівель, загинуло дуже багато людей. За наказом Баязида II у місті розгорнули масштабну кампанію ремонту й відбудови.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Початок повстання Шахкулу", "3d9a4a90"], "d": ["За статтею «Шахкулу Баба Текелі» в «Енциклопедії ісламу» TDV, Шахкулу, якого живила сефевідська пропаганда, зібрав навколо себе в області Теке великі маси туркменів і розпочав масштабне повстання релігійно-суспільного характеру. Це повстання, одна з найсерйозніших криз внутрішньої безпеки тієї доби, глибоко похитнуло центральну владу держави.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Смерть Баязида II дорогою до Дімотики", "c46e98c9"], "d": ["Колишній падишах, який після зречення виїхав зі Стамбула до свого рідного міста Дімотики, рухаючись у ношах-тахтиревані, що долали лише 5-6 км за день, занедужав у селі Абалар поблизу Чорлу й помер 25 рабі аль-авваля 918 року (10 червня 1512). «Енциклопедія ісламу» TDV вважає причину смерті дуже підозрілою; за деякими місцевими та іноземними джерелами, обговорюють імовірність того, що його отруїли. Так після тридцяти одного року правління пішов із життя восьмий падишах із роду Османа Газі.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Страта шехзаде Ахмеда за наказом Селіма Явуза", "65abb2f2"], "d": ["За статтею «Селім I» в «Енциклопедії ісламу» TDV, шехзаде Ахмед, улюбленець свого батька Баязида II та головний суперник у боротьбі за престол, у боротьбі, яку розпочав після сходження брата Селіма, зазнав розгрому на рівнині Єнішехіра, а тікаючи з поля бою, був схоплений і вбитий. Із цією подією Селім здебільшого поклав край боротьбі за престол між своїми братами та племінниками.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Ібрагіма-пашу призначено великим візиром", "9c94c1e3"], "d": ["За статтею «Ібрагім-паша Макбул» в «Енциклопедії ісламу» TDV, Ібрагім-паша, піднесений з посади начальника особистих покоїв (хас-одабаши) до бейлербея Румелії й того самого дня — до великого візирства, став великим візиром 13 шаабана 929 року (27 червня 1523). Це було безпрецедентне призначення — прямий перехід із палацової служби на посаду великого візира, — яке свідчило про надзвичайну близькість Ібрагіма-паші до Сулеймана Законодавця.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Хайреддіна-пашу Барбароссу призначено капудан-пашею", "a0ff6bab"], "d": ["За статтею «Барбарос Хайреддін-паша» в «Енциклопедії ісламу» TDV, Хайреддіна-пашу, відомого своїми успіхами в Алжирі, 6 квітня 1534 року викликали до Стамбула й призначили капудан-пашею та бейлербеєм Джезаїр-і Бахр-і Сефід (островів Білого моря). Це призначення вважають початком реорганізації османського флоту та інституціоналізації морської могутності в Середземномор'ї.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Рюстем-паша вперше став великим візиром", "ddfcc014"], "d": ["За статтею «Рюстем-паша» в «Енциклопедії ісламу» TDV, після того як Хадима Сулеймана-пашу звільнили з посади через конфлікт з одним із візирів, 17 рамадана 951 року (2 грудня 1544) великим візиром призначили Рюстема-пашу. Рюстем-паша, близькість якого до двору зросла завдяки шлюбу з Міхрімах-султан, із цією посадою став одним із найвпливовіших державних діячів доби Сулеймана Законодавця.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ебуссууд-ефенді став шейх-уль-ісламом", "11ed04f8"], "d": ["За статтею «Ебуссууд-ефенді» в «Енциклопедії ісламу» TDV, Ебуссууд-ефенді, який вісім років був кадіаскером Румелії, у шаабані 952 року (жовтень 1545) був призначений шейх-уль-ісламом і залишався на цій посаді двадцять вісім років і одинадцять місяців. Відомий своїми фетвами, які узгодили канун-наме Сулеймана Законодавця з шаріатським правом, Ебуссууд-ефенді відіграв визначальну роль у формуванні правових та освітніх інституцій свого часу.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Помер Хайреддін-паша Барбаросса", "3378a0bf"], "d": ["За статтею «Барбарос Хайреддін-паша» в «Енциклопедії ісламу» TDV, після короткої хвороби він помер у Стамбулі 6 джумада аль-авваля 953 року (5 липня 1546). Смерть Барбаросси, похованого в усипальні при медресе, яке він сам збудував у Бешикташі, сприйняли як завершення доби в тій середземноморській перевазі, яку створив османський флот.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Розпочалося будівництво мечеті Сулейманіє та її комплексу", "101ec36f"], "d": ["За статтею «Мечеть і комплекс Сулейманіє» в «Енциклопедії ісламу» TDV, комплекс, фундамент якого заклали 1550 року під керівництвом головного архітектора Мімара Сінана, був задуманий як великий суспільний комплекс, до якого, крім мечеті, входили медресе, лікарня (дарюшшифа), імарет і бібліотека. Це будівництво було однією з найбільших будівельних програм, що символізували могутність правління Сулеймана Законодавця та розбудову Стамбула.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["У Стамбулі та околицях почалася нова хвиля чуми", "547d6bf6"], "d": ["За статтею «Таун» (чума) в «Енциклопедії ісламу» TDV, одна з епідемій XVI століття, що охопила ісламський світ, тривала в 1552-1566 роках і особливо вразила Стамбул, Анатолію, Румелію, Єгипет і Північну Африку. Розширення торговельних шляхів і зростання рухливості населення називають серед чинників, що в наймогутнішу добу імперії полегшували поширення епідемій.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Кару Ахмед-пашу призначено великим візиром", "a7d7748e"], "d": ["За статтею «Кара Ахмед-паша» в «Енциклопедії ісламу» TDV, Кару Ахмед-пашу, який був другим візиром, після раптового звільнення чинного великого візира 27 шавваля 960 року (5 жовтня 1553) піднесли до великого візирства. Ця зміна, що припала на ті самі дні, що й страта шехзаде Мустафи, вказує на період, коли співвідношення сил усередині двору швидко змінювалося.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Капудан-пашу Пірі Реїса страчено", "3b2ad7a0"], "d": ["За статтею «Пірі Реїс» в «Енциклопедії ісламу» TDV, коли до Єгипту дійшли звинувачення, що, знімаючи облогу Ормуза, він за хабар пограбував майно мусульман і покинув своє військо на полі бою, славетного мореплавця та картографа наприкінці 960 року (кінець 1553) стратили в Каїрі. Смерть Пірі Реїса, майно якого конфіскували, оцінюють як наслідок суперництва між пашами в тогочасній морській політиці щодо Басри та Індійського океану.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Кару Ахмед-пашу страчено, Рюстем-паша знову став великим візиром", "9a85076a"], "d": ["За статтями «Рюстем-паша» та «Кара Ахмед-паша» в «Енциклопедії ісламу» TDV, замість Кари Ахмед-паші, якого раптово стратили під час засідання дивану 13 зу-ль-каади 962 року (29 вересня 1555), того самого дня за підтримки Хюррем-султан і Міхрімах-султан великим візиром удруге призначили Рюстема-пашу. Закулісний бік події джерела залишають нез'ясованим, і її оцінюють як наслідок палацових інтриг.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Померла Хюррем-султан", "1ae998b5"], "d": ["За статтею «Хюррем-султан» в «Енциклопедії ісламу» TDV, Хюррем-султан, яка як хасекі-султан Сулеймана Законодавця роками мала великий вплив у палаці, померла в Стамбулі 26 джумада аль-ахіра 965 року (15 квітня 1558) і була похована у своїй усипальні в комплексі мечеті Сулейманіє. Зі смертю Хюррем-султан, яка після смерті валіде-султан Хафси 1534 року зміцнила свою владу над гаремом, зник і стримувальний вплив, що стояв на заваді боротьбі за престол між її синами Баязидом і Селімом.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Соколлу Мехмед-паша піднісся до великого візирства", "896391a2"], "d": ["За статтею «Соколлу Мехмед-паша» в «Енциклопедії ісламу» TDV, Соколлу Мехмед-паша, який піднісся до великого візирства після смерті Семіза Алі-паші 30 зу-ль-каади 972 року (29 червня 1565), став останнім великим візиром Сулеймана Законодавця та, залишаючись на посаді й після нього за Селіма II і Мурада III, став одним із великих візирів, які найдовше обіймали цю посаду в історії Османської держави.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Селім II прибув до Стамбула й зійшов на престол", "0289ef97"], "d": ["Після смерті Сулеймана Законодавця під Сігетваром Соколлу Мехмед-паша, щоб не порушити порядок, тижнями тримав цю звістку в таємниці. За «Енциклопедією ісламу» TDV, Селянікі називає датою прибуття Селіма до Стамбула 15 рабі аль-авваля 974 року (30 вересня 1566), тоді як більшість сучасних істориків вважають правильним 9 рабі аль-авваля (24 вересня). Про смерть Сулеймана Законодавця офіційно оголосили лише 24-25 жовтня 1566 року в Белграді.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Відбудований Киличем Алі-пашею флот спустили на воду", "d0fc9f48"], "d": ["Після тяжкої поразки під Лепанто (7 жовтня 1571) кораблі всю зиму будували на верфях. За «Енциклопедією ісламу» TDV, 1 сафара 980 року (13 червня 1572) новий флот із 250 галер і близько 300 галіотів добровільних реїсів вийшов у море як демонстрація сили.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["На Соколлу Мехмед-пашу вчинили замах і вбили його", "6ffa8dec"], "d": ["Соколлу Мехмед-пашу, який чотирнадцять років був великим візиром за трьох падишахів, 20 шаабана 987 року (12 жовтня 1579) заколов кинджалом дервіш, який наблизився до нього на післяобідньому дивані в його особняку, наче бажаючи подати прохання. За «Енциклопедією ісламу» TDV, обговорюють, чи не був замах пов'язаний із помстою за страченого шейха хамзавійя Хамзу Балі.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Перша торговельна ахднаме з Англією — англійцям надано капітуляції", "59c8e3ee"], "d": ["Англійський представник Вільям Гарборн, якого в жовтні 1578 року відправили до Стамбула, за підтримки Соколлу Мехмед-паші та Ходжі Садеддіна-ефенді отримав від Мурада III ахднаме 1580 року. За цією ахднаме англійські купці дістали право однаковою мірою користуватися торговельними привілеями (капітуляціями), раніше наданими французам і венеційцям. Між королевою Єлизаветою I та Мурадом III відбувся обмін листами, і між двома державами було встановлено офіційні відносини. Одразу після цих привілеїв, 1581 року, в Лондоні заснували Левантійську компанію; англійці до 1825 року вели торгівлю в регіоні через неї.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Стамбульську обсерваторію зруйновано за хатт-і хумаюном", "3bc0c78c"], "d": ["Під впливом фетви про те, що обсерваторії приносять країнам нещастя, та опозиції при дворі за хатт-і хумаюном від 4 зу-ль-хіджжа 987 року (22 січня 1580) Стамбульську обсерваторію разом з усіма приладами зруйнували. За «Енциклопедією ісламу» TDV, це був швидкий кінець установи, заснованої Такіюддіном ар-Расідом.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["На площі Атмейдани почалося свято обрізання шехзаде Мехмеда", "c2926d5d"], "d": ["Шехзаде Мехмеда, сина Мурада III, обрізали під час пишних урочистостей, що почалися 6 джумада аль-авваля 990 року (29 травня 1582) і тривали п'ятдесят шість — п'ятдесят сім днів. За «Енциклопедією ісламу» TDV, гуляння на площі Атмейдани були одними з найрозкішніших придворних святкувань тієї доби.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Померла валіде-султан Нурбану", "77d0a577"], "d": ["Мати Мурада III Нурбану-султан померла 22 зу-ль-каади 991 року (7 грудня 1583). За «Енциклопедією ісламу» TDV, як валіде-султан вона листувалася з венеційським і французьким дворами, а сенат Венеції того самого року погодився надіслати їй у відповідь на її послуги подарунок вартістю 2000 венеційських золотих.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Через псування акче спалахнув «інцидент бейлербея»", "db2f2e61"], "d": ["Коли держава стала розплачуватися акче зі зменшеним умістом срібла, сипахи та яничари оточили палац і здійняли кривавий бунт, що ввійшов в історію як «інцидент бейлербея». За статтею «Абдюлькадір Шейхі-ефенді» в «Енциклопедії ісламу» TDV, через цю подію шейх-уль-іслама звільнили з посади.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Мехмед III зійшов на престол, дев'ятнадцятьох шехзаде задушили", "2cd9a8c5"], "d": ["Мехмед III після смерті батька Мурада III прибув до Стамбула в п'ятницю 16 джумада аль-авваля 1003 року (27 січня 1595) й посів престол. За «Енциклопедією ісламу» TDV, тієї самої ночі задушили дев'ятнадцятьох шехзаде, з-поміж них чотирьох дорослих (Мустафу, Баязида, Османа та Абдаллаха); це було наймасовіше братовбивство в історії Османської держави.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Сафіє-султан набула впливу як валіде-султан", "000bec21"], "d": ["Сафіє-султан, дружина Мурада III та мати Мехмеда III, зі сходженням сина на престол у статусі валіде-султан піднеслася до визначального становища в придворній політиці. За «Енциклопедією ісламу» TDV, у цей період вплив, що походив із гарему, сягнув прямого втручання в державні справи.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Мехмед III під тиском яничарів особисто вирушив у похід", "d3c50656"], "d": ["Попри заперечення великого візира Дамада Ібрагіма-паші, під тиском яничарів 20 червня 1596 року Мехмед III вирушив зі Стамбула в похід, ставши першим після Сулеймана Законодавця падишахом, який особисто очолив військо. За «Енциклопедією ісламу» TDV, це означало відродження давньої традиції ґази.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Епідемія чуми, що почалася в 1570-х роках, і далі вражала Стамбул", "eb4ca37a"], "d": ["За статтею «Таун» (чума) в «Енциклопедії ісламу» TDV, епідемія, що почалася в 1570-х роках, тривала до початку XVII століття й уразила насамперед Стамбул, а також Анатолію, Балкани, Єгипет і Північну Африку. Періоди епідемії становили хронічну загрозу, яка часто порушувала життя двору й міста.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Помер Караязиджи Абдюльхалім, повстанський рух ослаб", "876ca7a6"], "d": ["Караязиджи Абдюльхалім, який після тяжкої поразки 12 серпня 1601 року під Сепетлі поблизу Ельбістана відступив пораненим, помер 1010 року (1602). За «Енциклопедією ісламу» TDV, звістка про його смерть дійшла до Стамбула в рамадані 1010 року (лютий — березень 1602); джерела зазначають, що спірно, чи помер він від рани, чи його вбили власні люди.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Фактичне припинення традиції братовбивства", "9046c607"], "d": ["Під час сходження на престол Ахмед I, на відміну від попередніх падишахів, не наказав убити свого брата шехзаде Мустафу, а подарував йому життя; це рішення вважають початком фактичного запровадження в османській системі спадкування принципу старшинства (екбер-і ершед). Стаття «Мустафа I» в «Енциклопедії ісламу» TDV повідомляє, що відтоді Мустафа жив у палаці в усамітненні. Ця практика фактично поклала край убивствам під час сходження на престол, які тривали століттями.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Закладено фундамент мечеті Султанахмет", "1683262f"], "d": ["За наказом Ахмеда I на площі Атмейдани урочисто заклали фундамент мечеті, яку мав збудувати архітектор Седефкяр Мехмед-ага. За статтею «Мечеть і комплекс султана Ахмеда» в «Енциклопедії ісламу» TDV, ця споруда, перша велика султанська мечеть, збудована безпосередньо коштом скарбниці без жодної перемоги-завоювання, стала також предметом тогочасної критики. Комплекс був задуманий так, щоб разом із мечеттю охоплювати медресе, імарет і усипальню.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Убивство Османа Молодого яничарами (Хаїле-і Османіє)", "324f6582"], "d": ["Яничари та сипахи, які повстали через чутки, що він під приводом хаджу має намір виїхати зі Стамбула та розпустити яничарський корпус, скинули Османа II з престолу й наказали задушити його в підземеллях Єдікуле. За статтею «Осман II» в «Енциклопедії ісламу» TDV, ця подія — перший в османській історії випадок, коли падишаха відкрито вбили внаслідок військового бунту, і вона спричинила глибокий розлом у відносинах між династією та військом. Останні години його життя минули так: коли спроба сховатися в особняку яничарського аги Алі-аги не дала результату, падишаха, за висловом TDV, «у жалюгідному вигляді, з непокритою головою й у понівеченому одязі» посадили на шкапу й під тяжкими образами повезли спочатку в Орта-Джамі, де перебував Мустафа I, а того самого дня пополудні — в Єдікуле; на думку деяких істориків, щоб довести його смерть, йому відрізали вухо та ніс і показали їх матері Мустафи I. Після цієї події Мустафу I вдруге посадили на престол. Подія, відома як «Хаїле-і Османіє» (трагедія Османа), надовго порушила рівновагу між двором і корпусом та започаткувала суперечки про легітимність, які тривали ціле століття.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Друге сходження Мустафи I на престол", "34a0b29a"], "d": ["Після вбивства Османа Молодого яничарами, оскільки в династії не було іншого дорослого чоловіка, Мустафу I вдруге посадили на престол. За статтею «Мустафа I» в «Енциклопедії ісламу» TDV, це друге султанування, так само як і перше, минуло без того, щоб він міг фактично вести державні справи, і управління державою опинилося в руках візирів та валіде-султан. Ця чотирнадцятимісячна доба закінчилася 1623 року зі сходженням на престол Мурада IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Пожежа в Джибалі", "3e42fb08"], "d": ["Пожежа, що спалахнула в Джибалі й під дією вітру швидко поширилася, перетворила на попіл більшу частину Стамбула; за статтею «Стамбул» в «Енциклопедії ісламу» TDV, тогочасні джерела повідомляють, що згоріли тисячі осель. Пов'язування пожежі з дерев'яною забудовою та курінням тютюну стало прямим обґрунтуванням суворої заборони тютюну й кав'ярень, яку невдовзі оголосив Мурад IV. Це лихо було лише однією з великих пожеж, що повторювалися в тогочасному Стамбулі.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Заборона тютюну та кав'ярень Мурадом IV", "5dd71297"], "d": ["Після пожежі в Джибалі, побоюючись пожеж і порушень порядку, Мурад IV заборонив курити тютюн і тримати кав'ярні; до порушників застосовували суворі покарання, аж до смертної кари. За статтею «Мурад IV» в «Енциклопедії ісламу» TDV, падишах проводив настільки сувору політику внутрішньої дисципліни, що, щоб контролювати заборону, сам переодягненим обходив вулиці міста. Ці жорсткі заходи оцінюють як частину зусиль Мурада IV відновити центральну владу.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Епідемія чуми в Стамбулі", "f33f58c5"], "d": ["За правління Мурада IV Стамбул уразила тяжка епідемія чуми, яка зачепила значну частину населення; внутрішньоміська торгівля та повсякденне життя були порушені на місяці. Стаття «Стамбул» в «Енциклопедії ісламу» TDV зазначає, що повторювані епідемії XVII століття серйозно впливали на демографічну рівновагу міста. Під час епідемії двір і еліта на певний час переселилися в сади й павільйони за межами міста.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Крилатий політ Хезарфена Ахмеда Челебі (переказ)", "df474c04"], "d": ["За переказом, який наводить Евлія Челебі, Хезарфен Ахмед Челебі зміг спланерувати на власноруч виготовлених крилах із Галатської вежі аж до Ускюдара; хоча історична достовірність цього спірна, він став символом технічної уяви. Падишах, який спочатку нагородив Хезарфена, згодом, через розголос, спричинений подією, заслав його в Алжир.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Джинджі Ходжа Гусейн-ефенді набуває впливу при дворі", "41d21572"], "d": ["Гусейн-ефенді, знахар-заклинач, якого покликали до палацу лікувати душевні розлади падишаха Ібрагіма, швидко здобув його довіру й піднявся аж до посади кадіаскера Анатолії. За статтею «Гусейн-ефенді, Джинджі Ходжа» в «Енциклопедії ісламу» TDV, цей вплив він використовував для накопичення статків і втручання в тогочасні політичні події. Після смерті Ібрагіма його позбавили всіх посад і 1648 року стратили.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Страта Кеманкеша Мустафи-паші", "0ecc8030"], "d": ["Кеманкеша Мустафу-пашу, який був великим візиром ще з часів Мурада IV і своїми фінансовими реформами забезпечив скарбниці значний надлишок, задушили й стратили після того, як його придворні суперники вплинули на Ібрагіма та звинуватили пашу в організації яничарського бунту. За статтею «Кеманкеш Мустафа-паша» в «Енциклопедії ісламу» TDV, страта відбулася 21 зу-ль-каади 1053 року / 31 січня 1644 року: Кеманкеша Кару Мустафу-пашу задушив кат Кара Алі на ринку Ходжапаша, і поховали його у власній усипальні в Чаршикапи. Його смерть згадують як яскравий приклад нестабільності посади великого візира тієї доби; вона поклала край короткому періоду суворих реформ.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Диван ухвалив Критський похід, і флот вирушив", "9076827e"], "d": ["В імператорському дивані ухвалили розпочати масштабний похід на острів Крит, що належав Венеції, і османський флот під командуванням капудан-паші вирушив зі Стамбула на Крит. За статтею «Крит» в «Енциклопедії ісламу» TDV, це рішення стало політичним початком тривалої доби облоги й війни, що тривала близько двадцяти п'яти років. Початок походу як найбільший зовнішньополітичний захід доби Ібрагіма викликав широкі дискусії серед сановників.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Сходження семирічного Мехмеда IV на престол", "a197a3bc"], "d": ["Одразу після скинення Ібрагіма на престол посадили його сина Мехмеда, якому було лише сім років, і він став падишахом під іменем Мехмеда IV. За статтею «Мехмед IV» в «Енциклопедії ісламу» TDV, таке раннє сходження на престол загострило боротьбу за вплив у палаці між його бабусею Кьосем-султан і матір'ю Турхан-султан. Ця боротьба за владу закінчилася 1651 року вбивством Кьосем-султан.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Реформа збалансованого бюджету Тархунджу Ахмед-паші", "376fc7f2"], "d": ["Великий візир Тархунджу Ахмед-паша, щоб подолати фінансову кризу, спричинену довгими роками війни, запровадив сувору програму ощадності, яка охопила й палацові витрати, і склав перший відомий в османській історії збалансований бюджет (записку Тархунджу). За статтею «Тархунджу Ахмед-паша» в «Енциклопедії ісламу» TDV, ця реформа забезпечила скарбниці значний надлишок, але викликала широке невдоволення в придворних колах і вищій бюрократії. Це невдоволення за рік призвело до його страти.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Інцидент із чинарою (Вак'а-і Вакваккіє)", "4c6ed90f"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Кьопрюлю Мехмед-пашу призначено великим візиром на його умовах", "3a6b7f8f"], "d": ["За статтею «Кьопрюлю Мехмед-паша» в «Енциклопедії ісламу» TDV, майже вісімдесятирічний Кьопрюлю Мехмед-паша прийняв печатку лише після того, як валіде Турхан-султан і Мехмед IV погодилися на тяжкі умови, які він їм поставив: не втручатися в його призначення й не вірити тому, що говорять проти нього. 26 зу-ль-каади 1066 року він став на посаду замість Бойнуеґрі Мехмеда-паші та взявся жорстко відновлювати державну дисципліну.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Придушення руху кадизаделі Кьопрюлю Мехмед-пашею", "5ec3ce84"], "d": ["За статтею «Кадизаделі» в «Енциклопедії ісламу» TDV, щойно обійнявши посаду, Кьопрюлю Мехмед-паша взявся за релігійний конфлікт між колом Кадизаде Мехмеда-ефенді та послідовниками тарикатів. Порадившись з улемами, він, хоча й домігся фірману про страту ватажків руху — Устювані Мехмеда-ефенді, Тюрка Ахмеда та Дівана Мустафи, — замінив це покарання на заслання, і всіх трьох відправили на Кіпр; так закінчився другий етап руху.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Велика пожежа в Стамбулі: згоріла Аґакаписи", "b9253b66"], "d": ["За статтею «Аґакаписи» в «Енциклопедії ісламу» TDV, під час великої пожежі, що спалахнула в липні 1660 року за правління Мехмеда IV, Аґакаписи, офіційна резиденція яничарського аги, згоріла дотла, а потім її відбудували. Ця пожежа була однією з великих міських пожеж, які знову й знову вражали тогочасний Стамбул.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Фазиля Ахмед-пашу Кьопрюлюзаде призначено великим візиром", "c1999b5c"], "d": ["За статтею «Кьопрюлюзаде Фазиль Ахмед-паша» в «Енциклопедії ісламу» TDV, після смерті батька, Кьопрюлю Мехмед-паші, 8 рабі аль-авваля 1072 року (1 листопада 1661) його призначили великим візиром. На відміну від батька, Фазиль Ахмед-паша був відомий як людина лагідної вдачі, побожна й покровитель учених і митців; за понад п'ятнадцять років візирства він заснував у Стамбулі та на завойованих землях бібліотеки й благодійні установи.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Вані Мехмеда-ефенді призначено проповідником мечеті Єні-Джамі та наставником падишаха", "7ea6aaae"], "d": ["За статтею «Мехмед-ефенді, Вані» в «Енциклопедії ісламу» TDV, Вані Мехмед-ефенді, якого покликали до Стамбула, коли Фазиль Ахмед-паша Кьопрюлюзаде став великим візиром, і представили Мехмедові IV, незабаром здобув пильну увагу падишаха. 1665 року, призначений проповідником Єні-Джамі та наставником падишаха, він став одним із найвпливовіших духовних діячів при дворі.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Мерзіфонлу Кару Мустафу-пашу призначено великим візиром", "3d1e836c"], "d": ["За статтею «Мерзіфонлу Кара Мустафа-паша» в «Енциклопедії ісламу» TDV, після смерті Фазиля Ахмед-паші 28 шаабана 1087 року (5 листопада 1676) його призначили великим візиром. Мерзіфонлу, зять і вихованець роду Кьопрюлю з великим досвідом державного управління, став одним із наймогутніших і найвпливовіших великих візирів Мехмеда IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Смерть Вані Мехмеда-ефенді на засланні", "cda714aa"], "d": ["За статтею «Мехмед-ефенді, Вані» в «Енциклопедії ісламу» TDV, Вані Мехмед-ефенді, якого вважають одним із головних, хто переконав падишаха погодитися на Віденський похід, після того як похід закінчився розгромом, під тиском громадської думки потрапив у неласку й був засланий у містечко Кестель біля Бурси. Він помер там 14 зу-ль-каади 1096 року (12 жовтня 1685) і був похований біля входу до мечеті, яку сам збудував.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Призначення Фазиля Мустафи-паші Кьопрюлюзаде великим візиром та його фінансові реформи", "b048570e"], "d": ["За статтею «Кьопрюлюзаде Фазиль Мустафа-паша» в «Енциклопедії ісламу» TDV, Фазиль Мустафа-паша, якого 11 мухаррама 1101 року (25 жовтня 1689) призначили великим візиром, реорганізував порядок збору джизьї на засадах шаріату, боровся з інфляцією мангира та зміцнив скарбницю, переводячи до неї кошти з палацових установ. Крім того, він посилив провінційне управління надійними урядовцями й запровадив місцеві ради на зразок центрального дивану.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Запровадження системи малікяне", "316b8426"], "d": ["За статтею «Малікяне» в «Енциклопедії ісламу» TDV, в останній чверті XVII століття зростання воєнних видатків і зменшення доходів через територіальні втрати ввергли скарбницю в тяжку фінансову кризу. У системі малікяне, запровадженій 1106 (1695) року, відкупникам надавали довічне фіксоване право на податки, і замість короткострокової експлуатації з'явився стимул оберігати виробництво.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Сходження Мустафи II на престол", "b53656c7"], "d": ["За статтею «Мустафа II» в «Енциклопедії ісламу» TDV, Мустафа II, який посів престол у тридцять один рік, проголосив своє султанування, не чекаючи схвалення великого візира та шейх-уль-іслама; церемонію оперізування мечем відбули за кілька днів у мечеті Ескі-Джамі. Падишах, який зійшов на престол у добу, коли після віденського розгрому тривали війни на кількох фронтах, став останнім султаном в османській історії, що особисто вирушав у похід.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Вдруге призначення Фейзуллаха-ефенді шейх-уль-ісламом", "1cf14cff"], "d": ["За статтею «Фейзуллах-ефенді, Сеїд» в «Енциклопедії ісламу» TDV, після сходження Мустафи II на престол 11 шавваля 1106 року (25 травня 1695) його вдруге призначили шейх-уль-ісламом. За цей термін служби, що тривав понад вісім років, його вплив на падишаха поступово зростав.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Призначення Фейзуллахом-ефенді синів на високі посади та накопичене обурення", "a6398280"], "d": ["За статтею «Фейзуллах-ефенді, Сеїд» в «Енциклопедії ісламу» TDV, шейх-уль-іслам отримав від Мустафи II небувалий фірман про те, що його син Фетхуллах-ефенді стане шейх-уль-ісламом після нього, і рано розставив родичів на високих посадах. Ці дії викликали широке невдоволення серед ільмійє, війська й мешканців Стамбула; поєднавшись із чутками про перенесення столиці в Едірне, вони підготували ґрунт для едірнського інциденту 1703 року.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Початок Едірнського інциденту", "5a106458"], "d": ["За статтею «Едірнський інцидент» TDV, рух, що почався з повстання воїнів, які не могли отримати своє утримання (улюфе), швидко переріс у широке повстання, у якому взяли участь яничари, учні медресе, ремісники й простолюд. Головною ціллю бунту був шейх-уль-іслам Фейзуллах-ефенді, якого звинувачували в надмірному втручанні в державні справи. Натовп приблизно у 60 000 людей рушив зі Стамбула до Едірне.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Великовізирство Дамада Ібрагіма-паші з Невшехіра", "8d627a6f"], "d": ["За статтею «Дамад Ібрагім-паша Невшехірлі» TDV, під час мирних переговорів з Австрією, які ще тривали, 8 джумада аль-ахіра 1130 року (9 травня 1718) його призначили великим візиром, і щойно призначений, він узявся за переговори, що мали покласти край війні; за два місяці було підписано Пожаревацький мир (21 липня 1718). За словами TDV, він «хотів займатися суспільними та фінансовими питаннями й прагнув доби миру, яка б змусила забути війни, що довгі роки закінчувалися поразками». Провівши фінансові реформи, він зменшив жалування воїнів і створив у державній скарбниці значний надлишок. Його візирство, що тривало дванадцять років, утворило політичну рамку доби, яка дістала відповідну назву (Доба тюльпанів).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Заснування корпусу тулумбаджі (пожежників)", "f58b0d97"], "d": ["За статтею «Тулумбаджі» TDV, після успіху, якого Ґерчек Давуд, що повернувся з морейського походу 1715 року, досяг із пожежним насосом (тулумбою) під час стамбульських пожеж, великий візир Дамад Ібрагім-паша з Невшехіра доручив йому створити офіційний пожежний корпус. Корпус, заснований у казармах аджемі-огланів із шести офіцерів і п'ятдесяти рядових, 1724 року налічував 150 осіб, а 1755 року — 461. Давуд очолював корпус до своєї смерті 1733 року.", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Будівництво палацу Саадабад", "aec9c65e"], "d": ["За статтею «Саадабад» TDV, на березі річки Кяґитхане збудували великий розважально-прогулянковий комплекс, що складався з палацу, каналу, фонтанів і павільйонів, натхненних французькою палацовою архітектурою. Саадабад, який став наймоднішим місцем розваг тієї доби, увіковічнений у віршах поета Недіма. Під час повстання Патрони Халіля 1730 року комплекс здебільшого зруйнували.", "2698478e"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Дозвіл Ібрагіму Мютеферріка заснувати друкарню", "0659dd0a"], "d": ["За статтею «Ібрагім Мютеферріка» TDV, за фірманом Ахмеда III та фетвою шейх-уль-іслама Абдуллаха-ефенді з Єнішехіра було дозволено заснувати першу турецьку друкарню. Друкарня почала працювати в стамбульському кварталі Явузселім. До своєї смерті 1747 року Мютеферріка надрукував сімнадцять творів у двадцяти трьох томах.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Завершено першу друковану книгу — словник Ванкулу", "684700e8"], "d": ["За статтею «Ібрагім Мютеферріка» TDV, першу працю друкарні — турецький переклад «Сихах аль-Джаугарі» (словник Ванкулу) — було завершено на початку 1729 року. Це була перша книга, надрукована арабським письмом на османських землях, і її вважають початком історії турецького книгодрукування.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Страта Дамада Ібрагіма-паші з Невшехіра", "50c64341"], "d": ["За статтею «Дамад Ібрагім-паша Невшехірлі» TDV, тіло великого візира, якого вбили в палаці під час повстання Патрони Халіля, протягли вулицями Стамбула й покинули поблизу фонтану Ахмеда III на площі Султанахмет. Так кривавим чином закінчилися його дванадцятирічне візирство та Доба тюльпанів.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Зречення Ахмеда III, сходження Махмуда I на престол", "a43f5d40"], "d": ["За статтею «Махмуд I» TDV, під тиском повстанців Ахмед III, отримавши гарантії для себе та своїх дітей, зрікся престолу й особисто посадив на нього свого племінника шехзаде Махмуда. Махмуд I, який посів престол із порадою дядька «візьми державні справи у власні руки, нікому не довіряй», насамперед узявся ламати вплив тієї групи повстанців, яка посадила його на престол.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Реформа артилерійського корпусу Гумбараджі Ахмедом-пашею", "ea3a7c64"], "d": ["За статтею «Гумбараджі» TDV, Ахмед-паша, офіцер французького походження, що прийняв іслам, за великого візира Хекімоглу Алі-паші взявся реформувати на європейський лад організацію бомбардирів-гумбараджі на платні. Він створив нову структуру з 601 особи, безпосередньо підпорядковану великому візиру, з них 300 на платні та 301 з тімарами. За тогочасною технологією він наказав виготовити 100 мортир і 50 000 ядер.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Заснування Хендесехане (першого зразка інженерної школи)", "a77ed1f3"], "d": ["За статтею «Махмуд I» TDV, Гумбараджі Ахмед-паша, заснувавши в Ускюдарі Хендесехане, яку називали також Гумбарахане, давав відібраним з-поміж палацових служителів і бостанджі учням військову освіту, засновану на математиці та геометрії. Цю установу вважають першим зразком інженерних шкіл, що розвинулися пізніше.", "84b5af85"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Початок епідемії чуми в Стамбулі", "9fa82b56"], "d": ["За статтею «Таун» (чума) TDV, епідемія чуми, яка в 1739-1743 роках лютувала в ісламських країнах, у цей період уразила й Стамбул. Стаття зазначає, що епідемії XVIII століття перебігали порівняно легше, ніж у попередні століття. До періодів епідемій зараховують також 1713, 1719, 1728-1729 та 1759-1765 роки.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Пожежа в Ходжапаші", "321c7d0d"], "d": ["За статтею «Мечеть Фатіми-султан» TDV, пожежа в Ходжапаші, що спалахнула вночі, спустошила Високу Порту та її околиці; припускають, що від неї постраждала й мечеть Фатіми-султан у цьому районі. Це лихо, одна з великих пожеж, які вражали Стамбул за Османа III, завдало тяжких руйнувань торговельному та адміністративному центру міста.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Великовізирство Коджі Раґипа Мехмеда-паші", "a1846910"], "d": ["Раґипа-пашу, відомого як поет і дипломат, Осман III призначив великим візиром (після смерті Османа III в жовтні 1757 року він залишився на посаді, отримавши нову печатку від Мустафи III). Поки тривала Семирічна війна, він проводив зважену зовнішню політику, яка тримала Османську державу осторонь європейських конфліктів. Упродовж свого візирства, що тривало шість років, він приділяв увагу й культурній діяльності, зокрема заснуванню бібліотек.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Смерть Раґипа-паші", "6bc19323"], "d": ["Раґип-паша помер після шести років великовізирства. Із його смертю закінчилося найтриваліше й найзваженіше великовізирство доби Мустафи III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Великий стамбульський землетрус і обвал мечеті Фатіха", "2475b4dc"], "d": ["За статтею «Мечеть і комплекс Фатіха» TDV, під час великого землетрусу 1766 року головний купол мечеті повністю обвалився, а стіни зазнали пошкоджень, які неможливо було відремонтувати. Відбудову, розпочату 1767 року за наказом Мустафи III під керівництвом архітекторів Сарима Ібрагіма-ефенді та Іззета Мехмед-бея, завершили 1771 року за новим проєктом, відмінним від старого плану.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Короткочасна спроба артилерійської школи під керівництвом барона де Тотта", "4192260c"], "d": ["За статтею «Імператорське морське інженерне училище» (Mühendishâne-i Bahrî-i Hümâyun) TDV, невдачі російсько-османської війни 1768 року оголили потребу в технічній військовій освіті; короткочасна артилерійська школа, відкрита за участі французького офіцера барона де Тотта, почала діяти в жовтні 1772 року, але залишилася неефективною. Цю спробу вважають попередницею Імператорського морського інженерного училища, заснованого 1775 року.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Селім III зійшов на престол", "00d046d9"], "d": ["Після смерті Абдул-Гаміда I престол посів його племінник Селім III. За статтею «Селім III» в «Енциклопедії ісламу» TDV, новий падишах, який ще шехзаде цікавився реформуванням армій на європейський зразок, невдовзі після сходження на престол почав готувати корінну програму оновлення. За кілька років цю програму називатимуть «Нізам-і Джедід».", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Почалася підготовка реформаторської програми Нізам-і Джедід", "eff78a68"], "d": ["Селім III наказав підготувати всеохопну програму оновлення на основі записок, які він вимагав від державних діячів та іноземних фахівців. За статтею «Нізам-і Джедід» в «Енциклопедії ісламу» TDV, ця програма не обмежилася створенням нової армії; вона переросла в широкий реформаторський рух, що охопив також фінанси, провінційне управління та дипломатію. Упродовж наступних п'ятнадцяти років програма мала і прихильників, і противників.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["У європейських столицях засновано постійні посольства", "2e9dc8a1"], "d": ["Селім III уперше в історії Османської держави відправив у великі європейські центри постійних послів, які мали служити там безперервно. За статтею «Посол» (Elçi) в «Енциклопедії ісламу» TDV, цей крок надав османській дипломатії, яку доти вели лише тимчасові одноразові місії, постійної організації. Головним завданням нових посольств було регулярно повідомляти Стамбулу про політичні та військові події в Європі.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Засновано скарбницю Ірад-і Джедід", "ae5c8ce2"], "d": ["Щоб покрити витрати армії Нізам-і Джедід і програми реформ, створили окрему скарбницю. За статтею «Есхам» в «Енциклопедії ісламу» TDV, серед доходів нової скарбниці були пряма експлуатація деяких мукатаа державою та взяття під контроль продажу есхамів. Це впорядкування було спробою створити нове джерело поза традиційною фінансовою системою.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Почалося повстання Кабакчі Мустафи", "b98eee17"], "d": ["Невдоволення проти Нізам-і Джедід, що накопичувалося, вибухнуло з повстанням ямаків під проводом Кабакчі Мустафи. За статтею «Повстання Кабакчі» в «Енциклопедії ісламу» TDV, повстанці незабаром захопили контроль у Стамбулі й зажадали голів прихильних до Нізам-і Джедід державних діячів. За кілька днів повстання закінчилося скиненням Селіма III з престолу.", "820bdd75"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Взяття Кьопрюхісара та підготовка до заснування Єнішехіра", "39abff03"], "d": ["Захопивши фортеці на перевалах між Бурсою та Ізніком, заклали основу передової ставки, яка мала взяти обидва міста в облогу.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Заснування Єнішехіра", "d3275837"], "d": ["Для керівництва облогами Бурси та Ізніка було засновано перше регулярне османське гарнізонне поселення; тут народився Орхан Газі.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Перша облога Ізніка та завоювання Мармараджика", "cdca2349"], "d": ["Ізнік уперше взяли в облогу, але здобути не змогли (остаточне завоювання — 1331 року); тоді ж взяли сусідню фортецю Мармараджик.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Анатолійський похід каталонських загонів", "4fd940d5"], "d": ["Каталонська компанія, найнята Візантією, щоб зупинити турецький наступ, здобула тимчасові успіхи, але надовго не затрималася; з її відходом наступ прикордонних бейліків прискорився.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Кьосе Міхал приймає іслам і приєднується до османів", "ca0d86e1"], "d": ["Текфур Харманкаї Кьосе Міхал, прийнявши іслам, разом зі своєю фортецею та людьми приєднався до Османа Газі; він став першим османським полководцем візантійського походження.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Орхан-бей фактично перебирає правління", "6dadbefc"], "d": ["Через старість і хворобу Османа Газі фактичне керівництво облогою Бурси та походами перейшло до його сина Орхан-бея (офіційне сходження на престол — 1326 року).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Взяття Муданьї", "0a623368"], "d": ["Узявши Муданью, порт Бурси, перерізали зв'язок міста з морем; облога Бурси перейшла на стадію удушення.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Перехід Акьязи та острова Імрали в руки османів (дати в джерелах немає)", "380c60ce"], "d": ["За доби Осман-бея (у роки після походу 1305 року) Акьязи стала мішенню османських набігів; точний рік остаточного взяття невідомий. Коли було взято острів Імрали, не повідомляє жодне джерело. Кордон 1324 року на карті є тимчасовим заповнювачем.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Акча Коджа захопив Кандиру та околиці", "341bb97e"], "d": ["Акча Коджа, один із прикордонних беїв Орхана Газі, здійснюючи набіги на околиці Ізміта зі своєї ставки на захід від озера Сапанджа, близько 1326 року захопив Кандиру та її околиці. Ізміт тоді ще був у руках Візантії; місто впаде лише 1337 року.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Приєднання Ялови та Карамюрселя", "133cb07a"], "d": ["Того року Ялова та її околиці на південному узбережжі Ізмітської затоки перейшли в руки турків; прибережну смугу Орхан-бей віддав як тімар Карамюрселу Ґазі.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Акча Коджа взяв Айдос і замок Самандира", "ce4daa8a"], "d": ["Після взяття Кандири Акча Коджа разом із Конуралпом і Ґазі Абдуррахманом взяв фортецю Айдос поблизу Картала, а потім замок Самандира на північ від неї; Самандирський край віддали йому у власність. Акча Коджа помер 1328 року поблизу Кандири; прикордонне бейство краю передали шехзаде Мураду.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Союз османів, Айдинідів і Саруханідів", "9df6bb74"], "d": ["Три бейліки діяли спільно проти Візантії; флот Умур-бея з роду Айдинідів набігами на фракійське узбережжя виснажував Візантію на другому фронті.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Завоювання Гемліка (Кіоса)", "66fc4bcd"], "d": ["Прибережне місто Гемлік (Кіос) біля Гемлікської затоки, що виходить у Мармурове море, перейшло в руки османів. Коли 1326 року здалася Бурса, міського текфура з родиною відіслали до Гемліка; отже, 1326 року Гемлік ще був у руках Візантії. Окремої дати для Армутлу не знайдено; його прив'язано до ланцюга Гемліка.", "27ef02f4"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Шлюб Орхана Газі та Феодори: візантійський союз", "9b67a590"], "d": ["Орхан Газі, який підтримав Кантакузина в боротьбі за візантійський престол, одружився з його донькою Феодорою; цей союз дав османським силам змогу ближче ознайомитися з Румелією.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Взяття Анкари", "49bf1f6d"], "d": ["Анкара, якою управляли ахі, перейшла під османське управління; відкрився шлях у Центральну Анатолію. Інші місця, приєднані тоді ж: Сіврігісар, Чанкири.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Просування у Фракії за часів Сулеймана-паші: Малкара, Іпсала та Текірдаг", "fb31cf02"], "d": ["Створивши плацдарм у Галліполі, Сулейман-паша, вийшовши з півострова на північ, крок за кроком захопив рівнину між узбережжям Мармурового моря та гирлом Мариці. Так Малкара, Іпсала та Родосчук (Текірдаг) утворили нерозривний коридор, що з'єднував Галліполі з долиною Мариці. Без цього коридору на Едірне йти було неможливо; просування, що зупинилося через раптову смерть царевича 1357 року, продовжать Лала Шахін і Хаджі Ільбей.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Викрадення шехзаде Халіля", "b52ac3d7"], "d": ["Молодшого сина Орхана Газі, Халіля, викрали фокейські пірати; криза з викупом роками займала османо-візантійські відносини.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Перерізання шляхів допомоги Едірне: фортеці Чорлу, Люлебургаз, Бабаескі та Кешан", "8e8ad485"], "d": ["Шехзаде Мурад, відновивши завойовницький похід після визволення Халіля, щоб ізолювати Едірне від можливої допомоги ззовні, послав акинджі аж під Константинополь. Було захоплено фортеці Чорлу, Люлебургаз і Бабаескі на дорозі Константинополь—Едірне та Кешан на дорожньому вузлі Південної Фракії. Здача Едірне настала після того, як це кільце облоги було завершене.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Взяття Дімотіки — відкриття долини Мариці", "b59aee83"], "d": ["Було взято Дімотіку (Дідімотіхо), ключову фортецю долини Мариці; так відкрився шлях до завоювання Едірне. Іти на Едірне, не завершивши коридор, що тягнувся на північ від Галліполі, було неможливо, тому в послідовності румелійських завоювань ця фортеця передує Едірне. Місто на певний час стало румелійською ставкою султанів. Сили, що взяли Дімотіку, згодом разом із невеликими фортецями, як-от Кулелі-Бурґаз (Піфіон), узяли під контроль увесь район середньої Мариці.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Втрата Галліполі (Савойський хрестовий похід)", "00e7e415"], "d": ["Флот Амадея Савойського, кузена візантійського імператора, взяв Галліполі й передав його Візантії; османським плацдармом у Румелії десять років керували з того боку протоки. Інші поселення, втрачені тоді ж: Чимпе.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Битва під Чірменом — контроль над долиною Мариці", "cd738d8d"], "d": ["Військо сербських володарів було розігнане нічним нападом; місцеві сербські та болгарські володарі в Македонії та Родопах один за одним почали платити данину османам — це був початок не прямого завоювання, а хвилі васалізації. В османській традиції цю битву оповідають також під назвою «Сирпсиндиґи» та під 1364 роком як нічний напад Хаджі Ільбея на військо хрестоносців, що прийшло повернути Едірне; TDV зазначає, що ця дата помилкова і що обидві оповіді стосуються тієї самої битви.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Завоювання Пловдива та Старої Загори", "e780c9ae"], "d": ["Було взято Пловдив у горішній частині долини Мариці та Стару Загору на північ від нього; Болгарське царство зробили данником. Шлях Татарпазарджик—Іхтіман між Пловдивом і Софією залишився в руках місцевих володарів, які після Чірмена стали васалами. Інші поселення, втрачені тоді ж: Хасково, Клокотниця.", "019bac28"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Васальна Візантія: Іоанн V у війську Мурада I (наслідок перемоги під Чірменом 1371 року)", "13ffe568"], "d": ["За TDV, після перемоги під Чірменом (на Мариці) 26 вересня 1371 року Візантійська імперія визнала османську владу і, погодившись платити данину та служити в османському війську, опинилася в становищі васальної держави. Імператор Іоанн V за цим зобов'язанням 1373 року приєднався до війська Мурада I; його син Андронік IV, якого він тоді залишив у Константинополі, разом із шехзаде Савджі-беєм із Бурси повстав проти своїх батьків.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Повернення Галліполі", "5f96c0a5"], "d": ["Андронік IV, який у боротьбі за візантійський престол дістав османську підтримку, натомість повернув Галліполі; міст між Румелією та Анатолією було відновлено. Інші місця, приєднані тоді ж: Чимпе.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Ґерміянський посаг: приєднання Кютах'ї", "d6a6fe61"], "d": ["Під час шлюбу Девлетшах-хатун, доньки ґерміянського Сулейман-шаха, з Баязидом Блискавичним Кютах'я, Сімав, Тавшанли та Еґріґьоз перейшли до османів як посаг — класичний приклад розширення без війни. Інші місця, приєднані тоді ж: Афьон.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Купівля Гамідської землі: приєднання Іспарти", "4a1b6047"], "d": ["Гамідський Хусейн-бей продав частину свого бейліку (Акшехір—Бейшехір—Іспарта) Мураду I за готівку; решту Гамідської землі 1391 року анексує Йилдирим. Інші поселення, втрачені тоді ж: Ісхакли.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Завоювання Серреса", "d4d28b60"], "d": ["Було взято Серрес, ключ до Східної Македонії; Салоніки потрапили в облогове кільце. Лінія Кюстендил—Петрич—Неврокоп—Драма між Софією та Серресом на цю дату ще не була прямо приєднана: вона послідовно перейшла у васалітет у 1370-х—1383 роках, а після 1383 року — під пряме управління. Інші поселення, втрачені тоді ж: Гевгелія, Кілкіс (Авратхісар).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Завоювання Софії", "96d5f01f"], "d": ["Західні перевали Балканських гір було взято під контроль; оскільки на цю дату Серрес перебував під владою вже з 1383 року, землі Фракії та Македонії утворювали нерозривне ціле.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Завоювання Ніша", "77f5d632"], "d": ["Зі взяттям Ніша, замка долини Морави, Сербська деспотовина опинилася під прямою загрозою.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Перша здача Салонік", "96010ee9"], "d": ["Після тривалої блокади місто здалося (1403 року його повернуть Візантії, а 1430 року остаточно завоюють). Інші місця, приєднані тоді ж: Кавала. Інші поселення, втрачені тоді ж: Лангадас, Елефтеруполіс (Правіште).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Османо-генуезька ахіднаме — поновлення договору 1352 року", "be11d17a"], "d": ["З генуезькими послами з Пери було поновлено торговельну угоду 1352 року, укладену ще за Орхана Газі; податки між двома державами, поводження з полоненими та вільну торгівлю визначили наново. Це вважають першою офіційно відомою ахіднаме дружби й торгівлі між османами та генуезцями — не військовим союзом, а суто торговельною угодою.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Болгарський похід Чандарли Алі-паші: взяття Шумена та Русе", "2781c3a9"], "d": ["Фортеці Болгарського царства вздовж Дунаю було прийнято під владу за один похід; його не слід плутати з поразкою під Білечею в Боснії того ж року — це був одночасний успіх на іншому фронті. Тирново та Відін були останніми болгарськими центрами, що ще трималися.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Поразка під Білечею", "89ba0a64"], "d": ["Загін акинджі, що рушив на Боснію, потрапив у засідку під Білечею та був знищений; ця перша велика балканська невдача підбадьорила союз, що привів до Косова.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Анексія західноанатолійських бейліків: Саруханідів, Айдинідів, Ментеше", "dcc33b71"], "d": ["Три бейліки було приєднано за один раз: осередок Саруханідів — Манісу; осередок Айдинідів — Айдин (разом із верхньою фортецею Ізміра, але портова, нижня, фортеця все ще залишалася в лицарів святого Іоанна — до 1402 року); осередок Ментеше — Муглу та Мілас разом із прибережною смугою Датча—Бодрум—Мармарис—Фетхіє. Егейське узбережжя вперше опинилося в одних руках. Інші місця, приєднані тоді ж: Сьоке.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Анексія землі Теке: приєднання Анталії", "fdbeee5c"], "d": ["Землю Теке на середземноморському узбережжі приєднали до османських земель. Текеїди — це гілка, що відокремилася від Гамідидів: Фелекюддін Дюндар-бей залишив завойовану ним Анталію своєму братові Юнусу-бею, і близько 1321 року виник окремий бейлік. Тому після 1321 року Анталію та її околиці на карті показано не кольором Гамідидів, а кольором Текеїдів. Після Анкарської битви бейлік відновили, і остаточно його ліквідували лише 1423 року.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Завоювання Скоп'є", "9e5a1af5"], "d": ["Було взято осередок Вардарської Македонії; Скоп'є стало одним із головних прикордонних центрів Румелії.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Анексія Кастамону", "876330ba"], "d": ["Кастамонську гілку роду Джандаридів було ліквідовано; синопська гілка залишилася васалом. Інші місця, приєднані тоді ж: Бартин, Сафранболу, Акчакоджа, Деврек, Ефлані, Караденіз-Ереглі, Тосья.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Падіння Тирнова — анексія Болгарії", "ff666977"], "d": ["Столиця Болгарського царства впала; Болгарія перейшла під пряме османське управління. Інші місця, приєднані тоді ж: Плевен, Ловеч, Габрово.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Фортеця Ловеч перейшла до османів", "a55e87a0"], "d": ["Ловеч, одну з фортець болгарського царя Івана Шишмана, під час походу 1393 року, у якому впало Тирново, разом з іншими провінціями Шишмана приєднали до османських земель. Джерело не говорить напевно: вважають, що завоювання припало на цей рік.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Приєднання Добруджі", "478e36f2"], "d": ["Було приєднано землі Добруджі, що тягнуться до дельти Дунаю. Інші місця, приєднані тоді ж: Силістра, Констанца, Бабадаг, Балчик, Хиршова, Тулча, Мангалія, Ісакча, Тутракан, Мечин, Кючук-Кайнарджа.", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Спуск у Фессалію", "8bec60dd"], "d": ["Фессалійську рівнину з осередком у Ларисі (Єнішехірі) взяли під османське управління. Інші місця, приєднані тоді ж: Трикала, Ламія (Іздін).", "d9f2128c"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Битва при Ровіне — волоський похід", "343ae7a9"], "d": ["Після кривавої битви з волоським воєводою Мірчею, наслідок якої є спірним, Волощина погодилася платити данину османам; на північ від Дунаю встановився порядок васалітету.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Завоювання Нікополя", "b9791717"], "d": ["Після битви при Ровіне проти волохів 1395 року Баязид Блискавичний узяв фортецю Нікополь на березі Дунаю; деякі анонімні болгарські хроніки зазначають, що завоювання відбулося 3 червня 1395 року. Дата завоювання в джерелах не одностайна: стаття про битву під Нікополем в «Енциклопедії ісламу» TDV повідомляє, що Баязид захопив Силістру та Нікополь під час дунайського походу 1394 року. 1396 року фортецю візьмуть в облогу під час знаменитого хрестового походу, але вона не впаде. Інші місця, приєднані тоді ж: Охрид.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Фортеця Нікополь переходить до османів", "327012c9"], "d": ["Після наскоку при Ровіне Баязид Блискавичний узяв Нікополь; болгарського царя Івана Шишмана, який сидів там як османський васал, усунули. В атласі Нікополь із цього дня позначено як такий, що перейшов від Болгарського царства до османів.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Будівництво Анадолу-Хісари", "aa259b00"], "d": ["Щоб підтримати блокаду Константинополя, на анатолійському боці Босфору збудували Ґюзельджехісар (Анадолу-Хісари) — перший постійний крок до контролю над протокою.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Анексія Відіна", "ee1ae44b"], "d": ["Після перемоги під Нікополем анексували також Відін, останнє болгарське князівство.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Перша анексія Карамана", "3cf07876"], "d": ["Завдяки перемозі при Акчаї землі Караманідів уперше приєднали до Османської держави (під час міжцарів'я вони відновляться).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Приєднання узбережжя Джаніка: Самсун", "af9c40fa"], "d": ["У вакуумі, що утворився, коли Каді Бурханеддін потрапив у полон до Караюлюка Османа-бея з Ак-Коюнлу, Баязид Блискавичний спершу підпорядкував османському управлінню край Джанік на чорноморському узбережжі. Так Самсун і його околиці стали першим чорноморським портом династії. Лінію Сівас—Токат—Кайсері у внутрішніх землях приєднають через два тижні з фактичним розпадом держави Каді Бурханеддіна.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Взяття Малатьї", "7cb6ae16"], "d": ["Було захоплено Малатью на мамлюцькому кордоні — один із кроків, що загострили напруження з Тимуром.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Тимур узяв Малатью й залишив її Караюлюку Осману — коли Тимур відійшов, її повернули Дулкадириди", "ad2ce7d8"], "d": ["Баязид Блискавичний, залишивши взяту 1399 року Малатью Насреддіну Мехмеду з роду Дулкадиридів, повернувся до Бурси. Тимур, який вступив в Анатолію 1400 року, взяв спершу Сівас та Ельбістан, а потім Малатью; місто та околиці пограбували, а управління ними залишили Караюлюку Осману, що перебував при Тимурі. Коли Тимур відійшов із краю, над Малатьєю знову запанували Дулкадириди; так османське панування скінчилося ще до Анкари.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Договір Сулеймана Челебі з Візантією: повернення Салонік", "cc503cc2"], "d": ["Сулейман Челебі, який під час міжцарів'я правив Румелією, за угодою з Візантією та латинськими державами віддав Візантії Салоніки та чорноморське узбережжя аж до Месемврії (TDV fetret-devri: Галліпольський договір, лютий 1403) — на карті Іґнеада, Резово та Ахтопол переходять до Візантії; на карті Салоніки від цієї дати виходять з-під влади османів.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Морська поразка під Галліполі (Венеція)", "b71d4d68"], "d": ["Венеційський флот завдав під Галліполі тяжкої поразки османському флоту; ця подія показала межі раннього османського мореплавства.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Повстання Дюзмедже Мустафи", "0ec43138"], "d": ["Мустафа Челебі, який видавав себе за сина Йилдирима, за підтримки Візантії проголосив себе султаном у Румелії; Мурад II придушив повстання 1422 року й наказав стратити суперника.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Облога Константинополя Мурадом II", "4b9d9fba"], "d": ["У відповідь на те, що Візантія підтримала Дюзмедже Мустафу, Мурад II обложив Константинополь; облогу зняли, коли в Анатолії підняли повстання його брата Кючюка Мустафи.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Передання Салонік Венеції", "bfa6c4a0"], "d": ["Візантійський намісник під тиском османів передав місто Венеції; почалося османо-венеційське суперництво, що триватиме сім років.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Повторна анексія західноанатолійських бейліків: Ментеше та Айдин", "aca30a48"], "d": ["Два егейські бейліки, відновлені під час міжцарів'я, за Мурада II остаточно приєднали до османських земель. За статтею TDV про Ментеше, Мурад II захопив землю Ментеше 827 (1424) року й ув'язнив двох братів, що стояли на чолі бейліку. За статтею ж про Айдинідів, бейлербей Анатолії Хамза-бей наказав схопити Джюнейда-бея, який знову вийшов із покори, і стратити його разом із родиною (829/1425-26), а землю Айдин перейшла до османів. Лицарі святого Іоанна, які з 1344 року тримали портову фортецю Ізміра, 1402 року втратили її на користь Тимура, і край повернувся під контроль Айдинідів; з цією анексією він також приєднався до османів. Земля Теке (Анталія) не є предметом цього запису: Текеїдів ліквідували окремо 1423 року. Ґерміян же приєднають 1429 року за заповітом.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Анексія Ґерміяну за заповітом", "9eb86b77"], "d": ["Ґерміянський бей Якуб II, який помер бездітним, заповів свою країну османам — хрестоматійний приклад анексії без війни. Інші місця, приєднані тоді ж: Карахісар-і Сахіб (Афьон).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Остаточне завоювання Салонік", "bc021768"], "d": ["Місто, що перебувало під венеційським управлінням, взяли штурмом; другий великий порт Румелії остаточно став османським. Інші місця, приєднані тоді ж: Кассандра (Кесендіре).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Здача Яніни", "ee45cb52"], "d": ["Яніна, осередок Епіру, здалася за угодою.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Перше взяття Смедерева", "c11ca17d"], "d": ["Після тримісячної облоги взяли столицю Сербської деспотовини, і Сербію вперше анексували (її повернуть за Едірнсько-Сеґедським договором 1444 року).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Облога Белграда (невдала)", "3e05f425"], "d": ["Перша велика облога Белграда, що тривала шість місяців, не дала результату; вісімдесят років фортеця залишалася замком на шляху османського просування.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Розгром під Златицею — «Довгий похід»", "97df1466"], "d": ["Військо, яке Гуняді посеред зими ввів на Балкани, пройшло Ніш і Софію та підступило до Златиці; османська оборона ледве встояла. Ця атмосфера розгрому посадила за стіл переговорів щодо Едірнсько-Сеґедського миру.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Едірнсько-Сеґедський договір", "0aa4e0de"], "d": ["Десятирічний мир: Сербську деспотовину відновили, Дунай визнали кордоном. Порушення договору за кілька місяців під підбурюванням папства призвело до катастрофи під Варною.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Повернення Смедерева та сербських фортець Сербії", "cda3cf9e"], "d": ["Положення Едірнсько-Сеґедського договору набуло чинності: 15 серпня 1444 року Мурад II повернув Юрію Бранковичу Смедерево разом із двадцятьма чотирма важливими фортецями та іншими окупованими сербськими землями (TDV semendire); Ніш (TDV nis), Аладжахісар (TDV alacahisar), Шехіркьой (TDV sehirkoy) і Приштину (TDV pristine) також залишили сербам. Відін, не будучи сербською землею, не увійшов до повернення — звідси та північно-західна територіальна втрата, яку видно на карті приблизно в час Варненської перемоги; через кілька місяців із розгромом під Варною договір і так втратить чинність.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Румелі-Хісари завершено — «Перерізувач протоки» (Боґазкесен)", "480e8a76"], "d": ["Із фортецею, яку, за джерелами, звели надзвичайно швидко — за чотири-п'ять місяців, — контроль над Босфором повністю перейшов до османів; шлях допомоги Константинополю з Чорного моря закрився. Це вважають фактичним першим кроком облоги.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Почалася облога Константинополя", "8af50742"], "d": ["Військо стало перед мурами; під час облоги, що триватиме 54 дні, велетенські гармати вперше систематично застосували проти мурів столиці.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Кораблі суходолом спустили в Золотий Ріг", "4f2ba07c"], "d": ["Близько 70 кораблів флоту, який не міг увійти в Золотий Ріг, перегороджений ланцюгом, перетягли на змащених жиром полозах через узгір'я Ґалати й за одну ніч спустили в Золотий Ріг; оборону було розділено на два фронти.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Завоювання Афін", "4f0f1bb2"], "d": ["Афінське герцогство припинило існування; на Акрополі підняли османський прапор. Інші місця, приєднані тоді ж: Фіви (Істефе), Лівадія.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Анексія Сербії (падіння Смедерева)", "75fd0a62"], "d": ["Смедерево, столиця Сербської деспотовини, здалося; Сербія стала османським санджаком.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Завоювання Мореї", "7d5a3c18"], "d": ["Морейський деспотат ліквідували; півострів (крім венеційських фортець) перейшов під османське управління.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Приєднання Синопа", "e03c2739"], "d": ["Джандаридський правитель Синопа здався без бою; відкрився шлях для Трапезундського походу. Інші місця, приєднані тоді ж: Кастамону, Бартин, Сафранболу. Стаття TDV про Джандаридів називає серед земель бейліку Джандаридів, анексованих 1461 року, також Болу, Ефлані та Тосью; в атласі ці три місця того ж дня записані як такі, що перейшли від Джандаридів до османів. Інші поселення, втрачені тоді ж: Караденіз-Ереглі, Деврек, Акчакоджа (землі Джандаридів).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Падіння Боснійського королівства — боснійський похід Фатіха", "5362e3f2"], "d": ["Коли останній боснійський король Стефан Томашевич (1461-1463), покладаючись на підтримку Заходу, відмовився платити данину, його стали вважати таким, що перестав бути залежним правителем, і військо під проводом султана Мехмеда Фатіха ліквідувало Боснійське королівство за один похід. Короля схопили та стратили, королівство зникло, а в краї утворили Боснійський санджак. Проте падіння королівства — не те саме, що завоювання Боснії. Османське управління в рівнині існувало вже п'ятнадцять років: Ходидєд і Сараєвську рівнину взяли 1448 року, а прикордонне бейство Іси-бея виникло посеред королівства. Завоювання не скінчилося й 1463 року: Фочу взяли 1465-го, Ливно — 1469-го, Герцогство Герцеговину — 1483-го, Сребреницький банат — 1512-го, а Яйце й Баню-Луку на півночі вдалося взяти лише 1528 року, після Мохача: угорці створили на півночі Боснії банат, який протримався шістдесят п'ять років після 1463-го. На цю дату прямо змінило власника місце Травнік; Яйце ж на цю дату перейшло не до османів, а до Угорщини.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Остаточна анексія Карамана", "f1dcecaa"], "d": ["Центральні землі Караманідів остаточно приєднали; внутрішні чвари тривали до 1470-х років. Інші місця, приєднані тоді ж: Ніґде, Мостар, Бейшехір.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Завоювання Негропонта", "5c97daf3"], "d": ["Негропонт (Еґрібоз), головна база Венеції в Егейському морі, впав.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Анексія Аланьї, Анамура та Силіфке (Ічеля)", "a0b9d461"], "d": ["Прибережну смугу Ічель, залежну від Караманідів (усе середземноморське узбережжя між Анталією та Мерсіном), приєднали морським походом Ґедіка Ахмеда-паші; Аланья була важлива своєю стратегічною верф'ю сельджуцьких часів.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Приєднання Новгорода до Москви", "bed87170"], "d": ["Великий князь Іван III зняв символічний дзвін новгородського віча, замінив місцевих урядників своїми намісниками й фактично підпорядкував місто Москві; Новгород перестав бути незалежною республікою. Новгородська земля тяглася від Балтійського моря до Білого моря та Уралу. В атласі Новгород із цього дня позначено як такий, що перейшов від Новгородської республіки до Москви.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Стамбульський договір — Албанія та Шкодер", "b09652f7"], "d": ["16-річна османо-венеційська війна скінчилася; Шкодер та албанське узбережжя залишилися за османами. Інші місця, приєднані тоді ж: Лемнос, Самос, Бозбаба (Айос-Евстратіос).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Висадка в Отранто", "7916b89d"], "d": ["Османські сили, що висадилися на узбережжі Апулії (Пульї), взяли в облогу й захопили фортецю Отранто; оскільки в місто увірвалися з боєм, частину знатних людей, які чинили опір, стратили, а частину взяли в полон. Церковна традиція вшановує загиблих як «отрантських мучеників» — близько 800 осіб; TDV пов'язує перебільшення цього числа з церковною пропагандою. Утримали лише фортецю на краю півострова Саленто та вузькі її околиці; решту земель Неаполітанського королівства на лінії Таранто—Бриндізі—Лечче втрачено не було — цей плацдарм, що відкривав шлях в Італію, проіснує рік.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Евакуація Отранто", "37371bb0"], "d": ["Гарнізон Отранто, який після смерті султана Мехмеда Фатіха (3 травня 1481) не мав надії на нове підкріплення, під облогою неаполітанського спадкоємця Альфонсо за угодою залишив фортецю; так єдиний османський плацдарм в Італії було втрачено через рік.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Завоювання Модона та Корона", "38b608c4"], "d": ["Було взято Модон і Корон, «два ока» Венеції в Мореї.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Завоювання Дурреса", "1f231b98"], "d": ["Під час османо-венеційської війни 1499-1503 років сили під командуванням Мехмеда-бея взяли Дуррес (Драч), останній великий албанський порт Венеції на Адріатиці. Після Шкодера (1479) та Вльори (1417) із цим завоюванням албанська прибережна смуга повністю перейшла під османський контроль.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Приєднання Східної Анатолії", "e0cb8f8f"], "d": ["Після Чалдирана приєднали Діярбакир та його околиці; курдські бейліки через Ідріса Бітлісі підпорядкувалися османам.", "025d3ddc"]}
});
